local config = {
  ui_story_5040_50400101_1_dialog_content = "(Ahh... Liburan sulit didapat...)",
  ui_story_5040_50400101_2_dialog_content = "(Tidak, tenangkan dirimu!)",
  ui_story_5040_50400101_3_dialog_content = "\"(Bip) 3 hari sampai <color=#FFB400>Hari Mahkota Bulan</color>.\"",
  ui_story_5040_50400101_4_dialog_content = "\"Mooncrown Day adalah hari libur tradisional di Astra. Ini adalah hari bagi pasangan untuk mengungkapkan cinta mereka, dan hari yang populer untuk pernikahan.\"",
  ui_story_5040_50400101_5_dialog_content = "Aku sudah tahu! Jika saya tidak begitu sibuk sehingga saya melewatkannya tahun lalu, saya tidak akan—",
  ui_story_5040_50400101_6_dialog_content = "Ngomong-ngomong, aku harus membeli kembali pemutar rekaman yang diembos itu, yang diinginkan oleh Vice dan Carleen. Itu akan menjadi kejutan liburan yang menyenangkan!",
  ui_story_5040_50400101_7_dialog_content = "(Mereka baru-baru ini mengatakan bahwa mereka bermaksud untuk istirahat sebentar, dan saya tidak tahu ke mana mereka pergi. Terserah, saya harus melakukannya sendiri!)",
  ui_story_5040_50400101_8_dialog_content = "PlayerName, sudah lama. Ada yang bisa saya bantu?",
  ui_story_5040_50400101_9_dialog_content = "Maaf, tapi Serikat Kurir kewalahan dengan festival yang akan datang, jadi saya tidak punya waktu untuk mengobrol.",
  ui_story_5040_50400101_10_dialog_content = "Belum lagi rekan saya di divisi Rediesel Wrench mengacaukan banyak surat menuju Lumopolis...",
  ui_story_5040_50400101_11_dialog_content = "Whoa... Ada yang bisa saya bantu?",
  ui_story_5040_50400101_12_dialog_content = "Saya ingin membeli sesuatu untuk liburan, jadi saya bekerja serabutan untuk mendapatkan uang.",
  ui_story_5040_50400101_13_dialog_content = "Saya tidak benar-benar ingin mengganggu Anda lagi, terutama karena Anda membantu Tweety terakhir kali.",
  ui_story_5040_50400101_14_dialog_content = "Tapi karena Anda bertanya, ada satu hal. Apakah Anda pikir Anda bisa mampir ke divisi Rediesel Wrench?",
  ui_story_5040_50400101_15_dialog_content = "Seorang teman lama dari Northland akan menikah pada Hari Mahkota Bulan, sama seperti banyak orang lainnya.",
  ui_story_5040_50400101_16_dialog_content = "Hanya saja tunangannya mengalami sedikit kecelakaan di Gurun Rediesel beberapa waktu lalu, dan mereka khawatir tidak akan ada cukup waktu untuk sampai ke Northland begitu dia pulih.",
  ui_story_5040_50400101_17_dialog_content = "Dan Anda ingin meminjam Colossus untuk memastikan dia sampai di sana, bukan? Tidak masalah, itu mudah dilakukan.",
  ui_story_5040_50400101_18_dialog_content = "(Berbicara tentang pernikahan temannya, bukankah Naroxel akan pergi sendiri?)",
  ui_story_5040_50400101_19_dialog_content = "(Pokoknya, sebaiknya selalu tanyakan detailnya kepada orang yang terlibat. Ini pasti divisi Rediesel Wrench.)",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>Ketuk, ketuk—</color>",
  ui_story_5040_50400101_21_dialog_content = "Permisi...",
  ui_story_5040_50400101_22_dialog_content = "Anda harus menjadi Caelestite muda di sini untuk membantu! Aku sudah menunggumu!",
  ui_story_5040_50400101_23_dialog_content = "Saya pikir Anda akan sampai di sini lebih awal, seperti Naroxel selalu berbicara tentang seberapa cepat Colossus itu.",
  ui_story_5040_50400101_X23_dialog_content = "(A-Ular yang sangat besar! Apakah benda ini Pembicara!? Sungguh menakjubkan!)",
  ui_story_5040_50400101_X24_dialog_content = "(Dan kantor ini... Halus biasanya bukan gaya Rediesel Wrench.)",
  ui_story_5040_50400101_24_dialog_content = "(Wow, kantor ini... Penyempurnaan biasanya bukan gaya Rediesel Wrench.)",
  ui_story_5040_50400101_25_dialog_content = "Senang bertemu dengan mu. Saya PlayerName, di sini atas nama Naroxel.",
  ui_story_5040_50400101_26_dialog_content = "Siapa kalian?",
  ui_story_5040_50400101_27_dialog_content = "Anda lebih muda dari yang saya bayangkan. Bagaimanapun, izinkan saya memperkenalkan diri.",
  ui_story_5040_50400101_28_dialog_content = "Saya <color=#FFB400>Jeriah</color>, Anggota Senior Divisi Wrench Rediesel Serikat Kurir. Ini <color=#FFB400>Tara</color>, klien kami untuk tugas ini.",
  ui_story_5040_50400101_29_dialog_content = "Hai, saya Tara! Saya tidak pernah menyangka akan bertemu Caelestite yang legendaris. Apa keberuntungan!",
  ui_story_5040_50400101_30_dialog_content = "Aku tersanjung! Apakah Anda ikut dengan kami ke Northland juga, Nona Jeriah?",
  ui_story_5040_50400101_31_dialog_content = "Hanya Yeriah yang akan melakukannya. Heheh, ada kekacauan dengan surat, dan aku tidak punya pilihan selain meminta bantuan Naroxel.",
  ui_story_5040_50400101_32_dialog_content = "Jadi saya akan mewakilinya sebagai saksi pernikahan.",
  ui_story_5040_50400101_33_dialog_content = "(Aku ingin tahu apakah dia rekan yang disebutkan Naroxel siapa yang bertanggung jawab atas keributan surat?)",
  ui_story_5040_50400101_34_dialog_content = "Saksi? Saya mendengar bahwa seseorang dari Courier Union menghadiri pernikahan membawa keberuntungan bagi pengantin baru.",
  ui_story_5040_50400101_35_dialog_content = "Tentu! Tidak mudah menemukan kurir untuk pernikahan di Mooncrown Day. Naroxel harus meminta bantuan hanya untuk kami!",
  ui_story_5040_50400101_36_dialog_content = "Apakah Naroxel benar-benar sangat sibuk sehingga dia tidak bisa mendapatkan satu hari pun libur?",
  ui_story_5040_50400101_37_dialog_content = "Periode sebelum dan sesudah Hari Mooncrown selalu menjadi waktu tersibuk bagi Serikat Kurir, dengan segala jenis undangan dan surat bertebaran.",
  ui_story_5040_50400101_38_dialog_content = "Waktu yang tepat bagi Jeriah yang cantik untuk \"secara tidak sengaja\" mengacaukan banyak paket yang menuju Northland.",
  ui_story_5040_50400101_39_dialog_content = "Saya membayangkan Anda mengundang teman Caelestite kami ke sini untuk hal-hal yang lebih penting daripada mengolok-olok saya. Mari kita pergi. Apakah kamu tidak merindukan tunanganmu?",
  ui_story_5040_50400101_40_dialog_content = "Ide bagus. Secepat Colossus itu, sebaiknya kita berangkat secepatnya.",
  ui_story_5040_50400101_41_dialog_content = "Wow! Colossus Anda sangat berbeda dari Kadal Raksasa!",
  ui_story_5040_50400101_42_dialog_content = "Haha, tunggu saja sampai Anda naik.",
  ui_story_5040_50400101_43_dialog_content = "Omong-omong, pengantin Gurun dan pengantin pria Northlander adalah pasangan yang menarik. Apakah serikat lintas negara semacam ini umum?",
  ui_story_5040_50400101_44_dialog_content = "Hmm, yah... Menurutku mereka sangat langka!",
  ui_story_5040_50400101_45_dialog_content = "Dunia adalah tempat yang besar dan segala sesuatu mungkin terjadi. Tapi bagi orang Aurorian, ini agak aneh.",
  ui_story_5040_50400101_46_dialog_content = "Wow, benarkah?",
  ui_story_5040_50400101_47_dialog_content = "Nak... Jeriah, kamu dari Gurun Rediesel juga?",
  ui_story_5040_50400101_48_dialog_content = "Saya tidak suka mengakuinya, tapi itu benar.",
  ui_story_5040_50400101_49_dialog_content = "Ini cukup aneh bagaimana Anda jelas lahir dan dibesarkan di gurun, namun Anda tampaknya tidak memiliki banyak teman di Rediesel Wrench.",
  ui_story_5040_50400101_50_dialog_content = "Saya harus meminta banyak orang hanya untuk menemukan kantor Anda.",
  ui_story_5040_50400101_51_dialog_content = "Nah sekarang, setiap orang menempuh jalan hidup mereka sendiri.",
  ui_story_5040_50400101_52_dialog_content = "Bagaimanapun, kisah hidup saya tidak masalah. Anda adalah bintang pertunjukan hari ini.",
  ui_story_5040_50400101_53_dialog_content = "Itu benar! Aku belum pernah bertemu calon pengantin sebelumnya!",
  ui_story_5040_50400101_54_dialog_content = "Ini bukan masalah besar. Kami para penghuni gurun cukup berpikiran terbuka dalam hal cinta.",
  ui_story_5040_50400101_55_dialog_content = "Ngomong-ngomong, kita tidak punya banyak waktu, jadi aku benar-benar ingin melihat-lihat Colossus.",
  ui_story_5040_50400101_56_dialog_content = "Bawa saya dalam tur, PlayerName!",
  ui_story_5040_50400101_57_dialog_content = "Baiklah. Tunggu aku!",
  ui_story_5040_50400101_58_dialog_content = "Ini mungkin terdengar buruk, tapi menurutku Tara tidak terlalu... seperti pengantin wanita.",
  ui_story_5040_50400101_59_dialog_content = "Setiap orang punya gayanya masing-masing, Caelestite kecil. Tidak baik bergosip di belakang orang.",
  ui_story_5040_50400101_60_dialog_content = "Ya, saya kira Anda benar.",
  ui_story_5040_50400101_61_dialog_content = "(Jeriah tampaknya benar-benar acuh tak acuh tentang pernikahan...)",
  ui_story_5040_50400101_62_dialog_content = "Fiuh! Kami akhirnya di sini.",
  ui_story_5040_50400101_63_dialog_content = "Apakah Tara pergi mencari tunangannya? Saya ingat melihat apa yang tampak seperti sebuah desa di dekatnya.",
  ui_story_5040_50400101_64_dialog_content = "Kota Asal, di perbatasan Northland. Mayoritas masyarakat disana adalah masyarakat tradisional, dan mengadakan upacara pernikahan mereka di pura.",
  ui_story_5040_50400101_65_dialog_content = "Haruskah kita menuju ke sana?",
  ui_story_5040_50400101_66_dialog_content = "Saya pikir keduanya mungkin ada di tempat lain sekarang.",
  ui_story_5040_50400101_67_dialog_content = "(Sekarang klien sudah diantar, apakah saya perlu tinggal untuk pernikahan itu sendiri??)",
  ui_story_5040_50400101_68_dialog_content = "Apakah Anda bertanya-tanya apakah Anda dapat kembali sekarang?",
  ui_story_5040_50400101_69_dialog_content = "(Dia membaca saya seperti buku.)",
  ui_story_5040_50400101_70_dialog_content = "Melihatmu sebagai teman Naroxel, mereka pasti akan mengundangmu ke pesta pernikahan.",
  ui_story_5040_50400101_71_dialog_content = "Bagaimanapun, Anda sudah ada di sini. Meskipun pernikahan di Northland mungkin tidak semeriah pernikahan di Lumopolis, pernikahan tersebut tentu memiliki karakternya sendiri.",
  ui_story_5040_50400101_72_dialog_content = "Poin bagus. Omong-omong, Anda tampaknya sangat akrab dengan Northland untuk seseorang yang berasal dari Divisi Wrench Rediesel.",
  ui_story_5040_50400101_73_dialog_content = "Bukan hanya Northland! Dia tahu segalanya yang perlu diketahui tentang dunia, kecuali hal-hal yang berkaitan dengan pekerjaan.",
  ui_story_5040_50400101_74_dialog_content = "Ahaha, kamu kembali! Dimana mempelai pria?",
  ui_story_5040_50400101_75_dialog_content = "Tara?",
  ui_story_5040_50400101_76_dialog_content = "Maaf telah membuatmu menunggu...!",
  ui_story_5040_50400101_77_dialog_content = "Kamu benar-benar slowpoke—",
  ui_story_5040_50400101_78_dialog_content = "Ini Jeriah dari Divisi Kunci Pas Rediesel Serikat Kurir. Aku memberitahumu tentang dia.",
  ui_story_5040_50400101_79_dialog_content = "Dan ini adalah orang yang membawa kita ke sini! Bertemu PlayerName, seorang Caelestite! Colossus itu benar-benar sesuatu.",
  ui_story_5040_50400101_80_dialog_content = "Dia <color=#FFB400>Adonis</color>, tunanganku... Eh, agak aneh mengatakan itu. Saya biasanya hanya menggunakan namanya.",
  ui_story_5040_50400101_81_dialog_content = "Senang bertemu dengan Anda berdua, Nona Jeriah, PlayerName.",
  ui_story_5040_50400101_82_dialog_content = "Maaf untuk terburu-buru hari ini. Naroxel adalah teman lamaku dari sekolah. Dia selalu ada untuk membantu dalam keadaan darurat.",
  ui_story_5040_50400101_83_dialog_content = "Jika Anda memberi saya kehormatan untuk hadir, PlayerName, kami juga ingin Anda hadir di pesta pernikahan.",
  ui_story_5040_50400101_84_dialog_content = "Oh iya, kamu udah pulang belum?",
  ui_story_5040_50400101_85_dialog_content = "Eh, belum.",
  ui_story_5040_50400101_86_dialog_content = "Anda masih belum memberi tahu mereka?",
  ui_story_5040_50400101_87_dialog_content = "Berapa lama tepatnya Anda berencana untuk menyeret ini keluar?",
  ui_story_5040_50400101_88_dialog_content = "Hanya beberapa hari! Aku akan pergi besok, aku janji!",
  ui_story_5040_50400101_89_dialog_content = "Dan besok akan lusa! Besok tidak pernah datang! Apakah Anda bahkan INGIN memberi tahu orang tua Anda?",
  ui_story_5040_50400101_90_dialog_content = "...",
  ui_story_5040_50400101_91_dialog_content = "(Apa yang terjadi di sini?)",
  ui_story_5040_50400101_92_dialog_content = "Sepertinya kita kehilangan backstory di sini.",
  ui_story_5040_50400101_93_dialog_content = "Sejak Caelestite muda dan saya telah diminta di sini, bukankah seharusnya Anda memberi tahu kami apa yang terjadi?",
  ui_story_5040_50400101_94_dialog_content = "Hmph. Anda memberi tahu mereka!",
  ui_story_5040_50400101_95_dialog_content = "... Anda mungkin akan menganggap ini menggelikan, tapi sejujurnya... kami mengadakan upacara pribadi dan rahasia.",
  ui_story_5040_50400101_96_dialog_content = "Orang tua saya tidak pernah menginginkan saya menikah dengan Tara.",
  ui_story_5040_50400101_97_dialog_content = "Ah. Jadi begitu.",
  ui_story_5040_50400101_98_dialog_content = "Perkawinan antara seorang Northlander dan seorang penghuni gurun sangat jarang terjadi.",
  ui_story_5040_50400101_99_dialog_content = "Saya serius, saya akan memberi tahu mereka kali ini!",
  ui_story_5040_50400101_100_dialog_content = "Dan kemudian mari kita keluar dari sini! Kita bisa pergi ke Gurun Rediesel atau ke tempat lain.",
  ui_story_5040_50400101_101_dialog_content = "Maksudmu kau kawin lari?",
  ui_story_5040_50400101_102_dialog_content = "Aku akan senang jika aku bisa mempengaruhi orang tuaku, tapi...",
  ui_story_5040_50400101_103_dialog_content = "Tapi apa? Anda bahkan belum mencoba.",
  ui_story_5040_50400101_104_dialog_content = "Apakah benar-benar sulit bagimu untuk berbicara sendiri?!",
  ui_story_5040_50400101_105_dialog_content = "Aku…",
  ui_story_5040_50400101_106_dialog_content = "Saya ingin tahu, Adonis, apakah Anda pernah meninggalkan Northland sebelumnya?",
  ui_story_5040_50400101_107_dialog_content = "T-Tidak. Tara dan aku bertemu di sini.",
  ui_story_5040_50400101_108_dialog_content = "Ah! Bunga rumah kaca ingin menjalani kehidupan bunga liar. Betapa berani.",
  ui_story_5040_50400101_109_dialog_content = "Saya siap! Selama dua orang bersatu, tidak ada yang tidak bisa diatasi!",
  ui_story_5040_50400101_110_dialog_content = "Benar-benar? Bagaimana mengatasi ketidakmampuan Anda untuk memberitahu orang tua Anda?",
  ui_story_5040_50400101_111_dialog_content = "Hmm maaf mengganggu...",
  ui_story_5040_50400101_112_dialog_content = "Aku punya paket untukmu, Adonis. Anda mengatakan itu mendesak, jadi saya membawanya langsung.",
  ui_story_5040_50400101_113_dialog_content = "Wah, kalau bukan burung kecil Northland!",
  ui_story_5040_50400101_114_dialog_content = "L-Nyonya Jeriah?",
  ui_story_5040_50400101_115_dialog_content = "Terima kasih atas bantuan Anda memilah beberapa surat yang dikirim ke sini secara tidak sengaja.",
  ui_story_5040_50400101_116_dialog_content = "Itu lebih dari beberapa! Harap lebih berhati-hati lain kali.",
  ui_story_5040_50400101_117_dialog_content = "<size=33>Saya tidak pernah ingin harus menangani beban kerja yang mengerikan seperti itu lagi...</size>",
  ui_story_5040_50400101_118_dialog_content = "Terima kasih, <color=#FFB400>Kya</color>.",
  ui_story_5040_50400101_119_dialog_content = "Tempat apa itu?",
  ui_story_5040_50400101_120_dialog_content = "Oh iya, paranormal yang mengirimkan ramuan ini katanya sangat berhati-hati saat menggunakannya. Rupanya itu hal yang cukup ampuh.",
  ui_story_5040_50400101_121_dialog_content = "Obat? Ramuan apa?",
  ui_story_5040_50400101_122_dialog_content = "Oh, er... Nanti saya ceritakan.",
  ui_story_5040_50400101_123_dialog_content = "Katakan saja padaku sekarang! Ada apa dengan semua gumamanmu?!",
  ui_story_5040_50400101_124_dialog_content = "Huh...",
  ui_story_5040_50400101_125_dialog_content = "Itu adalah <color=#FFB400>ramuan serba guna</color> dibuat oleh paranormal super mistis. Ini dapat digunakan untuk membantu mengubah kondisi mental seseorang dengan berbagai cara, seperti meningkatkan keberanian.",
  ui_story_5040_50400101_126_dialog_content = "Saya pikir itu akan membuat saya lebih percaya diri ketika berhadapan dengan orang tua saya.",
  ui_story_5040_50400101_127_dialog_content = "(Saya belum pernah mendengar ramuan semacam ini sebelumnya!)",
  ui_story_5040_50400101_128_dialog_content = "Hah?! Apa yang salah denganmu? Apakah Anda benar-benar percaya sampah itu? Berikan di sini, coba lihat.",
  ui_story_5040_50400101_129_dialog_content = "Aku tidak percaya masih ada pengisap yang jatuh cinta pada paranormal hari ini.",
  ui_story_5040_50400101_130_dialog_content = "Kita sudah bersama selama tiga tahun, dan kamu MASIH mengandalkan ramuan minyak ular untuk memberi tahu orang tuamu tentang kita?",
  ui_story_5040_50400101_131_dialog_content = "Aku punya ini untuk membantu kami!",
  ui_story_5040_50400101_132_dialog_content = "Apa kau benar-benar pengecut? Atau apakah Anda memiliki sedikit kepercayaan pada masa depan kita ?!",
  ui_story_5040_50400101_133_dialog_content = "Adonis, apakah kita benar-benar perlu mengandalkan kekuatan eksternal untuk menjaga hubungan kita?",
  ui_story_5040_50400101_134_dialog_content = "Jika Anda harus seperti ini, mungkin lebih baik tidak—",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>Kresek... Kresek...</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>Astaga!</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>Gra—!!</size>",
  ui_story_5040_50400101_138_dialog_content = "Gerhana? Dari mana mereka berasal?",
  ui_story_5040_50400101_139_dialog_content = "Apa yang dilakukan Eclipsites di sini?!",
  ui_story_5040_50400101_140_dialog_content = "Nah, ini tidak terduga. Betapa menyusahkan.",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>... Desir!!!</color>",
  ui_story_5040_50400201_2_dialog_content = "Graaah—!",
  ui_story_5040_50400201_3_dialog_content = "Graa—!",
  ui_story_5040_50400201_4_dialog_content = "Apa yang sedang terjadi? Dari mana mereka semua berasal?!",
  ui_story_5040_50400201_5_dialog_content = "Betapapun menjengkelkannya hal ini, yang terbaik adalah berhati-hati.",
  ui_story_5040_50400201_6_dialog_content = "Ada yang aneh dengan Eclipsite di tengah itu.",
  ui_story_5040_50400201_7_dialog_content = "Hosh... Hosh...",
  ui_story_5040_50400201_8_dialog_content = "Tara! Dibelakangmu!",
  ui_story_5040_50400201_9_dialog_content = "Adonis, mundur! Mari kita tangani ini!",
  ui_story_5040_50400201_10_dialog_content = "Awas, Tara! Eclipsite yang aneh itu sepertinya mengincarmu!",
  ui_story_5040_50400201_11_dialog_content = "Memberi...",
  ui_story_5040_50400201_12_dialog_content = "Berikan padaku...",
  ui_story_5040_50400201_13_dialog_content = "aku mau... mau...",
  ui_story_5040_50400201_14_dialog_content = "Apa kaubilang?!",
  ui_story_5040_50400201_15_dialog_content = "(Apakah itu berbicara Universese?)",
  ui_story_5040_50400201_16_dialog_content = "Tara! Singkirkan ramuan itu di tanganmu!",
  ui_story_5040_50400201_17_dialog_content = "Apa-",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>Whoosh — Banting!</color>",
  ui_story_5040_50400201_19_dialog_content = "Tara!!",
  ui_story_5040_50400201_20_dialog_content = "Ini berbahaya. Cari perlindungan!",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>Byur...</color>",
  ui_story_5040_50400201_22_dialog_content = "Hei!",
  ui_story_5040_50400201_23_dialog_content = "Huff...! Obat...",
  ui_story_5040_50400201_24_dialog_content = "Grah...",
  ui_story_5040_50400201_25_dialog_content = "Grah! Graaaaah!",
  ui_story_5040_50400201_27_dialog_content = "Apakah mereka baru saja lepas landas?",
  ui_story_5040_50400201_28_dialog_content = "Masih ada beberapa yang lebih kecil yang tersisa.",
  ui_story_5040_50400201_29_dialog_content = "Jaga tunanganmu, Adonis.",
  ui_story_5040_50400202_1_dialog_content = "Akhirnya. Apakah semua orang baik-baik saja?",
  ui_story_5040_50400202_2_dialog_content = "Tara! Tara!!",
  ui_story_5040_50400202_3_dialog_content = "Oh tidak! Dia kedinginan!",
  ui_story_5040_50400202_4_dialog_content = "Kalian berdua, minggir. Mari saya lihat.",
  ui_story_5040_50400202_5_dialog_content = "Tidak ada luka serius. Sepertinya Eclipsite tidak terlalu merugikannya.",
  ui_story_5040_50400202_6_dialog_content = "Hanya beberapa goresan.",
  ui_story_5040_50400202_7_dialog_content = "Tapi mengapa dia pingsan? Mungkinkah kepalanya terbentur?",
  ui_story_5040_50400202_8_dialog_content = "Pertama dan terpenting, tenang. Dia tampak baik-baik saja sekarang, tapi kita harus membawanya ke tempat yang aman.",
  ui_story_5040_50400202_9_dialog_content = "Um, sepertinya dia terkena ramuan itu.",
  ui_story_5040_50400202_10_dialog_content = "Tidak ada yang buruk di dalamnya, bukan?!",
  ui_story_5040_50400202_11_dialog_content = "Aku tidak tahu! Kaulah yang menginginkannya, Adonis! Saya baru saja mengirimkannya atas nama paranormal itu.",
  ui_story_5040_50400202_12_dialog_content = "Jangan membuat diri Anda bekerja sampai. Hal terpenting saat ini adalah membawanya ke suatu tempat untuk beristirahat.",
  ui_story_5040_50400202_13_dialog_content = "Ya. Maaf atas masalah ini, semuanya. Bisakah kita membawa dia ke tempatku?",
  ui_story_5040_50400202_14_dialog_content = "Kalau begitu, aku akan menyelesaikan sisa pengirimanku. Jaga Tara, kalian.",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_5040_50400202_16_dialog_content = "Adonis? Apakah Anda tahu jam berapa sekarang—",
  ui_story_5040_50400202_17_dialog_content = "Apa ini? Apa yang terjadi?!",
  ui_story_5040_50400202_18_dialog_content = "Ceritanya panjang, Ayah. Mari kita masuk dulu.",
  ui_story_5040_50400202_19_dialog_content = "Apa ini temanmu, Adonis? Dan gadis ini... Apakah itu Tara?",
  ui_story_5040_50400202_20_dialog_content = "Maaf untuk ketidaknyamanannya.",
  ui_story_5040_50400202_21_dialog_content = "Dia terluka, Ibu. Kami bertemu dengan beberapa Eclipsites... Bisakah kita membuatnya menetap dulu di suatu tempat? Kemudian saya akan menceritakan keseluruhan cerita.",
  ui_story_5040_50400202_22_dialog_content = "Gerhana?! Kita harus memiliki kotak P3K di suatu tempat. Apakah ada luka yang perlu dirawat? Apakah kamu terluka?!",
  ui_story_5040_50400202_23_dialog_content = "Tidak ada alasan untuk khawatir. Dia memiliki beberapa goresan dan mungkin shock. Semua orang baik-baik saja.",
  ui_story_5040_50400202_24_dialog_content = "Aku akan pergi merawatnya. Kalian mengobrol.",
  ui_story_5040_50400202_25_dialog_content = "Jadi, itulah yang terjadi...",
  ui_story_5040_50400202_26_dialog_content = "Tidak masuk akal!",
  ui_story_5040_50400202_27_dialog_content = "Bagaimana mungkin kamu tidak memberi tahu ibumu dan aku tentang ini?",
  ui_story_5040_50400202_28_dialog_content = "Jika dia tidak terluka, Anda hanya akan kawin lari dan kemudian meninggalkan Northland?",
  ui_story_5040_50400202_29_dialog_content = "Aku…",
  ui_story_5040_50400202_30_dialog_content = "Saya selalu berpikir Anda agak bodoh, tetapi saya tidak berpikir Anda benar-benar idiot!",
  ui_story_5040_50400202_31_dialog_content = "Apakah semua yang diajarkan Novio hanya masuk ke satu telinga dan keluar dari telinga yang lain?!",
  ui_story_5040_50400202_32_dialog_content = "Anda benar-benar berpikir Anda bisa hidup sendiri jika Anda meninggalkan Northland? Kalau begitu baiklah, pergi! Dan jangan pernah kembali!",
  ui_story_5040_50400202_33_dialog_content = "Kami akan berpura-pura kami tidak pernah memiliki seorang putra!",
  ui_story_5040_50400202_34_dialog_content = "Ayah, Bu, kumohon... A-aku tidak bermaksud seperti itu!",
  ui_story_5040_50400202_35_dialog_content = "Simpan alasan menyedihkan Anda, saya tidak ingin mendengarnya!",
  ui_story_5040_50400202_36_dialog_content = "Ayahmu hanya marah, Nak.",
  ui_story_5040_50400202_37_dialog_content = "Tapi sungguh, Adonis, kami sudah kehabisan akal denganmu.",
  ui_story_5040_50400202_38_dialog_content = "...",
  ui_story_5040_50400202_39_dialog_content = "Anu…",
  ui_story_5040_50400202_40_dialog_content = "(... Tidak bisa dikatakan aku pernah menyaksikan hal seperti itu sebelumnya.)",
  ui_story_5040_50400202_41_option_content = "Hibur Adonis",
  ui_story_5040_50400202_42_dialog_content = "Jangan dimasukkan ke dalam hati. Mereka hanya sedikit kesal.",
  ui_story_5040_50400202_43_dialog_content = "Maksudku, wajar jika mereka menjadi sedikit emosional, tiba-tiba mendengar semua ini.",
  ui_story_5040_50400202_44_dialog_content = "Tapi mereka tetap orang tuamu. Bicara saja dengan mereka nanti, dan saya yakin semuanya akan beres.",
  ui_story_5040_50400202_45_dialog_content = "Sigh... orang tuaku tidak akan memaafkanku, dan Tara juga terluka.",
  ui_story_5040_50400202_46_dialog_content = "Aku benar-benar gagal.",
  ui_story_5040_50400202_47_dialog_content = "(Ini tidak baik. Dia tampaknya terjebak dalam siklus pemikiran negatif tentang dirinya sendiri...)",
  ui_story_5040_50400202_48_option_content = "Minta bantuan Yeriah",
  ui_story_5040_50400202_49_dialog_content = "Apa yang harus kita lakukan, Yeriah?",
  ui_story_5040_50400202_50_dialog_content = "Hah? Apa?",
  ui_story_5040_50400202_51_dialog_content = "(Apakah dia melamun? Pada saat seperti ini ?!)",
  ui_story_5040_50400202_52_dialog_content = "Apa yang Anda katakan dalam situasi ini?",
  ui_story_5040_50400202_53_dialog_content = "Ini masalahnya. Tidak peduli apa kata orang lain.",
  ui_story_5040_50400202_54_dialog_content = "Bagaimanapun, bahkan jika Anda menawarkan beberapa basa-basi, itu tidak benar-benar menyelesaikan apa pun.",
  ui_story_5040_50400202_55_dialog_content = "(Dia tidak salah, tapi tentunya saya tidak bisa diam saja!)",
  ui_story_5040_50400202_56_dialog_content = "(Ini sangat canggung... Suasananya sangat kaku dan tidak nyaman.)",
  ui_story_5040_50400202_57_dialog_content = "Maafkan aku, teman-teman. Saya tidak bisa membayangkan apa yang harus Anda pikirkan.",
  ui_story_5040_50400202_58_dialog_content = "Tidak apa-apa. Beri tahu kami jika ada yang bisa kami bantu.",
  ui_story_5040_50400202_59_dialog_content = "Eh... Aku sudah membawa semua ini pada diriku sendiri.",
  ui_story_5040_50400202_60_dialog_content = "Anda telah datang begitu jauh juga, dan saya telah menjadi tuan rumah yang buruk.",
  ui_story_5040_50400202_61_dialog_content = "Jangan khawatir tentang itu sekarang.",
  ui_story_5040_50400202_62_dialog_content = "Mengapa Anda tidak membawanya keluar untuk menjernihkan pikirannya, PlayerName? Aku akan merawat Tara.",
  ui_story_5040_50400202_63_dialog_content = "Oke. Ayo cari udara segar.",
  ui_story_5040_50400202_64_dialog_content = "Tentu saja…",
  ui_story_5040_50400202_65_dialog_content = "...",
  ui_story_5040_50400202_66_dialog_content = "Sudah waktunya kau bangun, kurasa.",
  ui_story_5040_50400202_67_dialog_content = "?!",
  ui_story_5040_50400202_68_dialog_content = "Bagaimana kamu tahu aku sudah bangun?",
  ui_story_5040_50400202_69_dialog_content = "Eclipsite itu bahkan tidak benar-benar menyerangmu.",
  ui_story_5040_50400202_70_dialog_content = "Saya sangat meragukan Anda bisa tidak sadarkan diri begitu lama.",
  ui_story_5040_50400202_71_dialog_content = "...",
  ui_story_5040_50400202_72_dialog_content = "Saya di sini hanya untuk membantu Naroxel, jadi saya tidak akan membuang banyak waktu untuk terlibat.",
  ui_story_5040_50400202_73_dialog_content = "Lagipula ini bukan urusanku.",
  ui_story_5040_50400202_74_dialog_content = "Tapi karena aku membantunya, aku hanya akan mengajukan pertanyaan. Apa yang Anda rencanakan?",
  ui_story_5040_50400202_75_dialog_content = "Aku…",
  ui_story_5040_50400202_76_dialog_content = "Sejujurnya? Saya tidak punya ide. Hidup di gurun tidak pernah sesulit ini. Aku sangat kesal.",
  ui_story_5040_50400202_77_dialog_content = "Saya tidak dapat menyangkal bahwa Adonis memberi saya banyak kebahagiaan. Tapi kurangnya tulang punggung membuat saya bertanya-tanya apakah saya benar-benar bisa menikah dengannya.",
  ui_story_5040_50400202_78_dialog_content = "Karakter seseorang tidak terbentuk dan tidak dapat diubah dalam semalam. Anda sudah bersama begitu lama, apakah Anda benar-benar baru menemukan masalah ini sekarang?",
  ui_story_5040_50400202_79_dialog_content = "Tentu saja tidak.",
  ui_story_5040_50400202_80_dialog_content = "Tiga tahun lalu, saya diserang oleh Eclipsites saat mencari reruntuhan di Northland. Saya berhasil kabur, tapi pingsan di pinggir jalan.",
  ui_story_5040_50400202_80X1_dialog_content = "Dia yang menemukanku dan membawaku pulang.",
  ui_story_5040_50400202_81_dialog_content = "Ada hujan salju lebat hari itu juga. Aku tidak ingin memikirkan apa yang akan terjadi jika dia tidak menemukanku.",
  ui_story_5040_50400202_82_dialog_content = "*Sigh* Setelah itu, kami berbicara tentang apa saja, tentang hal-hal yang belum pernah dilihat orang lain.",
  ui_story_5040_50400202_83_dialog_content = "Kami tetap berhubungan setelah saya kembali ke gurun, mengirim surat bolak-balik.",
  ui_story_5040_50400202_84_dialog_content = "Dia begitu bijaksana dan perhatian. Saya tumbuh tanpa orang tua, dan tidak ada yang pernah menunjukkan perhatian seperti itu kepada saya sebelumnya.",
  ui_story_5040_50400202_85_dialog_content = "Saya sangat tersentuh.",
  ui_story_5040_50400202_86_dialog_content = "Ah, jadi begitulah kejadiannya.",
  ui_story_5040_50400202_87_dialog_content = "Namun belakangan, setiap kali topik meninggalkan Northland diangkat, dia selalu tampak ragu-ragu. Aku merasa dia benar-benar berubah.",
  ui_story_5040_50400202_88_dialog_content = "Dia tidak seperti dulu lagi. Apakah benar-benar sulit untuk mengambil keputusan?",
  ui_story_5040_50400202_89_dialog_content = "Saya belum pernah bertemu pria yang begitu pemalu, begitu bimbang! Apakah dia benar-benar menyukaiku?",
  ui_story_5040_50400202_90_dialog_content = "Saya sudah lama merencanakan pernikahan kami, dan bahkan menyiapkan hadiah yang sangat istimewa. Tapi sekarang... Meh.",
  ui_story_5040_50400202_91_dialog_content = "Ini mungkin tidak pantas, tetapi apakah Anda pernah jatuh cinta sebelum dia?",
  ui_story_5040_50400202_92_dialog_content = "Sebelum Adonis? Tidak, dia cinta pertamaku.",
  ui_story_5040_50400202_93_dialog_content = "Yah, tidak heran kalau begitu. Anda tampaknya memiliki harapan yang tidak realistis terhadapnya.",
  ui_story_5040_50400202_94_dialog_content = "Cinta bisa menjadi hal yang indah, tetapi Anda juga harus menghargai siapa seseorang. Setiap individu adalah makhluk yang rumit dan bernuansa; tidak ada yang hanya hitam atau putih.",
  ui_story_5040_50400202_95_dialog_content = "A-Apa maksudmu? Saya tidak yakin saya mengikuti.",
  ui_story_5040_50400202_96_dialog_content = "Heheh... Suatu saat nanti, kamu mungkin mengerti.",
  ui_story_5040_50400202_97_dialog_content = "...",
  ui_story_5040_50400202_98_dialog_content = "Tunggu! Aku memahaminya! Saya punya ide!",
  ui_story_5040_50400202_99_dialog_content = "?",
  ui_story_5040_50400202_102_dialog_content = "Ini dia!",
  ui_story_5040_50400202_103_dialog_content = "Aku hanya akan berpura-pura menderita amnesia! Mulai dari awal lagi, lihat bagaimana dia bertindak terhadap saya!",
  ui_story_5040_50400202_104_dialog_content = "...",
  ui_story_5040_50400202_105_dialog_content = "Kau serius?",
  ui_story_5040_50400202_106_dialog_content = "Tolong, saya mohon! Tolong aku!",
  ui_story_5040_50400202_107_dialog_content = "Jika kalian berdua tidak akan menikah, aku mungkin harus pergi.",
  ui_story_5040_50400202_108_dialog_content = "Oh ayolah! Jangan pergi! Apa yang akan Anda katakan kepada Naroxel?",
  ui_story_5040_50400202_109_dialog_content = "Apakah Anda mencoba untuk mengancam saya?",
  ui_story_5040_50400202_110_dialog_content = "Ah! Tidak, tidak, tentu saja tidak! Bagaimana aku bisa? Anda telah begitu baik kepada saya... Tolong, saya mohon!",
  ui_story_5040_50400202_111_dialog_content = "Tolong, lakukan itu bukan hanya untuk Naroxel, tapi untuk sesama Rediesel Wrench gal!",
  ui_story_5040_50400202_112_dialog_content = "Anda benar-benar tahu cara memanipulasi orang.",
  ui_story_5040_50400202_113_dialog_content = "Sakit sekali.",
  ui_story_5040_50400202_114_dialog_content = "Pleeeaaaassee! Kamu yang terbaik!",
  ui_story_5040_50400202_115_dialog_content = "Kalian berdua harus menyelesaikan masalah kalian sendiri. Aku hanya seorang pengamat.",
  ui_story_5040_50400202_116_dialog_content = "Terserah Anda bagaimana sandiwara Anda dimainkan.",
  ui_story_5040_50400202_117_dialog_content = "<color=#e8d9bb>Keesokan harinya...</color>",
  ui_story_5040_50400202_118_dialog_content = "Selamat pagi, Jeriah, Adonis.",
  ui_story_5040_50400202_119_dialog_content = "Selamat pagi, Caelestite muda.",
  ui_story_5040_50400202_120_dialog_content = "Pagi. Aku akan memeriksa apakah Tara sudah bangun...",
  ui_story_5040_50400202_121_dialog_content = "*Huahh*",
  ui_story_5040_50400202_122_dialog_content = "Tara! Anda sudah bangun! Apakah kamu baik-baik saja?",
  ui_story_5040_50400202_123_dialog_content = "…?",
  ui_story_5040_50400202_124_dialog_content = "Apa yang salah? Kenapa kau menatapku seperti itu?",
  ui_story_5040_50400202_125_dialog_content = "Siapa kau?",
  ui_story_5040_50400202_126_dialog_content = "Apa yang kamu bicarakan? Tara?",
  ui_story_5040_50400202_127_dialog_content = "Saya tidak mengenal Anda. Jangan sentuh aku!",
  ui_story_5040_50400202_128_dialog_content = "dimana saya? Kamu siapa?",
  ui_story_5040_50400202_129_dialog_content = "Aku ingat datang ke Northland kemarin dengan Jeriah di Colossus, tapi... Sungguh aneh, aku tidak ingat kenapa.",
  ui_story_5040_50400202_130_dialog_content = "Ini tidak lucu Tara...",
  ui_story_5040_50400202_131_dialog_content = "Tidak lucu sama sekali!",
  ui_story_5040_50400202_132_dialog_content = "Apakah kamu baik-baik saja, Adonis?",
  ui_story_5040_50400202_133_dialog_content = "(Lucu, anehnya Tara terdengar tenang, mengingat semua hal. Apakah dia sengaja mengatakan itu?)",
  ui_story_5040_50400202_134_dialog_content = "(Aku tidak benar-benar mengerti urusan hati. Segalanya mungkin menjadi lebih buruk jika aku mengorek, jadi sebaiknya jangan ikut campur sekarang.)",
  ui_story_5040_50400202_135_dialog_content = "Ini salahku! Semua salahku!",
  ui_story_5040_50400202_136_dialog_content = "Ramuan celaka itu! Saya berharap saya tidak pernah memikirkannya!",
  ui_story_5040_50400202_137_dialog_content = "Menurutmu ramuan itu yang menyebabkan amnesianya?",
  ui_story_5040_50400202_138_dialog_content = "Paranormal mengatakan bahwa itu mampu menghasilkan segala macam efek! Saya tidak bisa memikirkan alasan lain untuk ini!",
  ui_story_5040_50400202_139_dialog_content = "Pasti itu. Ramuan itu tumpah padanya, tepat ketika dia kesal padaku dan berharap dia bisa melupakanku! Jadi itulah yang dilakukan ramuan itu!",
  ui_story_5040_50400202_140_dialog_content = "Itu semua salah ku!",
  ui_story_5040_50400202_141_dialog_content = "Jika memang begitu, mengapa tidak pergi bertanya kepada paranormal?",
  ui_story_5040_50400202_142_dialog_content = "Tidak ada gunanya hanya duduk di sini menangisi susu yang tumpah.",
  ui_story_5040_50400202_143_dialog_content = "Cenayang?",
  ui_story_5040_50400202_144_dialog_content = "Ya kau benar! Dan saya baru ingat terkadang mereka mendirikan lapak di pasar!",
  ui_story_5040_50400202_145_dialog_content = "Aku akan pergi! Aku akan pergi sekarang!",
  ui_story_5040_50400202_146_dialog_content = "*Terengah-engah*... O-Di sana!",
  ui_story_5040_50400202_147_dialog_content = "(Wow, dia berlari sangat cepat...)",
  ui_story_5040_50400202_148_dialog_content = "Hmm? Siapa Anda?",
  ui_story_5040_50400202_149_dialog_content = "Saya orang yang membeli ramuan serba guna itu! Saya punya pertanyaan mendesak untuk Anda!",
  ui_story_5040_50400202_150_dialog_content = "Hah...? Oh ya! Orang itu!",
  ui_story_5040_50400202_151_dialog_content = "Bagaimana itu? Saya menuangkan hati dan jiwa saya ke dalam setiap botol, jadi apakah saya yakin hasilnya seperti yang diharapkan?",
  ui_story_5040_50400202_152_dialog_content = "Ceritanya panjang, tapi tunanganku menggunakan ramuan itu secara tidak sengaja, dan sekarang dia tidak bisa mengingat apapun! Tolong, Anda harus memberi saya penawarnya!",
  ui_story_5040_50400202_153_dialog_content = "Hah?! Tapi itu tidak mungkin...",
  ui_story_5040_50400202_154_dialog_content = "Bukankah Anda mengatakan itu bisa melakukan apa saja? Apapun yang diinginkan hati?!",
  ui_story_5040_50400202_155_dialog_content = "A-aku memang mengatakan itu, ya.",
  ui_story_5040_50400202_156_dialog_content = "Tapi jika itu penawar yang kau cari... Aku khawatir itu akan membutuhkan usaha.",
  ui_story_5040_50400202_157_dialog_content = "Hah? Bagaimana bisa?!",
  ui_story_5040_50400202_158_dialog_content = "Karena itu terbuat dari sesuatu yang hanya sedikit orang yang pernah melihatnya. Harta paling langka Reddiesel Desert, sisik berkilauan dari cacing pasir merah muda yang legendaris!",
  ui_story_5040_50400202_159_dialog_content = "Saya sendiri dari gurun. Kenapa saya belum pernah mendengar tentang ini sebelumnya?",
  ui_story_5040_50400202_160_dialog_content = "!",
  ui_story_5040_50400202_161_dialog_content = "Baiklah, beri tahu saya... Jika semua orang biasa mengetahuinya, apakah itu masih langka?",
  ui_story_5040_50400202_162_dialog_content = "Kebanyakan orang bahkan tidak akan pernah melihat cacing pasir merah muda yang misterius sekali pun dalam hidup mereka.",
  ui_story_5040_50400202_163_dialog_content = "(Saya pikir paranormal ini penuh dengan itu. Dan siapa yang mau melihat hal seperti itu?)",
  ui_story_5040_50400202_164_dialog_content = "Sisiknya berkilau dengan semua warna pelangi, sementara tubuhnya yang merah jambu sama megah dan mempesonanya dengan cangkang terindah!",
  ui_story_5040_50400202_165_dialog_content = "Jika Anda bersikeras pada penawar ini, itu tidak dapat dilakukan tanpa beberapa sisiknya. Mungkin Anda harus memikirkan cara mendapatkannya!",
  ui_story_5040_50400202_166_dialog_content = "K-Kau sengaja mempersulit, bukan?!",
  ui_story_5040_50400202_167_dialog_content = "Hei, bukan aku yang menginginkan penawarnya. Aku sudah memberitahumu dengan itikad baik, sekarang tinggalkan aku. Saya tidak ingin Anda mempengaruhi bisnis saya.",
  ui_story_5040_50400202_168_dialog_content = "...",
  ui_story_5040_50400202_169_dialog_content = "Itu dia. Ini sudah berakhir.",
  ui_story_5040_50400202_170_dialog_content = "Saya bersedia dan mampu melakukan apa pun, tetapi melawan cacing pasir...? Mustahil.",
  ui_story_5040_50400202_171_dialog_content = "Bahkan cacing-cacing di kebun saya membuat saya takut. Tidak mungkin aku bisa pergi mencari cacing pasir gurun!",
  ui_story_5040_50400202_172_dialog_content = "Kau tahu... Aku jarang bertemu pria dengan tulang punggung sekecilmu.",
  ui_story_5040_50400202_173_dialog_content = "(Tolong jangan membuat ini lebih buruk!)",
  ui_story_5040_50400202_174_dialog_content = "Lihat sisi positifnya. Setidaknya dia masih hidup dan sehat, dan dari apa yang kupahami dia baru saja kehilangan ingatannya tentang hubungan kalian.",
  ui_story_5040_50400202_175_dialog_content = "Daripada mengejar angsa liar, mungkin lebih baik memikirkan cara menyalakan kembali api romantis itu.",
  ui_story_5040_50400202_176_dialog_content = "Lagi pula, dia belum melupakan segalanya. Selama dia baik-baik saja, maka masih ada kesempatan.",
  ui_story_5040_50400202_177_dialog_content = "Pasti ada alasan mengapa kalian berdua bersama begitu lama. Saya tidak berpikir itu harus terlalu sulit untuk memulai kembali.",
  ui_story_5040_50400202_178_dialog_content = "Ya... Saya kira Anda benar.",
  ui_story_5040_50400202_179_dialog_content = "Masalahnya, saya sama sekali tidak tahu harus mulai dari mana. Dia melihatku sebagai orang asing.",
  ui_story_5040_50400202_180_dialog_content = "Omong-omong, saya yakin Anda berdua ingat bahwa saya dikirim ke sini untuk menghadiri pernikahan atas nama Naroxel.",
  ui_story_5040_50400202_181_dialog_content = "Banyak orang menikah pada Hari Mooncrown, dan kebanyakan dari mereka menginginkan seorang kurir untuk menghadiri pernikahan mereka.",
  ui_story_5040_50400202_182_dialog_content = "Aku pernah mendengar tentang tradisi itu. Ternyata, memiliki kurir di pesta pernikahan bisa membawa kebahagiaan dan harapan.",
  ui_story_5040_50400202_183_dialog_content = "Tepat. Itu sebabnya Union telah mengadakan acara khusus Hari Mooncrown dalam beberapa tahun terakhir, yang ditujukan untuk pengantin baru dan pasangan.",
  ui_story_5040_50400202_184_dialog_content = "Ini juga membantu meringankan beberapa tekanan pada kurir. Bagaimanapun, ini adalah salah satu waktu tersibuk dalam setahun.",
  ui_story_5040_50400202_185_dialog_content = "Benar-benar? Saya tidak pernah tahu itu.",
  ui_story_5040_50400202_186_dialog_content = "Benar, itu sudah jelas, karena ditujukan untuk pasangan. Saya sangat ragu mereka akan berada di radar lajang abadi.",
  ui_story_5040_50400202_187_dialog_content = "Hei!",
  ui_story_5040_50400202_188_dialog_content = "Apa maksudmu?",
  ui_story_5040_50400202_189_dialog_content = "Di beberapa tempat, acara ini sudah menggantikan kebiasaan kurir menghadiri pernikahan sebagai berkah keberuntungan bagi pasangan yang berbahagia.",
  ui_story_5040_50400202_190_dialog_content = "Setiap cabang memiliki acaranya sendiri, dan mereka yang mengalaminya dengan sukses menerima Segel Bulu Serikat Kurir.",
  ui_story_5040_50400202_191_dialog_content = "Anda harus mempertimbangkan untuk menghadiri salah satu acara ini bersama Tara. Anda bisa melihat dunia luar saat Anda melakukannya.",
  ui_story_5040_50400202_192_dialog_content = "Maksudmu... meninggalkan Northland?",
  ui_story_5040_50400202_193_dialog_content = "Pengidap amnesia seringkali dapat membuat ingatan masa lalu diaduk melalui peristiwa eksternal. Itu sebenarnya obat tradisional kuno.",
  ui_story_5040_50400202_194_dialog_content = "Yang saya katakan adalah bahwa acara Courier Union mungkin merupakan peluang besar. Apa yang Anda lakukan dengannya, jika ada, terserah Anda.",
  ui_story_5040_50400202_195_dialog_content = "Anda tidak akan mencapai banyak hal dengan menutup diri dan khawatir di rumah. Jika Anda tidak keluar dan melihat dunia, bagaimana Anda tahu jika ada solusi?",
  ui_story_5040_50400202_196_dialog_content = "Itu bukan urusan saya, tapi siapa bilang Anda mungkin tidak menemukan cara untuk mengembalikan ingatannya dengan pergi keluar dan berkeliling?",
  ui_story_5040_50400202_197_dialog_content = "Aku setuju!",
  ui_story_5040_50400202_198_dialog_content = "Saya juga menghabiskan waktu lama sendirian dalam kesendirian sebelumnya. Semua yang saya tahu tentang dunia diajarkan kepada saya.",
  ui_story_5040_50400202_199_dialog_content = "Hanya ketika saya keluar, saya menyadari bahwa dunia yang lebih luas memiliki begitu banyak hal yang tidak saya ketahui.",
  ui_story_5040_50400202_200_dialog_content = "Jika Anda pergi keluar dan menjelajah, Anda dapat membangkitkan ingatan Tara dan mempelajari lebih lanjut tentang kondisinya!",
  ui_story_5040_50400202_201_dialog_content = "Teman-teman...!",
  ui_story_5040_50400202_202_dialog_content = "Sebenarnya, aku... um, aku benar-benar tidak tahu harus berkata apa.",
  ui_story_5040_50400202_203_dialog_content = "Saya berterima kasih kepada Anda karena telah membantu saya memikirkan ide. Saat ini, kondisi Tara adalah satu-satunya hal yang dapat kupikirkan.",
  ui_story_5040_50400202_204_dialog_content = "Kamu benar! Aku percaya pada cinta kita. Apa pun yang hilang dari kita dapat ditemukan kembali!",
  ui_story_5040_50400202_205_dialog_content = "...",
  ui_story_5040_50400202_206_dialog_content = "...",
  ui_story_5040_50400202_207_dialog_content = "Itulah yang saya pikirkan!",
  ui_story_5040_50400202_208_dialog_content = "Aku tahu kau mungkin tidak setuju, tapi...",
  ui_story_5040_50400202_209_dialog_content = "Pergilah kalau begitu.",
  ui_story_5040_50400202_210_dialog_content = "Hah?",
  ui_story_5040_50400202_211_dialog_content = "Jika kalian berdua kembali dari perjalanan kalian dan masih ingin hidup bersama, yah... kita bisa mempertimbangkannya dengan serius.",
  ui_story_5040_50400202_212_dialog_content = "B-benarkah?!",
  ui_story_5040_50400202_213_dialog_content = "Saya tidak percaya! Ibu, Ayah, terima kasih banyak!",
  ui_story_5040_50400202_214_dialog_content = "Ingatlah bahwa Anda belum pernah keluar dari Northland sebelumnya. Ini dunia yang berbahaya di luar sana, jadi Anda harus ekstra hati-hati.",
  ui_story_5040_50400202_215_dialog_content = "<size=33>Ada apa dengan perubahan hati mereka yang tiba-tiba, Jeriah?</size>",
  ui_story_5040_50400202_216_dialog_content = "Seandainya saja dia juga ada di sini...",
  ui_story_5040_50400202_217_dialog_content = "Bolehkah saya berbicara dengan Anda, Tuan?",
  ui_story_5040_50400202_218_dialog_content = "Hmm? Siapa kamu?",
  ui_story_5040_50400202_219_dialog_content = "Saya Jeriah, anggota senior Serikat Kurir.",
  ui_story_5040_50400202_220_dialog_content = "Oh. Dapatkah saya membantu Anda dengan sesuatu? Jika itu ada hubungannya dengan anak nakal yang tidak tahu berterima kasih—",
  ui_story_5040_50400202_221_dialog_content = "Saya sangat mengerti bagaimana perasaan Anda.",
  ui_story_5040_50400202_222_dialog_content = "Semua orang tua ingin anaknya bahagia. Kekhawatiran Anda mungkin berasal dari ketakutan bahwa dia terlalu naif dan kekanak-kanakan.",
  ui_story_5040_50400202_223_dialog_content = "Seseorang yang tidak pernah meninggalkan rumahnya, tiba-tiba ingin menjalani kehidupan yang romantis dan mengembara.",
  ui_story_5040_50400202_224_dialog_content = "Saya pikir saya juga tidak akan bisa menerimanya.",
  ui_story_5040_50400202_225_dialog_content = "Seperti yang Anda katakan. Tidak ada dalam hidup yang semudah itu!",
  ui_story_5040_50400202_226_dialog_content = "Adonis belajar di bawah asuhan Pak Novio sebagai seorang anak. Dia penuh perhatian dan cerdas, hanya sedikit terlalu naif.",
  ui_story_5040_50400202_227_dialog_content = "Dia belum banyak mengalami, jadi dia memiliki kecenderungan untuk melihat dunia melalui kacamata berwarna mawar.",
  ui_story_5040_50400202_228_dialog_content = "Lalu, bagaimana dengan membiarkan dia memiliki kesempatan untuk mengalami sesuatu?",
  ui_story_5040_50400202_229_dialog_content = "Semakin lama anak burung tinggal di dalam sarang, semakin sedikit kemampuannya untuk bertahan hidup sendiri.",
  ui_story_5040_50400202_230_dialog_content = "Mereka yang tidak sekuat orang lain tidak akan pernah secara aktif merebut kebahagiaan, hanya menerimanya secara pasif.",
  ui_story_5040_50400202_231_dialog_content = "Tidak masalah ke mana mereka pergi, atau dengan siapa.",
  ui_story_5040_50400202_232_dialog_content = "Anda tampak seperti ayah yang bijaksana. Bagaimana menurutmu?",
  ui_story_5040_50400202_233_dialog_content = "Saya tidak tahu apa yang Anda katakan, tetapi selama semuanya berhasil.",
  ui_story_5040_50400301_1_dialog_content = "Surat untukmu! Ini dia!",
  ui_story_5040_50400301_2_dialog_content = "Terima kasih, Kya. Kenapa kamu bekerja begitu larut?",
  ui_story_5040_50400301_3_dialog_content = "Festival sudah dekat. Saya harap saya bisa memberikan lebih banyak, karena saya yakin orang-orang menunggu dengan cemas.",
  ui_story_5040_50400301_4_dialog_content = "Pemula selalu bekerja paling keras. Semua yang terbaik untukmu!",
  ui_story_5040_50400301_5_dialog_content = "Fiuh, sudah sangat larut.",
  ui_story_5040_50400301_6_dialog_content = "Semua terkirim, akhirnya. Saya kira saya akan menyebutnya sehari hari ini.",
  ui_story_5040_50400301_7_dialog_content = "(Sore ini aku mendengar Adonis mengatakan bahwa Tara menderita amnesia... Mungkinkah ini terkait dengan serangan Eclipsite kemarin?)",
  ui_story_5040_50400301_8_dialog_content = "(Ini mengkhawatirkan. Mungkin saya harus kembali ke tempat kejadiannya dan melihat-lihat.)",
  ui_story_5040_50400301_9_dialog_content = "(Saya pikir itu ada di sekitar sini.)",
  ui_story_5040_50400301_10_dialog_content = "Eh?",
  ui_story_5040_50400301_11_dialog_content = "Kenapa di sini berwarna ungu? Apa karena ramuan itu?",
  ui_story_5040_50400301_12_dialog_content = "Dan sepertinya ada jejak ungu menuju ke hutan.",
  ui_story_5040_50400301_13_dialog_content = "Yah, sebaiknya aku memeriksanya.",
  ui_story_5040_50400301_14_dialog_content = "<color=#e8d9bb>Aduh, aduh—</color>",
  ui_story_5040_50400301_15_dialog_content = "(Gelap sekali! Mungkin sebaiknya aku kembali saja. Ini agak menakutkan.)",
  ui_story_5040_50400301_16_dialog_content = "Tunggu... Jejaknya baru saja selesai di sini?",
  ui_story_5040_50400301_17_dialog_content = "Ah...",
  ui_story_5040_50400301_18_dialog_content = "<size=50>Aaaaaah!</size>",
  ui_story_5040_50400301_19_dialog_content = "Siapa di sana?!",
  ui_story_5040_50400301_20_dialog_content = "B-Tolong...",
  ui_story_5040_50400301_21_dialog_content = "Tolong aku...",
  ui_story_5040_50400301_22_dialog_content = "S-Siapa yang bilang itu?",
  ui_story_5040_50400301_23_dialog_content = "Aku... Aku!",
  ui_story_5040_50400301_24_dialog_content = "Sebuah E-Eclipsite?!",
  ui_story_5040_50400301_25_dialog_content = "T-Tidak... Jangan...",
  ui_story_5040_50400301_26_dialog_content = "Aku... Tidak... Bahaya...",
  ui_story_5040_50400301_27_dialog_content = "Apa? Apakah itu Semesta? Tapi kau Eclipsite yang menyerang Tara kemarin!",
  ui_story_5040_50400301_28_dialog_content = "Aku... Tidak... Terluka... Kamu...",
  ui_story_5040_50400301_29_dialog_content = "Tetap kembali! Apa yang sedang kamu lakukan?",
  ui_story_5040_50400301_30_dialog_content = "Tolong... Anda...",
  ui_story_5040_50400301_31_dialog_content = "Tolong aku...",
  ui_story_5040_50400301_32_dialog_content = "Apa katamu?",
  ui_story_5040_50400301_33_dialog_content = "ingatanku... hilang...",
  ui_story_5040_50400301_34_dialog_content = "Aku... lupa... siapa... aku...",
  ui_story_5040_50400301_35_dialog_content = "Takut...",
  ui_story_5040_50400301_36_dialog_content = "Sangat... takut...",
  ui_story_5040_50400301_37_dialog_content = "Anda tidak tahu siapa Anda? Lalu mengapa Anda menyerang kami kemarin?",
  ui_story_5040_50400301_38_dialog_content = "Aku... Bukan... Serang...",
  ui_story_5040_50400301_39_dialog_content = "Ingin ... ramuan ...",
  ui_story_5040_50400301_40_dialog_content = "Obat?",
  ui_story_5040_50400301_41_dialog_content = "Aku... bersembunyi... pasar...",
  ui_story_5040_50400301_42_dialog_content = "Dengar... ramuan... ampuh...",
  ui_story_5040_50400301_43_dialog_content = "Ingin... menggunakan... memulihkan... memori...",
  ui_story_5040_50400301_44_dialog_content = "Tapi... mereka... mengambil...",
  ui_story_5040_50400301_45_dialog_content = "Jadi itulah yang terjadi.",
  ui_story_5040_50400301_46_dialog_content = "Tapi bagaimana bisa sebuah Eclipsite memiliki kenangan? Mungkinkah Anda pernah menjadi Aurorian?",
  ui_story_5040_50400301_47_dialog_content = "Pikir... gitu... tapi... lupa...",
  ui_story_5040_50400301_48_dialog_content = "Saya ketakutan...",
  ui_story_5040_50400301_49_dialog_content = "(Semua orang membenci Eclipsites, tapi sepertinya tidak bohong...)",
  ui_story_5040_50400301_50_dialog_content = "(Jika ada yang tahu saya membantu Eclipsite, saya pasti akan kehilangan pekerjaan sebagai kurir. Saya bahkan bisa ditangkap.)",
  ui_story_5040_50400301_51_dialog_content = "Dingin...",
  ui_story_5040_50400301_52_dialog_content = "Dia!",
  ui_story_5040_50400301_53_dialog_content = "Baiklah. Ayo.",
  ui_story_5040_50400301_54_dialog_content = "Terima kasih...!",
  ui_story_5040_50400301_55_dialog_content = "Supaya jelas, urusan lucu apa pun dan saya memberi tahu Pembicara!",
  ui_story_5040_50400301_56_dialog_content = "Ya!",
  ui_story_5040_50400301_57_dialog_content = "Benar, jadi bagaimana sekarang...?",
  ui_story_5040_50400301_58_dialog_content = "Sembunyikan di sini sebentar lagi.",
  ui_story_5040_50400301_59_dialog_content = "Yap, ini harus berhasil!",
  ui_story_5040_50400301_60_dialog_content = "Bisakah saya...?",
  ui_story_5040_50400301_61_dialog_content = "Apakah Anda yakin ingin memakai ini? Ini gaun pengiring pengantin lamaku.",
  ui_story_5040_50400301_62_dialog_content = "Anda terlihat seperti Aurorian di dalamnya, meskipun gaunnya sedikit menonjol.",
  ui_story_5040_50400301_63_dialog_content = "Terima kasih... Kamu... Berpakaian... Bagus...",
  ui_story_5040_50400301_64_dialog_content = "Sudahlah. Anda bisa memakainya jika Anda menyukainya. Ngomong-ngomong, namaku Kya. Aku harus memanggilmu apa di depan umum? Apakah Anda ingat nama Anda?",
  ui_story_5040_50400301_65_dialog_content = "Tidak... tahu...",
  ui_story_5040_50400301_66_dialog_content = "Kurasa aku akan memanggilmu Sable untuk saat ini. Bagaimana dengan itu?",
  ui_story_5040_50400301_67_dialog_content = "O-oke…",
  ui_story_5040_50400301_68_dialog_content = "Anda benar-benar tidak ingat apa-apa?",
  ui_story_5040_50400301_69_dialog_content = "Tidak...",
  ui_story_5040_50400301_70_dialog_content = "Apakah Anda selalu berada di Northland?",
  ui_story_5040_50400301_71_dialog_content = "Tidak... aku pikir... datang dari... jauh...",
  ui_story_5040_50400301_72_dialog_content = "Hmm baiklah. Biarkan aku berpikir.",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>Hari berikutnya-</color>",
  ui_story_5040_50400301_74_dialog_content = "Siap?",
  ui_story_5040_50400301_75_dialog_content = "Kalian akan melakukan perjalanan panjang. Pastikan Anda memiliki semua yang Anda butuhkan.",
  ui_story_5040_50400301_76_dialog_content = "Ya! Kami punya cukup ikan haring kalengan, daging rusa, dan daging hiu untuk bertahan setidaknya sebulan.",
  ui_story_5040_50400301_77_dialog_content = "Sedangkan untuk makanan kering, kami memiliki anjing laut beku-kering, udang, dan ikan yang cukup untuk dua bulan.",
  ui_story_5040_50400301_78_dialog_content = "Kemudian, dalam keadaan darurat, ada kompor portabel, palu seberat sepuluh pon, pisau, sekop, ketel, sepatu bot, jas hujan...",
  ui_story_5040_50400301_79_dialog_content = "Tunggu sebentar. Anda akan Lumopolis, kan? Dan tidak bertahan hidup di hutan belantara di Wilayah Rahasia?",
  ui_story_5040_50400301_80_dialog_content = "Tentunya itu sedikit berlebihan? Tempat seperti apa menurutmu Lumopolis itu?",
  ui_story_5040_50400301_81_dialog_content = "Kami mengunjungi Lumopolis, Kota Gannon, dan Gurun Rediesel dalam perjalanan ini. Saya ingin mempersiapkan diri sebaik mungkin.",
  ui_story_5040_50400301_82_dialog_content = "Itu ide yang tepat, tetapi pikirkan tentang apa yang sebenarnya akan Anda gunakan. Ini tidak seperti Anda bisa kelaparan di salah satu tempat yang Anda tuju.",
  ui_story_5040_50400301_83_dialog_content = "...",
  ui_story_5040_50400301_84_dialog_content = "Apa? Bepergian? Dengan orang asing?!",
  ui_story_5040_50400301_85_dialog_content = "Tenang, Tara. Ini adalah perjalanan, tapi kami sangat berharap ini akan membantu Anda memulihkan ingatan Anda.",
  ui_story_5040_50400301_86_dialog_content = "Tentunya Anda ingin mengingatnya?",
  ui_story_5040_50400301_87_dialog_content = "Tentu saja saya tahu, tapi ini gila.",
  ui_story_5040_50400301_88_dialog_content = "Lagi pula, aku hanya melupakan hal-hal yang berhubungan denganmu.",
  ui_story_5040_50400301_89_dialog_content = "Anda mengatakan itu, tetapi kenangan kita bersama penting bagi Anda dan saya.",
  ui_story_5040_50400301_90_dialog_content = "Mmm…",
  ui_story_5040_50400301_91_dialog_content = "Saya menghormati pendapat Anda, tentu saja, tetapi saya benar-benar ingin setidaknya mencoba mengembalikan ingatan Anda dengan bepergian.",
  ui_story_5040_50400301_92_dialog_content = "Bagaimana menurutmu? Saya tidak akan memaksa Anda untuk pergi jika Anda benar-benar tidak mau.",
  ui_story_5040_50400301_93_dialog_content = "(Ya ampun, tidak percaya kita akan melakukan ini. Kenapa aku begitu lembut?)",
  ui_story_5040_50400301_94_dialog_content = "Tenang, Tar. Aku akan menjagamu! Tidak ada yang perlu dikhawatirkan!",
  ui_story_5040_50400301_95_dialog_content = "Tugas Anda dalam perjalanan ini adalah bersenang-senang!",
  ui_story_5040_50400301_96_dialog_content = "Aku bahkan tidak tahu siapa kamu. Jangan berpikir kamu bisa bersikap baik padaku dan aku akan tergerak atau semacamnya.",
  ui_story_5040_50400301_97_dialog_content = "Saya ingin pulang ke rumah.",
  ui_story_5040_50400301_98_dialog_content = "Aku akan mengantarmu pulang. Perhentian terakhir kami adalah gurun pasir.",
  ui_story_5040_50400301_99_dialog_content = "Kami hanya akan bersenang-senang di sepanjang jalan! Sementara itu, kami akan memikirkan cara untuk membangkitkan ingatan Anda.",
  ui_story_5040_50400301_100_dialog_content = "Bagus. Apa pun.",
  ui_story_5040_50400301_101_dialog_content = "Kalau begitu, jika Anda sudah siap, maka saatnya untuk pergi. Saya akan membawa Anda ke Lumopolis, karena saya harus melaporkan kembali ke Naroxel.",
  ui_story_5040_50400301_102_dialog_content = "PlayerName! Tunggu!",
  ui_story_5040_50400301_103_dialog_content = "Hah?",
  ui_story_5040_50400301_104_dialog_content = "*Hah* Fiuh, aku senang bisa menyusul!",
  ui_story_5040_50400301_105_dialog_content = "Jika bukan burung kecil Northland! Sangat lucu, bahkan ketika Anda kehabisan napas.",
  ui_story_5040_50400301_106_dialog_content = "Tolong jangan menggodaku, Nona Jeriah! Jadi, um... Kudengar kalian semua akan pergi ke Lumopolis. Bisakah Anda membawa kami juga?",
  ui_story_5040_50400301_107_dialog_content = "\"Kita\"?",
  ui_story_5040_50400301_108_dialog_content = "Mungkinkah dia mengacu pada individu aneh yang terlihat mencurigakan seperti Eclipsite?",
  ui_story_5040_50400301_109_dialog_content = "K-Kamu tidak bisa begitu saja memberi tahu seseorang bahwa mereka terlihat seperti Eclipsite!",
  ui_story_5040_50400301_110_dialog_content = "Ini adalah, eh, kerabat jauh saya! Dia dipanggil Sable.",
  ui_story_5040_50400301_111_dialog_content = "H-Halo... Semuanya...",
  ui_story_5040_50400301_112_dialog_content = "(Saya benar-benar yakin Sable ini mengeluarkan Darkflow yang serius...)",
  ui_story_5040_50400301_113_dialog_content = "(Tapi tidak ada lonceng alarm lain yang berbunyi. Lebih baik menunggu dan melihat.)",
  ui_story_5040_50400301_114_dialog_content = "Seekor burung hitam kecil, ya? Pakaian menarik yang Anda kenakan.",
  ui_story_5040_50400301_115_dialog_content = "S-Sable menyukai pakaian formal! Dia jarang keluar, jadi dia ingin berdandan sedikit.",
  ui_story_5040_50400301_116_dialog_content = "(Untuk beberapa alasan yang tidak bisa dijelaskan, dia sepertinya sangat menyukai gaun itu. Suka, banyak. Mungkinkah itu fetish yang aneh?)",
  ui_story_5040_50400301_117_dialog_content = "Dan kalian ingin pergi ke Lumopolis juga?",
  ui_story_5040_50400301_118_dialog_content = "Aku ingin mengajaknya berkeliling selama festival. Bisakah Anda membawa kami bersamamu? Kebetulan saya juga punya beberapa surat yang harus saya kirimkan ke Lumopolis.",
  ui_story_5040_50400301_119_dialog_content = "Tentu saja! Jika Anda sudah siap, kita bisa pergi sekarang.",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>Soroz</color>",
  ui_story_5040_50400301_121_dialog_content = "Apakah Anda tidak akan beristirahat, Jeriah?",
  ui_story_5040_50400301_122_dialog_content = "Hehe... Membaca adalah istirahat bagiku.",
  ui_story_5040_50400301_123_dialog_content = "Dan aku tidak lelah.",
  ui_story_5040_50400301_124_dialog_content = "Tidurlah jika kau lelah, Caelestite kecil.",
  ui_story_5040_50400301_125_dialog_content = "Wow, itu mengesankan. Aku bahkan tidak mengerti apa yang kamu baca.",
  ui_story_5040_50400301_126_dialog_content = "Kita masing-masing memiliki minat kita. Saya senang membaca teks-teks kuno.",
  ui_story_5040_50400301_127_dialog_content = "Jauh lebih santai daripada berurusan dengan Aurorians.",
  ui_story_5040_50400301_128_dialog_content = "Hah?",
  ui_story_5040_50400301_129_dialog_content = "Omong-omong, saat kita sampai di Lumopolis, apa kau akan mencari Naroxel?",
  ui_story_5040_50400301_130_dialog_content = "Kami masih memiliki hal-hal yang harus dilakukan; Aku akan berbicara dengannya dulu begitu kita sampai di sana.",
  ui_story_5040_50400301_131_dialog_content = "Aaaa!!",
  ui_story_5040_50400301_132_dialog_content = "?!",
  ui_story_5040_50400301_133_dialog_content = "Gerhana! Nona Jeriah, PlayerName, Hati-Hati!",
  ui_story_5040_50400301_134_dialog_content = "Tolong... ne...!",
  ui_story_5040_50400301_135_dialog_content = "Bagaimana Eclipsites bergabung? Apakah mereka mengikuti seseorang?",
  ui_story_5040_50400301_136_dialog_content = "Kita bisa membicarakannya nanti. Mari kita tangani hal-hal yang tidak sedap dipandang itu terlebih dahulu.",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>Setelah berurusan dengan Eclipsites, semua orang berhasil beristirahat. Mereka tiba dengan selamat dan sehat di Lumopolis...</color>",
  ui_story_5040_50400302_2_dialog_content = "Fiuh, itu pemeriksaan pabean yang ketat, tapi untungnya, mereka tidak mempersulitnya.",
  ui_story_5040_50400302_3_dialog_content = "(Jika Caelestite tidak menjamin kami, penyamaran Sable akan terbongkar. Syukurlah kami bisa ikut untuk masuk ke kota.)",
  ui_story_5040_50400302_4_dialog_content = "PlayerName! Nona Jeriah! Saya akan menunjukkan kerabat saya di sekitar kota, dan mengirimkan beberapa surat saat saya melakukannya! Sampai jumpa lagi!",
  ui_story_5040_50400302_5_dialog_content = "Dia baru saja lepas landas!",
  ui_story_5040_50400302_6_dialog_content = "...",
  ui_story_5040_50400302_7_dialog_content = "Wow... Jadi ini Lumopolis! Ini tentu memiliki getaran yang sangat berbeda.",
  ui_story_5040_50400302_8_dialog_content = "Bagaimana menurutmu, Tar?",
  ui_story_5040_50400302_9_dialog_content = "... Ini bukan pertama kalinya saya di sini.",
  ui_story_5040_50400302_10_dialog_content = "B-Baik...",
  ui_story_5040_50400302_11_dialog_content = "Jangan buang waktu. Kita harus mencari Naroxel.",
  ui_story_5040_50400302_12_dialog_content = "Naroksel! Sudah selamanya!",
  ui_story_5040_50400302_13_dialog_content = "Tunggu, siapa... Adonis?!",
  ui_story_5040_50400302_14_dialog_content = "Sudah lama sekali! Apa yang membawamu ke Lumopolis? Apakah orang tua Anda dan Pak Novio baik-baik saja?",
  ui_story_5040_50400302_15_dialog_content = "Semua orang baik-baik saja.",
  ui_story_5040_50400302_16_dialog_content = "Dan ini yang selalu kusebutkan dalam surat-suratku, Tara.",
  ui_story_5040_50400302_17_dialog_content = "...",
  ui_story_5040_50400302_18_dialog_content = "Sebenarnya, Naroxel, kami kembali ke Lumopolis karena ada sedikit situasi...",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>Setelah menceritakan kisah itu kepada Naroxel...</color>",
  ui_story_5040_50400302_20_dialog_content = "Kenapa begitu?",
  ui_story_5040_50400302_21_dialog_content = "Aku belum pernah mendengar ramuan yang bisa menghapus ingatan orang.",
  ui_story_5040_50400302_22_dialog_content = "Ya, saya juga merasa sulit untuk membungkus kepala saya.",
  ui_story_5040_50400302_23_dialog_content = "Apakah ada yang bisa saya bantu? Apa-apa? Kami teman lama, jadi jangan takut untuk bertanya.",
  ui_story_5040_50400302_24_dialog_content = "Sebenarnya, Jeriah menyarankan agar kami ikut serta dalam acara Mooncrown Day yang diadakan oleh Courier Union di berbagai kota untuk mendapatkan Feather Seals!",
  ui_story_5040_50400302_25_dialog_content = "Ini adalah kesempatan bagus untuk mengunjungi tempat-tempat baru, dan mungkin menemukan beberapa petunjuk untuk menyembuhkan amnesia Tara.",
  ui_story_5040_50400302_26_dialog_content = "Segel Bulu?",
  ui_story_5040_50400302_27_dialog_content = "Memang benar, Serikat Kurir memang menawarkan tantangan khusus bagi pasangan setiap Hari Mahkota Bulan.",
  ui_story_5040_50400302_28_dialog_content = "Namun…",
  ui_story_5040_50400302_29_dialog_content = "Tapi apa? Apakah ada masalah?",
  ui_story_5040_50400302_30_dialog_content = "Kami teman lama. Saya ingat sering melihat Anda dan Tuan Novio ketika saya belajar dengan ratu di Istana Musim Dingin.",
  ui_story_5040_50400302_31_dialog_content = "Dan itulah mengapa saya berharap pilihan Anda untuk menghadapi tantangan hidup bersama Tara adalah pilihan yang bijaksana, di atas segalanya.",
  ui_story_5040_50400302_32_dialog_content = "Hari Mooncrown, acara Courier Union, apa pun ... Semuanya dangkal.",
  ui_story_5040_50400302_33_dialog_content = "Ya, aku mengerti.",
  ui_story_5040_50400302_34_dialog_content = "Saya akan mendukung Anda, jika Anda ingin memanfaatkan kesempatan ini.",
  ui_story_5040_50400302_35_dialog_content = "Terima kasih, Naroxel!",
  ui_story_5040_50400302_36_dialog_content = "Adapun acara Mooncrown Day ...",
  ui_story_5040_50400302_37_dialog_content = "Ini adalah buku prangko peringatan khusus, yang dikeluarkan oleh Courier Union untuk merayakan Hari Mooncrown tahun ini. Jual semuanya, dan Anda lulus ujian.",
  ui_story_5040_50400302_38_dialog_content = "Itu akan mudah! Benar, Tara?",
  ui_story_5040_50400302_39_dialog_content = "Mungkin.",
  ui_story_5040_50400302_40_dialog_content = "Tapi aku belum pernah melakukan pekerjaan fiddly seperti sebelumnya.",
  ui_story_5040_50400302_41_dialog_content = "Jika kita bekerja sama, kita tidak akan memiliki masalah. Ayo! Mari kita mulai.",
  ui_story_5040_50400302_42_dialog_content = "Semoga berhasil!",
  ui_story_5040_50400302_43_dialog_content = "Terima kasih, PlayerName. Dan kamu juga, Jeriah.",
  ui_story_5040_50400302_44_dialog_content = "Tapi sepertinya mereka berniat untuk pergi ke divisi Courier Union lainnya. Bisakah saya menyusahkan Anda untuk mengawal mereka beberapa kali lagi, PlayerName?",
  ui_story_5040_50400302_45_dialog_content = "Tentu! Apa pun yang bisa saya lakukan untuk membantu.",
  ui_story_5040_50400302_46_dialog_content = "Tapi istirahatlah dulu.",
  ui_story_5040_50400302_47_dialog_content = "Saya akan menemani mereka selama tantangan.",
  ui_story_5040_50400302_48_dialog_content = "Jika saya bisa bicara, Jeriah?",
  ui_story_5040_50400302_49_dialog_content = "...",
  ui_story_5040_50400302_50_dialog_content = "Apakah ada sesuatu yang ingin Anda katakan kepada saya?",
  ui_story_5040_50400302_51_dialog_content = "Hehe... Apakah Anda mendapatkan sesuatu yang khusus?",
  ui_story_5040_50400302_52_dialog_content = "Sekarang, jangan bermain bodoh denganku. Tahukah Anda apa isi semua paket yang dikirim ke Lumopolis dari Rediesel?",
  ui_story_5040_50400302_53_dialog_content = "Hm, aku bertanya-tanya? Aku tidak benar-benar memeriksa.",
  ui_story_5040_50400302_54_dialog_content = "Bagaimana Anda bisa meneruskannya tanpa memeriksa...? Eho dan saya sudah punya banyak di piring kami.",
  ui_story_5040_50400302_55_dialog_content = "Bahkan sebelum festival, banyak hal menumpuk, tetapi sekarang Persatuan Kurir Lumopolis benar-benar kehabisan akal.",
  ui_story_5040_50400302_56_dialog_content = "Saya tidak memberi tahu atasan tentang hal ini, kalau tidak saya cukup yakin Anda harus menghadapi kuliah ketika Anda kembali.",
  ui_story_5040_50400302_57_dialog_content = "Jadi aku berhutang satu padamu. Tapi itu sebabnya aku berlari mengelilingi Northland untukmu.",
  ui_story_5040_50400302_58_dialog_content = "Huh, aku tidak pernah menyangka hal seperti ini akan terjadi pada Adonis.",
  ui_story_5040_50400302_59_dialog_content = "Bantulah saya dan terus bantu mereka.",
  ui_story_5040_50400302_60_dialog_content = "Sungguh merepotkan... dan saya tidak tahu mengapa mereka begitu bertekad untuk mengikat diri satu sama lain padahal mereka jelas bukan pasangan yang cocok.",
  ui_story_5040_50400302_61_dialog_content = "Bukankah Anda sering mengatakan bahwa setiap individu itu rumit?",
  ui_story_5040_50400302_62_dialog_content = "Anda akan mengerti suatu hari nanti, Jeriah. Tidak ada yang menjalani hidup sendirian selamanya.",
  ui_story_5040_50400302_63_dialog_content = "Ini prangko yang perlu kita bagikan, Tara.",
  ui_story_5040_50400302_64_dialog_content = "Anda biasa mengirimi saya cap Hari Mahkota Bulan setiap tahun, ingat? Saya menyelamatkan mereka satu per satu.",
  ui_story_5040_50400302_65_dialog_content = "Benar-benar? Saya tidak ingat.",
  ui_story_5040_50400302_66_dialog_content = "Itu benar. Mulai sekarang, aku yang akan memberikannya padamu! Bukankah desain tahun ini cukup keren?",
  ui_story_5040_50400302_67_dialog_content = "Ah...! Kemasannya!",
  ui_story_5040_50400302_68_dialog_content = "Awas!",
  ui_story_5040_50400302_69_dialog_content = "Syukurlah itu tidak jatuh ke tanah.",
  ui_story_5040_50400302_70_dialog_content = "Sudah kubilang aku tidak pandai dalam pekerjaan rumit semacam ini. Menjual persenjataan dan barang-barang, sekarang lebih sesuai keinginan saya.",
  ui_story_5040_50400302_71_dialog_content = "Sangat normal bagi orang untuk memiliki bakat yang berbeda. Tidak ada individu yang sama.",
  ui_story_5040_50400302_72_dialog_content = "Jangan khawatir tentang mengantongi barang dagangan. Saya akan mengurus itu, Anda menangani pelanggan.",
  ui_story_5040_50400302_73_dialog_content = "Setidaknya aku harus bisa melakukan itu.",
  ui_story_5040_50400302_74_dialog_content = "<color=#e8d9bb>Sesaat kemudian...</color>",
  ui_story_5040_50400302_75_dialog_content = "Bisakah saya juga memiliki beberapa prangko peringatan tahun ini?",
  ui_story_5040_50400302_76_dialog_content = "Kenapa milikku masih belum siap?",
  ui_story_5040_50400302_77_dialog_content = "Tolong, jangan khawatir. Perangko Mooncrown Day spesial, jadi kami harus memastikan perangko disajikan dengan sempurna dan terbungkus rapat. Apakah kamu tidak setuju?",
  ui_story_5040_50400302_78_dialog_content = "Ini dia!",
  ui_story_5040_50400302_79_dialog_content = "Apakah kamu baik-baik saja di sana, Tara?",
  ui_story_5040_50400302_80_dialog_content = "Saya pikir Anda harus lebih khawatir tentang prangko yang Anda tangani. Lagipula aku hanya berbicara.",
  ui_story_5040_50400302_81_dialog_content = "Sepertinya bisnis berjalan baik di sini.",
  ui_story_5040_50400302_82_dialog_content = "Ya! Sudah cukup mulus sejauh ini.",
  ui_story_5040_50400302_83_dialog_content = "Coba saya lihat... tidak banyak yang tersisa! Selamat beres.",
  ui_story_5040_50400302_84_dialog_content = "Ya! Yang terakhir terjual, selesai!",
  ui_story_5040_50400302_85_dialog_content = "Fiuh, itu kerja keras.",
  ui_story_5040_50400302_86_dialog_content = "Baik dilakukan untuk Anda berdua.",
  ui_story_5040_50400302_87_dialog_content = "Anda setidaknya bisa berpura-pura terdengar sedikit lebih tulus.",
  ui_story_5040_50400302_88_dialog_content = "*Menguap* Permisi, apakah Anda menjual prangko Courier Union di sini?",
  ui_story_5040_50400302_89_dialog_content = "Ya, tapi sayangnya kami baru saja terjual habis.",
  ui_story_5040_50400302_90_dialog_content = "Mereka sangat imut tahun ini, tapi saya tidak datang ke sini untuk membeli prangko.",
  ui_story_5040_50400302_91_dialog_content = "Saya bertanya-tanya apakah Anda memiliki perangko Hari Mahkota Bulan tahun lalu yang tergeletak di suatu tempat. Jika Anda melakukannya... Saya akan membayar premi untuk mereka.",
  ui_story_5040_50400302_92_dialog_content = "Anu…",
  ui_story_5040_50400302_93_dialog_content = "Kami hanya bantuan sementara. Yeriah, tahukah kamu?",
  ui_story_5040_50400302_94_dialog_content = "Prangko Courier Union itu semuanya edisi terbatas dan kami tidak menyimpan cadangannya.",
  ui_story_5040_50400302_95_dialog_content = "Saya khawatir Anda tidak akan bisa mendapatkannya dari saluran resmi.",
  ui_story_5040_50400302_96_dialog_content = "Oh begitu. Apa yang akan aku lakukan...?",
  ui_story_5040_50400302_97_dialog_content = "Apa masalahnya?",
  ui_story_5040_50400302_98_dialog_content = "Eh... Sejujurnya, seorang teman meminta saya untuk mendapatkannya.",
  ui_story_5040_50400302_99_dialog_content = "Dia mengirimkan prangko Mooncrown Day kepada rekannya di Illumina setiap tahun.",
  ui_story_5040_50400302_100_dialog_content = "Namun, keluarganya sedikit konservatif dan dengan tegas menentang hubungan mereka.",
  ui_story_5040_50400302_101_dialog_content = "Itu sebabnya dia meminta saya untuk membelikannya perangko dan alat tulis secara rahasia.",
  ui_story_5040_50400302_102_dialog_content = "Ha! Sangat Lumopolis.",
  ui_story_5040_50400302_103_dialog_content = "Hah? Apakah kebiasaan di Lumopolis memberi prangko?",
  ui_story_5040_50400302_104_dialog_content = "Pasangan di Lumopolis mengirim mereka satu sama lain pada Hari Mooncrown, tapi saya pikir para bangsawan memiliki praktik yang lebih boros.",
  ui_story_5040_50400302_105_dialog_content = "Memang. Saya lebih suka meringkuk di tempat tidur untuk tidur daripada berpartisipasi dalam sandiwara ini.",
  ui_story_5040_50400302_106_dialog_content = "Tapi masalahnya adalah rekannya kehilangan prangko peringatan dari tahun lalu...",
  ui_story_5040_50400302_107_dialog_content = "Dia merasa sangat bersalah dan sedih karenanya. Teman saya tidak tahan melihatnya begitu kesal, jadi dia meminta saya untuk mencari salinan lain dari prangko itu untuknya.",
  ui_story_5040_50400302_108_dialog_content = "Itu hanya perangko. Tidak bisakah dia memberinya sesuatu yang lain?",
  ui_story_5040_50400302_109_dialog_content = "Itu sama sekali tidak sama! Anda tidak bisa begitu saja mengganti sesuatu yang penuh dengan kenangan bersama dengan sesuatu yang lain.",
  ui_story_5040_50400302_110_dialog_content = "Seorang bangsawan Lumo, dan seorang gadis Illuminan... Menarik.",
  ui_story_5040_50400302_111_dialog_content = "Mereka harus menghadapi segala macam hambatan dalam hubungan mereka.",
  ui_story_5040_50400302_112_dialog_content = "Yah, masih ada cahaya di ujung terowongan untuk mereka. Tapi saya kira Anda bisa mengatakan mereka memiliki jalan berbatu di depan mereka.",
  ui_story_5040_50400302_113_dialog_content = "Dia perlahan berusaha meyakinkan orang tuanya dan kerabat lainnya, mencoba mengajak mereka berkeliling.",
  ui_story_5040_50400302_114_dialog_content = "Ini mungkin masih akan memakan waktu.",
  ui_story_5040_50400302_115_dialog_content = "Lumopolis benar-benar memenuhi reputasinya sebagai tempat di mana keluarga terobsesi untuk menikah di dalam kelas Anda.",
  ui_story_5040_50400302_116_dialog_content = "Ya? Jika Anda bertanya kepada saya, bahkan dua orang dari keluarga bangsawan pun tidak otomatis menjamin kebahagiaan bersama.",
  ui_story_5040_50400302_117_dialog_content = "Hall of Justice tempat saya bekerja menerima petisi cerai dari para bangsawan sepanjang waktu.",
  ui_story_5040_50400302_118_dialog_content = "Setiap kasus memiliki liku-liku anehnya sendiri, dan tidak pernah jelas, berkat perselisihan kepentingan antara bangsawan.",
  ui_story_5040_50400302_119_dialog_content = "Semua orang berusaha menghindari mengambil kasus-kasus itu.",
  ui_story_5040_50400302_120_dialog_content = "Jadi bahkan bangsawan pun bisa mendapat masalah di surga...",
  ui_story_5040_50400302_121_dialog_content = "Oh, pasti! Jadi saran saya adalah selalu ikuti kata hati Anda.",
  ui_story_5040_50400302_122_dialog_content = "Lagi pula, menerima seseorang dengan status yang sama tidak menjamin kebahagiaan.",
  ui_story_5040_50400302_123_dialog_content = "Betapa jarang mendengar kata-kata seperti itu dari mulut bangsawan Lumopolis!",
  ui_story_5040_50400302_124_dialog_content = "Saya hanya bisa mengatakan bahwa setiap orang membuat pilihannya sendiri. Perasaan tidak bisa dikendalikan. Cinta adalah cinta.",
  ui_story_5040_50400302_125_dialog_content = "Jatuh cinta pada seseorang bukanlah sesuatu yang bisa dikendalikan oleh siapa pun. Tidak peduli siapa mereka atau dari mana mereka berasal.",
  ui_story_5040_50400302_126_dialog_content = "Saya tahu ini dengan sangat baik.",
  ui_story_5040_50400302_127_dialog_content = "Memang benar! Saya sangat setuju!",
  ui_story_5040_50400302_128_dialog_content = "Oh? Mungkinkah Anda memiliki seseorang di pikiran Anda?",
  ui_story_5040_50400302_129_dialog_content = "Tidak... Hanya saja aku kebetulan bertemu dengan pria kecil yang lucu dan berbulu beberapa waktu lalu.",
  ui_story_5040_50400302_130_dialog_content = "Itu juga bisa berbicara Universese! Saya tidak bisa mempercayainya.",
  ui_story_5040_50400302_131_dialog_content = "Sebenarnya, saya mengirimnya surat kemarin. Entah kapan saya akan menerima tanggapan.",
  ui_story_5040_50400302_132_dialog_content = "Apakah benar-benar tidak ada yang bisa kita lakukan untuk membantu temannya, Jeriah?",
  ui_story_5040_50400302_133_dialog_content = "...",
  ui_story_5040_50400302_134_dialog_content = "Yah, aku tidak benar-benar tahu, tapi...",
  ui_story_5040_50400302_135_dialog_content = "Jika dia mau membayar, mungkin ada baiknya mengajak Allura ke Umbraton. Koleksinya cukup banyak.",
  ui_story_5040_50400302_136_dialog_content = "Saya yakin hal sekecil itu tidak akan menjadi masalah.",
  ui_story_5040_50400302_137_dialog_content = "Jadi begitu! Terima kasih banyak atas bantuan Anda!",
  ui_story_5040_50400302_138_dialog_content = "Sebaiknya aku pergi ke Umbraton sekarang, sementara aku belum mengantuk.",
  ui_story_5040_50400302_139_dialog_content = "Kau seperti ensiklopedia berjalan, Jeriah.",
  ui_story_5040_50400302_140_dialog_content = "Saya harap dia menemukan apa yang dia cari.",
  ui_story_5040_50400302_141_dialog_content = "Either way, kami menyelesaikan tugas! Ayo ambil segel itu!",
  ui_story_5040_50400302_142_dialog_content = "Tentu saja…",
  ui_story_5040_50400302_143_dialog_content = "Ada apa, Tar? Apakah merasa baik-baik saja?",
  ui_story_5040_50400302_144_dialog_content = "Tidak apa-apa, aku baik-baik saja.",
  ui_story_5040_50400302_145_dialog_content = "...",
  ui_story_5040_50400302_146_dialog_content = "<color=#e8d9bb>Sementara itu...</color>",
  ui_story_5040_50400302_147_dialog_content = "Tidak ada sama sekali...?",
  ui_story_5040_50400302_148_dialog_content = "Apakah Anda masih tidak ingat apa-apa?",
  ui_story_5040_50400302_149_dialog_content = "Tidak... Tidak ada... Maaf...",
  ui_story_5040_50400302_150_dialog_content = "Anda tidak perlu meminta maaf, Anda tidak melakukan kesalahan apa pun.",
  ui_story_5040_50400302_151_dialog_content = "Apa lagi yang bisa memberi kita petunjuk...?",
  ui_story_5040_50400302_152_dialog_content = "Ah... Itu...",
  ui_story_5040_50400302_153_dialog_content = "Apa?",
  ui_story_5040_50400302_154_dialog_content = "Memegang ... di ... tangan ...",
  ui_story_5040_50400302_155_dialog_content = "Siapa? Memegang apa?",
  ui_story_5040_50400302_156_dialog_content = "Dia...",
  ui_story_5040_50400302_157_dialog_content = "Perangko...",
  ui_story_5040_50400302_158_dialog_content = "Perangko?? Pria yang baru saja lewat itu? Ya, dia punya perangko Mooncrown Day itu.",
  ui_story_5040_50400302_159_dialog_content = "Apakah mereka mengingatkan Anda pada sesuatu?",
  ui_story_5040_50400302_160_dialog_content = "Sepertinya... ya...",
  ui_story_5040_50400302_161_dialog_content = "Hah? Dari mana Anda mendapatkan ini? Ini semua sepertinya perangko Hari Mahkota Bulan kuno!",
  ui_story_5040_50400302_162_dialog_content = "Pikir... aku punya... banyak...",
  ui_story_5040_50400302_163_dialog_content = "Banyak apa? Perangko seperti ini?",
  ui_story_5040_50400302_164_dialog_content = "Ya…",
  ui_story_5040_50400302_165_dialog_content = "Biasanya kalau orang punya banyak stempel, berarti kiriman suratnya banyak kan?",
  ui_story_5040_50400302_166_dialog_content = "Itu memberi saya ide! Mengapa saya tidak mengajak Anda melihat-lihat surat Union yang tidak diklaim? Mungkin kita akan menemukan sesuatu.",
  ui_story_5040_50400302_167_dialog_content = "Terima kasih...Kya...",
  ui_story_5040_50400302_168_dialog_content = "<color=#e8d9bb>Sesaat kemudian...</color>",
  ui_story_5040_50400302_169_dialog_content = "Tidak ada apa-apa?",
  ui_story_5040_50400302_170_dialog_content = "Tidak...",
  ui_story_5040_50400302_171_dialog_content = "Hmm. Yah, mungkin Anda berada di wilayah Union yang berbeda dari Lumopolis.",
  ui_story_5040_50400302_172_dialog_content = "Setidaknya kita memiliki petunjuk sekarang. Ini lebih baik daripada hanya berkeliaran tanpa tujuan seperti sebelumnya.",
  ui_story_5040_50400302_173_dialog_content = "Mari kita tag bersama PlayerName dan yang lainnya dan periksa divisi Illumina dan Rediesel Wrench.",
  ui_story_5040_50400302_174_dialog_content = "Jangan khawatir. Kami akan menemukannya!",
  ui_story_5040_50400302_175_dialog_content = "K... Kya...",
  ui_story_5040_50400302_176_dialog_content = "Terima kasih…",
  ui_story_5040_50400302_177_dialog_content = "Mengapa Anda... membantu... saya...?",
  ui_story_5040_50400302_178_dialog_content = "Aku tidak benar-benar tahu diri. Mungkin saya tidak bisa lewat ketika seseorang membutuhkan bantuan.",
  ui_story_5040_50400302_179_dialog_content = "(Aku pasti gila, membantu Eclipsite! Apa sih yang kupikirkan?!)",
  ui_story_5040_50400302_180_dialog_content = "(Apa yang akan Emerald lakukan?)",
  ui_story_5040_50400401_1_dialog_content = "<color=#e8d9bb>Setelah Adonis dan yang lainnya melapor kembali ke Naroxel...</color>",
  ui_story_5040_50400401_2_dialog_content = "Jadi ini adalah Segel Bulu Serikat Kurir? Saya belum pernah melihatnya sebelumnya.",
  ui_story_5040_50400401_3_dialog_content = "Ini terlihat dibuat dengan sangat baik!",
  ui_story_5040_50400401_4_dialog_content = "Ayo lihat, Tara!",
  ui_story_5040_50400401_5_dialog_content = "... Jangan tiba-tiba bertingkah seolah kita sangat akrab atau semacamnya.",
  ui_story_5040_50400401_6_dialog_content = "Segel Bulu sebagian besar adalah benda peringatan. Mereka sendiri memiliki nilai moneter yang sangat kecil.",
  ui_story_5040_50400401_7_dialog_content = "Bahkan sebelum Union ada, kurir disambut sebagai pembawa kabar baik kemanapun mereka pergi.",
  ui_story_5040_50400401_8_dialog_content = "Apakah bangsawan juga menyewa kurir untuk pernikahan?",
  ui_story_5040_50400401_9_dialog_content = "Ya, tapi terutama para bangsawan Lumopolis. Faktanya, banyak yang akan menghabiskan banyak uang untuk menyewa kurir untuk menjadi saksi dalam pernikahan mereka.",
  ui_story_5040_50400401_10_dialog_content = "Ini juga mengapa Serikat Kurir berusaha menghapus tradisi ini dengan sesuatu yang lain.",
  ui_story_5040_50400401_11_dialog_content = "Terutama di Lumopolis. Hari Mahkota Bulan berasal dari sini, jadi orang-orang di sini menganggap serius tradisinya.",
  ui_story_5040_50400401_12_dialog_content = "Benar-benar sekelompok orang aneh. Kami tidak merayakan liburan sia-sia seperti ini di padang pasir.",
  ui_story_5040_50400401_13_dialog_content = "Apa yang salah dengan mengamati hari libur? Apalagi yang satu ini sangat romantis.",
  ui_story_5040_50400401_14_dialog_content = "Di Lumopolis, di mana semua masyarakat sangat terstratifikasi, jenis formalitas ini hanyalah sarana untuk mengendalikan kelas bawah.",
  ui_story_5040_50400401_15_dialog_content = "Ini, pada gilirannya, adalah alasan pentingnya mereka sangat ditekankan.",
  ui_story_5040_50400401_16_dialog_content = "Itu banyak yang harus diambil ...",
  ui_story_5040_50400401_17_dialog_content = "Dia selalu bercerita tentang hal-hal yang tidak bisa aku mengerti.",
  ui_story_5040_50400401_18_dialog_content = "Jadi apa yang harus kita ketahui?",
  ui_story_5040_50400401_19_dialog_content = "Yeriah, ayo jalan-jalan. Aku perlu mengalihkan pikiranku dari berbagai hal.",
  ui_story_5040_50400401_20_dialog_content = "Lalu aku akan pergi dengan—",
  ui_story_5040_50400401_21_dialog_content = "PlayerName, bagaimana kalau Anda bermitra dengannya untuk saat ini? Aku butuh kedamaian dan ketenangan saat ini.",
  ui_story_5040_50400401_22_dialog_content = "Tentu, itu berhasil.",
  ui_story_5040_50400401_23_dialog_content = "...",
  ui_story_5040_50400401_24_dialog_content = "Huh...",
  ui_story_5040_50400401_25_dialog_content = "Apakah Anda lelah dengan tindakan kecil Anda?",
  ui_story_5040_50400401_26_dialog_content = "Aku hanya... Aku tidak tahu apakah aku melakukan hal yang benar. Adonis sepertinya benar-benar percaya bahwa aku kehilangan ingatanku.",
  ui_story_5040_50400401_27_dialog_content = "Saya sangat berkonflik. Dulu ketika kami menjual prangko bersama, aku merasa dia masih orang yang baik dan lembut yang selalu kukenal.",
  ui_story_5040_50400401_28_dialog_content = "Tapi itu tidak menyelesaikan semua masalah di antara kita. Aku tahu begitu sesuatu yang besar terjadi, dia akan kembali menjadi pengecut.",
  ui_story_5040_50400401_29_dialog_content = "Mungkin kita benar-benar terlalu berbeda untuk bersama.",
  ui_story_5040_50400401_30_dialog_content = "Kecuali karena aku sangat menyukainya, sulit bagiku untuk menerima kenyataan itu.",
  ui_story_5040_50400401_31_dialog_content = "Kita bisa memilih untuk menjadi siapapun yang kita mau, tapi kita tidak bisa memaksa orang lain untuk menjadi seperti yang kita inginkan.",
  ui_story_5040_50400401_32_dialog_content = "Ketika Anda memilih untuk bersama seseorang, Anda harus mengambil semua yang datang setelahnya.",
  ui_story_5040_50400401_33_dialog_content = "Semakin kau mencintai seseorang, semakin menyakitkan melepaskannya.",
  ui_story_5040_50400401_34_dialog_content = "... Apakah Anda berbicara dari pengalaman?",
  ui_story_5040_50400401_35_dialog_content = "Tentu saja tidak. Mengapa saya secara sadar membiarkan diri saya mengalami rasa sakit seperti itu?",
  ui_story_5040_50400401_36_dialog_content = "Tetap saja, bersamanya membuatku sangat senang. Sebagian besar waktu yang kami habiskan bersama terasa bahagia.",
  ui_story_5040_50400401_37_dialog_content = "Anda bisa saja memproyeksikan karena merasa tidak aman tentang hubungan Anda. Pada akhirnya, hubungan adalah tentang bertukar nilai.",
  ui_story_5040_50400401_38_dialog_content = "Dan saat ini, apa yang dia tawarkan tidak memenuhi harapan Anda. Bukankah itu benar?",
  ui_story_5040_50400401_39_dialog_content = "Aku…",
  ui_story_5040_50400401_40_dialog_content = "Aku tidak tahu... Aku tidak ingin melihat hubungan kita seperti itu, seperti tidak lebih dari sebuah transaksi.",
  ui_story_5040_50400401_41_dialog_content = "Hmph. Apa pun.",
  ui_story_5040_50400401_42_dialog_content = "Kami membutuhkan pengalaman untuk mengetahui apa yang sebenarnya kami inginkan jauh di lubuk hati. Karena semuanya sudah seperti sekarang, saya tidak akan terlalu khawatir.",
  ui_story_5040_50400401_43_dialog_content = "Lagipula ini urusanmu. Apa yang orang lain katakan tidak masalah.",
  ui_story_5040_50400401_44_dialog_content = "Luangkan waktu sebanyak yang Anda butuhkan untuk mencari tahu, dan dengarkan hati Anda saat Anda akhirnya membuat pilihan.",
  ui_story_5040_50400401_45_dialog_content = "...",
  ui_story_5040_50400401_46_dialog_content = "Selamat datang di Umbraton! Terasa jauh berbeda dengan Lumopolis ya?",
  ui_story_5040_50400401_47_dialog_content = "Ya...",
  ui_story_5040_50400401_48_dialog_content = "Lihat pulau yang mengambang tepat di atas kita? Itu Lumopolis.",
  ui_story_5040_50400401_49_dialog_content = "Bagi banyak orang di Umbraton, liburan ini adalah kesempatan sempurna untuk meraup keuntungan.",
  ui_story_5040_50400401_50_dialog_content = "Ada banyak orang aneh di sini, tapi ada juga banyak hal menarik dan menarik.",
  ui_story_5040_50400401_51_dialog_content = "Apa pun yang Anda tertarik untuk memeriksa?",
  ui_story_5040_50400401_52_dialog_content = "...",
  ui_story_5040_50400401_53_dialog_content = "(Sudah berakhir... Dia tampaknya telah kehilangan semua energinya.)",
  ui_story_5040_50400401_54_dialog_content = "Sigh ... Aku tidak tahu harus berbuat apa lagi.",
  ui_story_5040_50400401_55_dialog_content = "Tidak ada yang saya lakukan benar... Kalau saja dia memberi saya petunjuk! Lalu mungkin aku akan tahu apa yang harus dilakukan...",
  ui_story_5040_50400401_56_dialog_content = "Eh...",
  ui_story_5040_50400401_57_dialog_content = "Kami biasa berbicara tentang segala hal, terutama tentang hal-hal yang tidak kami pahami tentang dunia kami. Tapi sekarang... bagaimana semuanya berakhir seperti ini?",
  ui_story_5040_50400401_58_dialog_content = "PlayerName, Anda seorang Caelestite, Anda harus memiliki gadis-gadis yang berbaris di luar pintu depan Anda. Apakah Anda mengerti apa yang saya alami?",
  ui_story_5040_50400401_59_dialog_content = "U-Uh, itu sedikit berlebihan.",
  ui_story_5040_50400401_60_dialog_content = "Tapi saya pikir selama perasaan dua orang satu sama lain cukup kuat, mereka dapat mengatasi kesulitan apa pun.",
  ui_story_5040_50400401_61_dialog_content = "Dua teman baik saya dan saya, kami telah melalui banyak hal bersama. Kami bahkan telah menyelamatkan satu sama lain dari ambang pintu kematian beberapa kali!",
  ui_story_5040_50400401_62_dialog_content = "Namun semua pengalaman itu memperkuat kepercayaan kami satu sama lain. Kami bersedia melakukan apa pun untuk satu sama lain, bahkan jika itu berarti membahayakan diri kami sendiri.",
  ui_story_5040_50400401_63_dialog_content = "Aku yakin kau dan Tara sama.",
  ui_story_5040_50400401_64_dialog_content = "T-Tentu saja aku akan melakukan apa saja untuknya! Aku bahkan mempertaruhkan nyawaku, jika harus!",
  ui_story_5040_50400401_65_dialog_content = "Hanya saja terkadang saya sangat ragu-ragu... Saya tidak bisa membuat keputusan sepersekian detik seperti orang lain. Itu mungkin alasan dia berpikir aku kurang sebagai laki-laki...",
  ui_story_5040_50400401_66_dialog_content = "Jangan katakan itu, Adonis! Siapa bilang seorang pria harus menjadi satu atau lain cara? Kita semua berbeda, dan tidak apa-apa.",
  ui_story_5040_50400401_67_dialog_content = "Tidak ada yang sempurna, tetapi jika kalian berdua masih bersama ... Itu berarti ada sesuatu tentang Anda yang menurutnya cukup menarik untuk dipertahankan!",
  ui_story_5040_50400401_68_dialog_content = "*Menangis* Aku... Aku hanya berharap dia benar-benar merasa seperti itu!!",
  ui_story_5040_50400401_69_dialog_content = "Di sana, di sana, jangan menangis...",
  ui_story_5040_50400401_70_dialog_content = "Oooooh!",
  ui_story_5040_50400401_71_dialog_content = "Apakah kita mengganggu momen yang indah dan gagah?",
  ui_story_5040_50400401_72_dialog_content = "Gin, saya merasa sangat terinspirasi!",
  ui_story_5040_50400401_73_dialog_content = "Terbelenggu oleh ekspektasi masyarakat, dua kekasih yang tidak bisa dilihat bersama—",
  ui_story_5040_50400401_74_dialog_content = "Mereka jelas berpelukan di siang bolong.",
  ui_story_5040_50400401_75_dialog_content = "Meskipun ini adalah Hari Mooncrown, kedua kekasih itu tidak punya pilihan selain bertemu di sudut Umbraton yang terpencil, jauh dari pengintaian—",
  ui_story_5040_50400401_76_dialog_content = "Ada orang di mana-mana ...",
  ui_story_5040_50400401_77_dialog_content = "Bukankah ini hal terindah yang pernah kamu lihat, Gin? Saya ingin melakukan segala daya saya untuk membantu mereka! Dan mungkin mendapatkan sedikit sesuatu untuk diri saya sendiri, selagi saya melakukannya!",
  ui_story_5040_50400401_78_dialog_content = "Kedengarannya seperti ide yang luar biasa.",
  ui_story_5040_50400401_79_dialog_content = "Eh, saya pikir Anda salah paham—",
  ui_story_5040_50400401_80_dialog_content = "Aku mengagumi keberanianmu, kawan. Bolehkah saya menanyakan nama Anda?",
  ui_story_5040_50400401_81_dialog_content = "A-Aku? Nama saya Adonis...",
  ui_story_5040_50400401_82_dialog_content = "Anda memiliki aura keagungan tentang diri Anda, Adonis. Yang menempatkan Anda jauh di atas orang lain, terutama pria di sebelah Anda.",
  ui_story_5040_50400401_83_dialog_content = "Kenapa tiba-tiba kau menembakku?!",
  ui_story_5040_50400401_84_dialog_content = "Anda harus menjadi tipe yang akan melakukan apa saja untuk cinta. Aku bisa tahu hanya dengan melihatmu.",
  ui_story_5040_50400401_85_dialog_content = "Permen lolipop saya juga merasakan hal yang sama.",
  ui_story_5040_50400401_86_dialog_content = "Tapi mari kita buang obrolan ringan yang tidak perlu. Untuk Hari Mahkota Bulan tahun ini, kami memiliki lukisan yang sangat langka untuk dijual, yang menurut saya sangat cocok untuk Anda.",
  ui_story_5040_50400401_87_dialog_content = "Ini menggambarkan kisah tragis cinta terlarang antara dua kekasih yang bernasib sial ...",
  ui_story_5040_50400401_88_dialog_content = "Lukisan langka dan indah ini dapat menjadi milik Anda dengan harga yang sangat wajar, tetapi hanya untuk hari ini!",
  ui_story_5040_50400401_89_dialog_content = "Uh... Apa? SAYA...",
  ui_story_5040_50400401_90_dialog_content = "Ah-ah-ah! Bukan kata lain! Jelas sekali bahwa Anda sangat ingin membeli lukisan ini!",
  ui_story_5040_50400401_91_dialog_content = "Aku setuju.",
  ui_story_5040_50400401_92_dialog_content = "Aku…",
  ui_story_5040_50400401_93_dialog_content = "Hentikan, kalian berdua!",
  ui_story_5040_50400401_94_dialog_content = "Jangan merusak pengalaman pertamanya di sini di Umbraton!",
  ui_story_5040_50400401_95_dialog_content = "Tolong, kami hanya mencoba mencari nafkah di sini. Kami hanya melakukan transaksi yang wajar dengan pria baik ini, tidak lebih.",
  ui_story_5040_50400401_96_dialog_content = "Tidak ada yang masuk akal tentang itu!!",
  ui_story_5040_50400401_97_dialog_content = "Saya ingin membuktikan bahwa Anda salah... tapi saya pikir saya baru saja mendengar sesuatu.",
  ui_story_5040_50400401_98_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5040_50400401_99_dialog_content = "Apa yang salah?!",
  ui_story_5040_50400401_100_dialog_content = "EE-Gerhana!",
  ui_story_5040_50400401_101_dialog_content = "Apa yang dilakukan Eclipsites di sini?!",
  ui_story_5040_50400401_102_dialog_content = "<size=45>Graah!</size>",
  ui_story_5040_50400401_103_dialog_content = "Menghalangi bisnisku, betapa menjengkelkannya.",
  ui_story_5040_50400401_104_dialog_content = "E-Eclipsite!",
  ui_story_5040_50400401_105_dialog_content = "Berlindung, Adonis! Kami akan menemukan cara untuk menangani ini!",
  ui_story_5040_50400402_1_dialog_content = "... Sobat, mereka berdua tidak menyia-nyiakan waktu, bukan?",
  ui_story_5040_50400402_2_dialog_content = "Apakah kamu baik-baik saja, Adonis?",
  ui_story_5040_50400402_3_dialog_content = "Y-Ya, aku baik-baik saja.",
  ui_story_5040_50400402_4_dialog_content = "Maaf karena sangat tidak berguna... Hanya dengan melihat Eclipsites itu membuat kakiku lepas dari bawah.",
  ui_story_5040_50400402_5_dialog_content = "Jangan khawatir tentang itu. Kebanyakan orang tidak terbiasa bertarung melawan monster-monster itu.",
  ui_story_5040_50400402_6_dialog_content = "Setidaknya Hachi dan Gin kabur. Mereka tidak mungkin.",
  ui_story_5040_50400402_7_dialog_content = "Orang-orang itu cenderung mencari target yang paling mudah, jadi ingatlah untuk menolaknya secara blak-blakan saat Anda bertemu mereka lagi.",
  ui_story_5040_50400402_8_dialog_content = "Huh... Kenapa aku selalu seperti ini?",
  ui_story_5040_50400402_9_dialog_content = "Maafkan saya, tetapi bukankah Anda menjual prangko Mooncrown Day sebelumnya?",
  ui_story_5040_50400402_10_dialog_content = "Hah?",
  ui_story_5040_50400402_11_dialog_content = "Apakah Anda berbicara tentang Adonis? Dia bersama Tara dan Jeriah dari Courier Union sebelumnya.",
  ui_story_5040_50400402_12_dialog_content = "Ah, jadi itu namamu.",
  ui_story_5040_50400402_13_dialog_content = "Siapa kamu...?",
  ui_story_5040_50400402_14_dialog_content = "Salam! Nama saya Tina, dan saya seorang hakim dari Lumo Hall of Justice. Mohon maaf sebelumnya saya lupa memperkenalkan diri.",
  ui_story_5040_50400402_15_dialog_content = "Senang bertemu denganmu, Tina. Saya PlayerName.",
  ui_story_5040_50400402_16_dialog_content = "Saya baru saja bertanya kepada teman-teman Anda tentang prangko Hari Mahkota Bulan tahun lalu pagi ini.",
  ui_story_5040_50400402_17_dialog_content = "Berkat kurir itu, saya menemukan apa yang saya cari di sini di Umbraton.",
  ui_story_5040_50400402_18_dialog_content = "Benar-benar? Ini semua berkat Jeriah... Aku senang dia bisa membantu, mengingat aku tidak bisa berbuat apa-apa.",
  ui_story_5040_50400402_19_dialog_content = "Bagaimanapun, saya yakin teman Anda dan kekasihnya senang Anda dapat menemukan prangko dari tahun lalu.",
  ui_story_5040_50400402_20_dialog_content = "Anda benar sekali. Dia praktis melompat kegirangan ketika saya memberikannya kepadanya.",
  ui_story_5040_50400402_21_dialog_content = "Dia mengucapkan terima kasih berulang kali sebelum akhirnya berlari pulang secepat mungkin untuk menulis surat cintanya.",
  ui_story_5040_50400402_22_dialog_content = "Pedagang tempat saya mendapatkannya membawa banyak barang menarik. Aku sedang dalam perjalanan untuk melihat lebih banyak barang dagangannya ketika aku bertemu kalian berdua.",
  ui_story_5040_50400402_23_dialog_content = "... Apakah Anda merasa baik-baik saja, Pak? Kamu terlihat agak pucat... Apa terjadi sesuatu?",
  ui_story_5040_50400402_24_dialog_content = "Sebenarnya saya...",
  ui_story_5040_50400402_25_dialog_content = "Ah... aku mengerti sekarang! Pantas saja aku merasa ada sesuatu yang aneh di antara kalian berdua!",
  ui_story_5040_50400402_26_dialog_content = "Jadi Anda akan pergi ke Illumina, ya? Kalau begitu, saya bisa bertanya kepada kekasih teman saya apakah dia tahu obatnya?",
  ui_story_5040_50400402_27_dialog_content = "H-Hah?",
  ui_story_5040_50400402_28_dialog_content = "Aku akan dimuka dengan Anda. Dia bekerja untuk Laboratorium Payung Hitam di Kota Gannon.",
  ui_story_5040_50400402_29_dialog_content = "Jika obatnya ada, pengetahuannya mungkin berguna bagi Anda! Sebut saja namaku padanya, dan dia akan membantumu sebisanya.",
  ui_story_5040_50400402_30_dialog_content = "Saya tidak dapat menjamin dia akan mendapatkan jawaban yang Anda cari, tetapi merujuk Anda kepadanya adalah yang paling tidak dapat saya lakukan untuk Anda.",
  ui_story_5040_50400402_31_dialog_content = "Itu lebih dari cukup! Terima kasih banyak, Nona Tina!",
  ui_story_5040_50400402_32_dialog_content = "Kami pasti akan mengunjunginya begitu kami berada di sana!",
  ui_story_5040_50400402_33_dialog_content = "Lihat, Adonis? Masih ada harapan untuk kalian!",
  ui_story_5040_50400402_34_dialog_content = "Saya berharap perjalanan Anda aman dan semoga sukses dalam perjalanan Anda.",
  ui_story_5040_50400402_35_dialog_content = "Yaaaaawn... Aku mulai merasa sedikit lelah. Saya pikir sudah waktunya untuk pulang dan beristirahat ...",
  ui_story_5040_50400402_36_dialog_content = "Sepertinya tekadmu akhirnya mulai membuahkan hasil, Adonis. Kami akan mengunjungi wanita itu segera setelah kami tiba di Kota Gannon.",
  ui_story_5040_50400402_37_dialog_content = "Ya! Terima kasih lagi, PlayerName.",
  ui_story_5040_50400402_38_dialog_content = "<color=#e8d9bb>Malam itu...</color>",
  ui_story_5040_50400402_39_dialog_content = "Sigh... Tempat ini juga tidak berhasil, ya?",
  ui_story_5040_50400402_40_dialog_content = "Aku... mencoba... yang terbaik...",
  ui_story_5040_50400402_41_dialog_content = "Maaf, saya tidak bermaksud membuat Anda stres. Tidak ada tekanan, ambil semua waktu yang Anda butuhkan.",
  ui_story_5040_50400402_42_dialog_content = "Lagi pula, kita harus kembali. Saya pikir kita telah membahas cukup banyak hal di Umbraton untuk hari ini.",
  ui_story_5040_50400402_43_dialog_content = "Lebih aman di Lumopolis pada malam hari.",
  ui_story_5040_50400402_44_dialog_content = "Umbra... ton... Lumo... poli...",
  ui_story_5040_50400402_45_dialog_content = "Lumopolis...",
  ui_story_5040_50400402_46_dialog_content = "Apa masalahnya? Mengapa Anda begitu terpaku pada Lumopolis?",
  ui_story_5040_50400402_47_dialog_content = "Apakah Anda ingat sesuatu?",
  ui_story_5040_50400402_48_dialog_content = "Lumopolis... Perjalanan panjang...",
  ui_story_5040_50400402_49_dialog_content = "Aku datang ke sini... untuk bertemu seseorang...",
  ui_story_5040_50400402_50_dialog_content = "Tapi siapa...? Siapa yang saya janjikan untuk bertemu... di Lumopolis...?",
  ui_story_5040_50400402_51_dialog_content = "Dia... Dia tidak pernah datang...",
  ui_story_5040_50400402_52_dialog_content = "Apa? Maksud Anda, Anda pernah datang ke Lumopolis dari tempat lain?",
  ui_story_5040_50400402_53_dialog_content = "Ya... aku... merasakannya...",
  ui_story_5040_50400402_54_dialog_content = "Itu berarti Anda bukan dari sekitar sini. Apakah Anda ingat dari mana Anda berasal?",
  ui_story_5040_50400402_55_dialog_content = "Saya pikir ... jauh, jauh ...",
  ui_story_5040_50400402_56_dialog_content = "Tempat yang jauh, ya? Jadi begitu...",
  ui_story_5040_50400402_57_dialog_content = "Sudahlah, jangan berlebihan. Karena Anda bukan dari Lumopolis, kami harus pergi ke tempat lain dan terus mencari.",
  ui_story_5040_50400402_58_dialog_content = "Menurut saya PlayerName dan yang lainnya akan pergi ke Kota Gannon besok. Mari kita tag bersama mereka.",
  ui_story_5040_50400402_59_dialog_content = "Mungkin Serikat Kurir di sana akan memberi kita beberapa jawaban.",
  ui_story_5040_50400402_60_dialog_content = "Baiklah…",
  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>Keesokan harinya...</color>",
  ui_story_5040_50400402_62_dialog_content = "Baiklah, apakah semua orang sudah siap? Jangan lupakan apa pun yang mungkin Anda butuhkan!",
  ui_story_5040_50400402_63_dialog_content = "Heheh... Aku sudah lama tidak ke Illumina. Aku ingin tahu bagaimana kabar burung-burung kecil itu?",
  ui_story_5040_50400402_64_dialog_content = "Tolong jangan membuat lebih banyak masalah bagi mereka, Jeriah.",
  ui_story_5040_50400402_65_dialog_content = "Federasi Illumina seharusnya menjadi negara yang sangat termiliterisasi, bukan? Tara menceritakan semuanya padaku sebelumnya... Aku selalu ingin melihatnya sendiri!",
  ui_story_5040_50400402_66_dialog_content = "Saya cukup tertarik melihat model truk terbaru mereka.",
  ui_story_5040_50400402_67_dialog_content = "Kalau begitu ayo berangkat!",
  ui_story_5040_50400502_1_dialog_content = "Wow... Jadi ini Kota Gannon!",
  ui_story_5040_50400502_2_dialog_content = "Saya sendiri baru sekali ke sini.",
  ui_story_5040_50400502_3_dialog_content = "Sepertinya tidak pernah banyak berubah, bukan?",
  ui_story_5040_50400502_4_dialog_content = "Apakah Anda sering datang ke Illumina, PlayerName?",
  ui_story_5040_50400502_5_dialog_content = "Tidak juga, tidak. Hanya saja salah satu teman terdekat saya berasal dari sini, jadi kami datang ke sini beberapa kali.",
  ui_story_5040_50400502_6_dialog_content = "Padahal dia sedang liburan sekarang. Saya tidak berpikir kita akan memiliki kesempatan untuk melihatnya hari ini.",
  ui_story_5040_50400502_7_dialog_content = "Apakah Kota Gannon tidak merayakan Hari Mahkota Bulan atau semacamnya? Tidak ada satu pun dekorasi yang terlihat di sekitar sini...",
  ui_story_5040_50400502_8_dialog_content = "Tentu saja mereka melakukannya, dan itu sama pentingnya bagi mereka juga.",
  ui_story_5040_50400502_9_dialog_content = "Tempat yang berbeda memiliki caranya sendiri dalam mengamati hari libur. Federasi Illumina tidak terlalu mementingkan arak-arakan, itu saja.",
  ui_story_5040_50400502_10_dialog_content = "Orang-orang di sini cenderung lebih pragmatis dan pendiam saat tampil di depan umum. Untuk liburan khusus ini, kebanyakan wanita menawarkan gulungan kayu manis buatan tangan kepada orang yang mereka sukai.",
  ui_story_5040_50400502_11_dialog_content = "Laki-laki, sebaliknya, melukis hati kecil di bagian dalam lengan baju mereka dan menuliskan nama orang yang mereka cintai di atasnya.",
  ui_story_5040_50400502_12_dialog_content = "Kedengarannya lucu, sebenarnya.",
  ui_story_5040_50400502_13_dialog_content = "Dan romantis! Saya ingin melakukannya juga!",
  ui_story_5040_50400502_14_dialog_content = "Eh...",
  ui_story_5040_50400502_15_dialog_content = "Anda yakin tahu banyak tentang dunia, Jeriah.",
  ui_story_5040_50400502_16_dialog_content = "Saya mendengar Jeriah telah melakukan perjalanan ke banyak tempat sebelumnya, tetapi dia jarang mengungkitnya.",
  ui_story_5040_50400502_17_dialog_content = "Oh, itu semua sejarah kuno. Nah, jika saya tidak salah, orang itu di sana ...",
  ui_story_5040_50400502_18_dialog_content = "?!?",
  ui_story_5040_50400502_19_dialog_content = "Itu pasti burung kecil Illumina.",
  ui_story_5040_50400502_20_dialog_content = "Merpati? Bukankah seharusnya kau mengantarkan surat sekarang?",
  ui_story_5040_50400502_21_dialog_content = "Mm, ya, itulah yang saya lakukan. Saya tidak akan bermain-main hanya karena ini hari libur.",
  ui_story_5040_50400502_22_dialog_content = "Saya hanya bekerja dengan kecepatan saya sendiri, itu saja.",
  ui_story_5040_50400502_23_dialog_content = "Anda terdengar benar-benar tidak dapat dipercaya...",
  ui_story_5040_50400502_24_dialog_content = "Jadi kamu Dove yang terkenal, ya? Saya pernah mendengar tentang Anda ... meskipun saya tidak bisa mengatakan semua itu positif.",
  ui_story_5040_50400502_25_dialog_content = "Bagaimana Anda bisa mengatakan itu? Saya bekerja sangat keras! Bukan salahku ada miliaran surat yang harus dikirimkan selama liburan ini.",
  ui_story_5040_50400502_26_dialog_content = "Tidak mungkin untuk mengirimkan semuanya, itu benar-benar mengacak-acak buluku, coo!",
  ui_story_5040_50400502_27_dialog_content = "Jadi, Anda memutuskan untuk mengendur sama sekali?",
  ui_story_5040_50400502_28_dialog_content = "Jangan pedulikan itu untuk saat ini. Apakah Anda tahu sesuatu tentang Segel Bulu Hari Mahkota Bulan?",
  ui_story_5040_50400502_29_dialog_content = "Segel Bulu? Saya memilikinya pada saya.",
  ui_story_5040_50400502_30_dialog_content = "Hah?!",
  ui_story_5040_50400502_31_dialog_content = "Semua atasan saya sangat sibuk melakukan pengiriman sekarang, mereka membiarkan saya bertanggung jawab untuk mengawasinya.",
  ui_story_5040_50400502_32_dialog_content = "Kedengarannya lebih seperti mereka tidak punya pilihan selain bekerja lembur karena seseorang tidak menarik beban mereka sendiri ...",
  ui_story_5040_50400502_33_dialog_content = "Mendekut! Maksudnya apa?!",
  ui_story_5040_50400502_34_dialog_content = "P-Pokoknya, kami hanya ingin mendapatkan stempel Feather Seal dari Courier Union of Illumina. Kami pasangan, Anda lihat ...",
  ui_story_5040_50400502_35_dialog_content = "Ah, begitu.",
  ui_story_5040_50400502_36_dialog_content = "Itu mudah, urus saja sisa kirimanku untukku.",
  ui_story_5040_50400502_37_dialog_content = "... Apakah itu diperbolehkan?!",
  ui_story_5040_50400502_38_dialog_content = "Yah, aku satu-satunya di sini, dan kebetulan aku juga memiliki Segel Bulu... Jadi pada dasarnya, aku bisa melakukan apapun yang aku mau.",
  ui_story_5040_50400502_39_dialog_content = "Saya benar-benar minta maaf, tetapi akan sangat bagus jika Anda bersedia membantu saya.",
  ui_story_5040_50400502_40_dialog_content = "Kita akan melakukannya! Serahkan saja pada kami!",
  ui_story_5040_50400502_41_dialog_content = "<color=#e8d9bb>Lima belas menit kemudian—</color>",
  ui_story_5040_50400502_42_dialog_content = "...",
  ui_story_5040_50400502_43_dialog_content = "...",
  ui_story_5040_50400502_44_dialog_content = "...",
  ui_story_5040_50400502_45_dialog_content = "Itu cukup banyak hal untuk disampaikan.",
  ui_story_5040_50400502_46_dialog_content = "\"Hanya beberapa bungkusan lagi,\" kakiku! Bagaimana dia bisa memasukkan semua ini ke sini?!",
  ui_story_5040_50400502_47_dialog_content = "Kami berdua tidak mungkin memberikan semua ini, bahkan jika kami bekerja tanpa istirahat selama tiga hari berturut-turut...",
  ui_story_5040_50400502_48_dialog_content = "Maaf... Saya tidak berpikir akan ada begitu banyak.",
  ui_story_5040_50400502_49_dialog_content = "Sepertinya kita tidak punya pilihan, guys. Mari kita mulai...",
  ui_story_5040_50400502_50_dialog_content = "Saya akan membantu juga, dan mengambil kesempatan untuk membawa Sable berkeliling kota.",
  ui_story_5040_50400502_51_dialog_content = "Maaf... Sepertinya kami menyeretmu ke dalam masalah kami sendiri lagi.",
  ui_story_5040_50400502_52_dialog_content = "Kami akan menangani bagian terbesar dari pengiriman. Saya cukup baik dalam pekerjaan fisik.",
  ui_story_5040_50400502_53_dialog_content = "Saya hanya akan berada di sini bersantai dengan buku saya, menyemangati kalian pergi.",
  ui_story_5040_50400502_54_dialog_content = "Jeriah... Huh, kurasa itu mungkin lebih baik. Kita tidak perlu hal-hal menjadi lebih buruk daripada yang sudah ada ...",
  ui_story_5040_50400502_55_dialog_content = "Baiklah! Mari kita mulai, semuanya!",
  ui_story_5040_50400502_56_dialog_content = "Ahhhh!",
  ui_story_5040_50400502_57_dialog_content = "Oi, cepatlah, Adonis!",
  ui_story_5040_50400502_58_dialog_content = "Aku... aku minta maaf! Tangga ini sangat curam...",
  ui_story_5040_50400502_59_dialog_content = "Jadilah sedikit lebih berhati-hati, kalau begitu!",
  ui_story_5040_50400502_60_dialog_content = "Di sini, mari kita berhenti dan memilah pengiriman kita. Anda mengambil yang lebih dekat, dan saya akan menangani yang lebih jauh.",
  ui_story_5040_50400502_61_dialog_content = "Tidak mungkin, ada terlalu banyak untuk Anda tangani sendiri.",
  ui_story_5040_50400502_62_dialog_content = "Jangan khawatir, aku sudah terbiasa berlarian seperti ini. Itu akan membuat pengiriman berjalan lebih cepat, percayalah.",
  ui_story_5040_50400502_63_dialog_content = "Oh… Baiklah.",
  ui_story_5040_50400502_64_dialog_content = "D-Pengiriman untukmu, Vivian!",
  ui_story_5040_50400502_65_dialog_content = "Ya ampun, jika tidak PlayerName! Bukankah kamu biasanya bersama V—",
  ui_story_5040_50400502_66_dialog_content = "Ya, ya. Ini paketmu, sampai jumpa lagi!",
  ui_story_5040_50400502_67_dialog_content = "Tapi mengapa Anda mengirimkan surat?",
  ui_story_5040_50400502_68_dialog_content = "... Dove, ulasan kinerja Anda akan menjadi bencana.",
  ui_story_5040_50400502_69_dialog_content = "Halo! Tolong tandatangani surat ini, dan semoga harimu menyenangkan!",
  ui_story_5040_50400502_70_dialog_content = "Bagus. Itu menangani pengiriman untuk lantai ini.",
  ui_story_5040_50400502_71_dialog_content = "Kiya...luar biasa...",
  ui_story_5040_50400502_72_dialog_content = "Tidak terlalu! Lagipula aku seorang kurir!",
  ui_story_5040_50400502_73_dialog_content = "Ingatlah untuk memberi tahu saya jika Anda melihat sesuatu yang membangkitkan ingatan Anda, oke?",
  ui_story_5040_50400502_74_dialog_content = "<color=#e8d9bb>Beberapa jam kemudian-</color>",
  ui_story_5040_50400502_75_dialog_content = "Aku... aku di batasku...",
  ui_story_5040_50400502_76_dialog_content = "*Terengah-engah* PlayerName... Apakah Anda selesai dengan pengiriman Anda?",
  ui_story_5040_50400502_77_dialog_content = "Ya... Akhirnya...",
  ui_story_5040_50400502_78_dialog_content = "Aku tahu kita harus menempuh banyak hal, tapi kalian benar-benar memiliki stamina yang lemah.",
  ui_story_5040_50400502_79_dialog_content = "Kerja bagus, semuanya! Sepertinya pekerjaan kita di sini sudah selesai.",
  ui_story_5040_50400502_80_dialog_content = "Kya belum kembali?",
  ui_story_5040_50400502_81_dialog_content = "Oh, jangan khawatir tentang dia. Dia menyelesaikan pengirimannya beberapa waktu lalu. Birdie Northland adalah yang paling efisien.",
  ui_story_5040_50400502_82_dialog_content = "Dia pasti sedang menunjukkan pemandangan di Kota Gannon kepada teman kecilnya sekarang.",
  ui_story_5040_50400502_83_dialog_content = "Ha ha! Aku tahu kau memilikinya di dalam dirimu, PlayerName!",
  ui_story_5040_50400502_84_dialog_content = "D-Merpati? Apakah Anda telah nongkrong di sini selama ini ?!",
  ui_story_5040_50400502_85_dialog_content = "\"Nongkrong\"? Saya bekerja sangat keras sekarang.",
  ui_story_5040_50400502_86_dialog_content = "Bisakah kita memiliki stempel sekarang setelah kita menyelesaikan pekerjaan?",
  ui_story_5040_50400502_87_dialog_content = "Tentu, ayolah. Lihatlah Segel Bulu!",
  ui_story_5040_50400502_88_dialog_content = "Ta-ra!",
  ui_story_5040_50400502_89_dialog_content = "Hah... Sekarang kita punya stempel Illumina juga!",
  ui_story_5040_50400502_90_dialog_content = "Aku masih tidak mengerti maksud dari semua ini...",
  ui_story_5040_50400502_91_dialog_content = "J-Jangan katakan itu! Petualangan kecil kita telah membuat kita semakin dekat, bukan begitu?",
  ui_story_5040_50400502_92_dialog_content = "K-Kata siapa?!",
  ui_story_5040_50400502_93_dialog_content = "Sekarang kita memiliki Segel Bulu Illumina, kemana kita akan pergi selanjutnya?",
  ui_story_5040_50400502_94_dialog_content = "Kami tidak datang ke Kota Gannon setiap hari. Mari kita mencoba beberapa makanan lokal, dan mungkin menonton film!",
  ui_story_5040_50400502_95_dialog_content = "Itu seharusnya membuat kita semua dalam semangat liburan!",
  ui_story_5040_50400502_96_dialog_content = "Kita bisa makan makanan Illumina kapanpun kita mau.",
  ui_story_5040_50400502_97_dialog_content = "Saat mengantarkan surat, saya mendengar bahwa kiriman senapan energi kinetik baru saja tiba dari Undercity. Saya ingin pergi melihat mereka menurunkan senjata itu.",
  ui_story_5040_50400502_98_dialog_content = "Anda ingin pergi melihat senjata di Mooncrown Day? Itu sangat tidak romantis...",
  ui_story_5040_50400502_99_dialog_content = "Jika Anda tidak ingin pergi, saya selalu bisa pergi sendiri.",
  ui_story_5040_50400502_100_dialog_content = "Aku…",
  ui_story_5040_50400502_101_dialog_content = "Tenanglah, kalian berdua. Masih ada hal yang sangat penting untuk diperhatikan.",
  ui_story_5040_50400502_102_dialog_content = "Atau apakah Anda berdua lupa alasan kami datang ke sini?",
  ui_story_5040_50400502_103_dialog_content = "Oh ya! Kita masih harus bertanya pada wanita di Laboratorium Payung Hitam itu tentang amnesia Tara!",
  ui_story_5040_50400502_104_dialog_content = "O-Oh, benar...",
  ui_story_5040_50400502_105_dialog_content = "...",
  ui_story_5040_50400502_106_dialog_content = "Ayo selesaikan itu sebelum gelap. Ayo.",
  ui_story_5040_50400601_1_dialog_content = "(Ini benar-benar sudah terlalu lama.)",
  ui_story_5040_50400601_2_dialog_content = "... Dan itulah mengapa kita di sini hari ini. Maaf untuk semua masalah.",
  ui_story_5040_50400601_3_dialog_content = "Tidak masalah sama sekali! Lagipula, aku berutang banyak pada Nona Tina, dan juga kalian semua!",
  ui_story_5040_50400601_4_dialog_content = "Lumopolis dan Illumina selalu memiliki perbedaan, yang membuat segalanya menjadi sangat sulit bagi kami berdua.",
  ui_story_5040_50400601_5_dialog_content = "Tapi kami diberkati memiliki orang-orang seperti Nona Tina yang mendukung kami!",
  ui_story_5040_50400601_6_dialog_content = "Meskipun menjadi anggota kelas bangsawan, dia selalu mendukung cinta kami.",
  ui_story_5040_50400601_7_dialog_content = "Dari apa yang saya pahami, tubuhnya membutuhkan banyak tidur agar bisa berfungsi dengan baik. Terlepas dari kondisinya, dia masih berusaha keras untuk menemukan stempel itu untuk kami.",
  ui_story_5040_50400601_8_dialog_content = "Yup, tidak dapat disangkal bahwa dia adalah orang yang luar biasa.",
  ui_story_5040_50400601_9_dialog_content = "Dia selalu begitu baik dan sopan.",
  ui_story_5040_50400601_10_dialog_content = "Tetapi saya tahu bahwa dia memiliki cukup banyak masalah untuk dihadapi. Saya mendengar bahwa pekerjaannya di Balai Kehakiman... menarik, untuk sedikitnya.",
  ui_story_5040_50400601_11_dialog_content = "Saya tidak tahu kapan kita akan memiliki kesempatan untuk bertemu lagi. Saya berharap saya tahu lebih banyak tentang dia.",
  ui_story_5040_50400601_12_dialog_content = "Tapi menurutnya, sepertinya kamu dan kekasihmu sudah cukup sulit apa adanya.",
  ui_story_5040_50400601_13_dialog_content = "Ya. Kenapa kalian berdua tidak kawin lari saja?",
  ui_story_5040_50400601_14_dialog_content = "Karena kita berdua memiliki hal-hal yang perlu kita lakukan. Kita mungkin kekasih, tetapi tanggung jawab kita sendiri akan selalu didahulukan.",
  ui_story_5040_50400601_15_dialog_content = "Dia dan saya sama-sama memiliki rasa tanggung jawab yang kuat, yang mungkin menjadi alasan mengapa kami tertarik satu sama lain.",
  ui_story_5040_50400601_16_dialog_content = "Jika dua orang benar-benar tulus dengan diri mereka sendiri dan satu sama lain, hal-hal seperti jarak menjadi sepele. Bagaimanapun, hati kita selalu bersama.",
  ui_story_5040_50400601_17_dialog_content = "Hatimu... selalu bersama?",
  ui_story_5040_50400601_18_dialog_content = "Saya juga merasakan hal yang sama. Tidak ada masalah yang terlalu sulit untuk diatasi, selama kalian saling mencintai!",
  ui_story_5040_50400601_19_dialog_content = "Ha ha ha! Sekarang, kita harus benar-benar kembali ke bisnis. Namamu Tara, kan? Saya pikir saya mengerti dilema Anda, kurang lebih.",
  ui_story_5040_50400601_20_dialog_content = "Sayangnya, saat ini saya hanya magang, tetapi izinkan saya bertanya kepada rekan-rekan saya dan lihat pendapat mereka. Tolong tunggu sebentar.",
  ui_story_5040_50400601_21_dialog_content = "Terima kasih lagi!",
  ui_story_5040_50400601_22_dialog_content = "<size=33>Jeriah... Menurutmu mereka tidak akan tahu kalau aku hanya berpura-pura, bukan?</size>",
  ui_story_5040_50400601_23_dialog_content = "Bukankah lebih baik berterus terang pada saat ini?",
  ui_story_5040_50400601_24_dialog_content = "<size=33>Mustahil! Saya tidak akan pernah bisa menunjukkan wajah saya kepada orang lain jika saya melakukannya!</size>",
  ui_story_5040_50400601_25_dialog_content = "Anda tidak memikirkan itu ketika Anda mendapatkan ide gila ini?",
  ui_story_5040_50400601_26_dialog_content = "<size=33>Ngomong-ngomong, jika rahasianya terbongkar, aku akan sangat membutuhkanmu untuk membantuku memadamkan api.</size>",
  ui_story_5040_50400601_27_dialog_content = "...",
  ui_story_5040_50400601_28_dialog_content = "(Aku tahu dia hanya berpura-pura selama ini... Kurasa aku akan berpura-pura tidak tahu apa-apa.)",
  ui_story_5040_50400601_29_dialog_content = "Apa yang kalian berdua bicarakan?",
  ui_story_5040_50400601_30_dialog_content = "Tidak ada apa-apa! Kami baru saja mengatakan betapa luar biasanya laboratorium ini!",
  ui_story_5040_50400601_31_dialog_content = "Yah, ya... Migard bertanggung jawab atas tempat ini, dan dia berada di level yang sama sekali berbeda.",
  ui_story_5040_50400601_32_dialog_content = "Tara? Mengapa kamu gemetar?",
  ui_story_5040_50400601_33_dialog_content = "Oh, dia hanya sedikit kedinginan!",
  ui_story_5040_50400601_34_dialog_content = "Benar-benar? Tidak terasa dingin sama sekali di sini...",
  ui_story_5040_50400601_35_dialog_content = "Maaf membuat anda menunggu! Jika semua orang mau mengikuti saya, saya ingin memperkenalkan Anda kepada salah satu peneliti senior di sini.",
  ui_story_5040_50400601_36_dialog_content = "Tunjukkan jalannya!",
  ui_story_5040_50400601_37_dialog_content = "Jola? Ini Tara, wanita muda yang saya sebutkan sebelumnya. Tampaknya dia saat ini menderita kasus amnesia.",
  ui_story_5040_50400601_38_dialog_content = "Kami sangat menghargai bantuan yang dapat Anda berikan kepada kami!",
  ui_story_5040_50400601_39_dialog_content = "Saya sangat senang untuk membantu! Hanya itu yang bisa saya lakukan, setelah semua yang telah Anda lakukan untuk rekan saya di sini.",
  ui_story_5040_50400601_40_dialog_content = "Nah, Nona Tara... Apakah Anda keberatan jika saya memeriksa Anda dari dekat?",
  ui_story_5040_50400601_41_dialog_content = "G-Majulah...",
  ui_story_5040_50400601_42_dialog_content = "Sayang sekali Migard tidak ada di sini hari ini. Saya bukan ahli dalam hal ini, tapi saya akan tetap mencoba yang terbaik.",
  ui_story_5040_50400601_43_dialog_content = "(Untunglah!)",
  ui_story_5040_50400601_44_dialog_content = "Hmm... Sekilas, tidak ada yang luar biasa. Kami harus menjalankan sejumlah tes untuk memastikan kondisi tubuh Anda.",
  ui_story_5040_50400601_45_dialog_content = "A-Tes macam apa...?",
  ui_story_5040_50400601_46_dialog_content = "(Senyumnya terlihat tidak menyenangkan...)",
  ui_story_5040_50400601_47_dialog_content = "Jangan khawatir! Sejumput kecil di sini, tarikan kecil di sana, dan itu akan berakhir sebelum Anda menyadarinya!",
  ui_story_5040_50400601_48_dialog_content = "Graaah!",
  ui_story_5040_50400601_49_dialog_content = "Oh, tidak...",
  ui_story_5040_50400602_1_dialog_content = "Hai! Anda tidak mengatakan apa-apa tentang menggunakan Eclipsites untuk menjalankan pengujian Anda!",
  ui_story_5040_50400602_2_dialog_content = "Sedikit peringatan pasti menyenangkan, lho!!",
  ui_story_5040_50400602_3_dialog_content = "Maafkan aku, semuanya. Sejujurnya saya tidak menyangka Anda akan sangat menentang metode saya!",
  ui_story_5040_50400602_4_dialog_content = "Lagi pula, kalian adalah kelompok yang cukup aneh. Seorang Northlander, seorang penghuni gurun, seorang kurir demi-human... dan, tentu saja, Caelestite terakhir di dunia.",
  ui_story_5040_50400602_5_dialog_content = "Itu tidak relevan sama sekali. Kami di sini hanya untuk membantu Tara menjadi lebih baik!",
  ui_story_5040_50400602_6_dialog_content = "Jadi apa sebenarnya yang salah dengan saya?",
  ui_story_5040_50400602_7_dialog_content = "Nah, dari apa yang saya lihat, Anda tampak sehat secara fisik.",
  ui_story_5040_50400602_8_dialog_content = "... Itu saja? Lalu, apa lagi yang bisa kita lakukan?",
  ui_story_5040_50400602_9_dialog_content = "Apa lagi yang bisa Anda ceritakan tentang penyakitnya? Tahukah Anda apa yang mungkin menyebabkannya?",
  ui_story_5040_50400602_10_dialog_content = "Coba saya lihat... Semuanya dimulai dengan ramuan ajaib itu. Paranormal yang menjualnya kepada saya mengatakan bahwa itu dibuat dengan menggunakan bahan yang sangat istimewa.",
  ui_story_5040_50400602_11_dialog_content = "Sesuatu tentang cacing pasir merah muda raksasa di Gurun Rediesel... Kurasa itu makhluk yang sangat langka?",
  ui_story_5040_50400602_12_dialog_content = "Apakah Anda mengatakan ... cacing pasir merah muda?",
  ui_story_5040_50400602_13_dialog_content = "Y-Ya?",
  ui_story_5040_50400602_14_dialog_content = "Jola, apa yang kamu ketahui tentang itu?",
  ui_story_5040_50400602_15_dialog_content = "...",
  ui_story_5040_50400602_16_dialog_content = "Aku tidak percaya cacing pasir merah muda yang legendaris telah muncul lagi...",
  ui_story_5040_50400602_17_dialog_content = "<size=33>Apa?! Itu tidak mungkin!</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>Tara?</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>Saya mendapatkan skala cacing pasir merah muda sejak lama! Bagaimana beberapa paranormal mendapatkan satu juga ?!</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>Jika cacing pasir merah muda ini benar-benar ada, apakah sangat mengejutkan mengetahui bahwa orang lain memiliki salah satu sisiknya?</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>Itu karena sejauh yang saya tahu, hanya satu skala cacing pasir merah muda yang pernah tersedia di seluruh pasar! Jadi bagaimana mungkin tiba-tiba ada yang lain?</size>",
  ui_story_5040_50400602_22_dialog_content = "Keahlian saya terletak pada bidang botani. Suatu hari ketika saya sedang mencari spora tertentu, Migard menyebutkan cacing pasir merah muda kepada saya.",
  ui_story_5040_50400602_23_dialog_content = "Spora ini sebagian besar tidak diteliti selama bertahun-tahun, dan hanya disebutkan dalam buku. Alasannya karena hanya tumbuh pada sisik cacing pasir merah muda yang sangat langka.",
  ui_story_5040_50400602_24_dialog_content = "Migard menyebutkan bahwa ada laporan saksi mata tentang makhluk ini, namun sangat sedikit yang bisa membuktikan klaim mereka.",
  ui_story_5040_50400602_25_dialog_content = "Ini lebih agresif daripada cacing pasir biasa, sehingga sulit bagi siapa pun untuk mendekatinya. Sisiknya adalah bahan yang sangat langka dan berharga. Nyatanya, menurut saya hanya ada satu skala yang tersedia di seluruh pasar.",
  ui_story_5040_50400602_26_dialog_content = "Jika Anda membawakan saya salah satu timbangan ini, saya mungkin bisa mencoba membuat obatnya.",
  ui_story_5040_50400602_27_dialog_content = "Di luar itu, saya khawatir saya tidak punya solusi lain untuk ditawarkan kepada Anda.",
  ui_story_5040_50400602_28_dialog_content = "...",
  ui_story_5040_50400602_29_dialog_content = "...",
  ui_story_5040_50400602_30_dialog_content = "Maka tampaknya tujuan kami telah dibuat sangat jelas bagi kami.",
  ui_story_5040_50400602_31_dialog_content = "Yeriah?",
  ui_story_5040_50400602_32_dialog_content = "Mengingat tujuan kita berikutnya adalah Rediesel Wrench, dan saya adalah kepala Serikat Kurir di sana... maka saya hanya akan membuat salah satu cacing pasir merah muda itu bersisik pada uji coba Feather Seal.",
  ui_story_5040_50400602_33_dialog_content = "Hei, apa kamu serius?",
  ui_story_5040_50400602_34_dialog_content = "Kedengarannya hanya sedikit orang yang pernah melihat benda ini... Aku bahkan belum pernah mendengarnya meski tinggal di gurun sepanjang hidupku. Apakah kamu?",
  ui_story_5040_50400602_35_dialog_content = "Saya juga belum pernah mendengarnya.",
  ui_story_5040_50400602_36_dialog_content = "Lalu mengapa kamu menjadikan ini percobaan kami ?!",
  ui_story_5040_50400602_37_dialog_content = "Aku akan melakukannya! Jika ada kesempatan sekecil apapun untuk mengembalikan ingatan Tara, aku bersedia mencobanya.",
  ui_story_5040_50400602_38_dialog_content = "Hah?",
  ui_story_5040_50400602_39_dialog_content = "Adonis! Apakah Anda kehilangan pikiran Anda ?!",
  ui_story_5040_50400602_40_dialog_content = "Sejujurnya, saya tidak merasa percaya diri sama sekali... karena saya tahu saya lemah dan penakut—saya bahkan tidak bisa membunuh serangga di rumah saya sendiri, apalagi cacing pasir raksasa...",
  ui_story_5040_50400602_41_dialog_content = "Tapi Tara berakhir seperti ini karena aku, jadi aku harus melakukan sesuatu.",
  ui_story_5040_50400602_42_dialog_content = "Aku tahu bahwa sifat pemaluku itulah yang membuatnya sangat frustasi sejak awal... Itu sebabnya aku ingin berubah.",
  ui_story_5040_50400602_43_dialog_content = "Aku tidak bisa mundur apapun yang terjadi.",
  ui_story_5040_50400602_44_dialog_content = "Itu adalah pidato yang sangat mengharukan!",
  ui_story_5040_50400602_45_dialog_content = "Adonis! Aku... Sebenarnya, aku—",
  ui_story_5040_50400602_46_dialog_content = "Pidato yang cukup menyentuh, Adonis. Jadi Anda pikir Anda bisa mengalahkan cacing pasir ini sendirian sekarang?",
  ui_story_5040_50400602_47_dialog_content = "Tentu saja tidak! Saya membutuhkan semua bantuan yang bisa saya dapatkan, jadi tolong ajari saya cara bertarung!",
  ui_story_5040_50400602_48_dialog_content = "Mulailah saya dengan Eclipsites jika Anda harus! Aku akan melakukan apapun untuk menjadi lebih kuat!",
  ui_story_5040_50400602_49_dialog_content = "Apakah Anda bahkan tahu cara bertarung?",
  ui_story_5040_50400602_50_dialog_content = "Aku ingat ayahmu mengatakan bahwa kamu pernah belajar Luminatics di bawah Novio... Benarkah?",
  ui_story_5040_50400602_51_dialog_content = "Ya! Sebagai anak laki-laki, saya sering pergi ke perpustakaan, dan Pak Novio akan mengajari saya banyak hal.",
  ui_story_5040_50400602_52_dialog_content = "Luminatics saya mungkin tidak terlalu kuat, tetapi saya memiliki pemahaman yang cukup kuat tentang cara menggunakannya.",
  ui_story_5040_50400602_53_dialog_content = "Hehehe... Bagus!",
  ui_story_5040_50400602_54_dialog_content = "Jeriah, ekspresimu membuatku takut.",
  ui_story_5040_50400602_55_dialog_content = "Tenang, kita semua berada di tim yang sama! Bukannya aku akan menyiksanya atau semacamnya.",
  ui_story_5040_50400602_56_dialog_content = "Ini akan mudah. Seperti yang Anda katakan sendiri, kita bisa mulai dengan Eclipsites...",
  ui_story_5040_50400602_57_dialog_content = "T-Tunggu... Kau benar-benar akan membuatku melawan salah satu dari hal itu?",
  ui_story_5040_50400602_58_dialog_content = "Ya Tuhan, tidak! Itu akan terlalu kejam! Tidak... Aku punya ide yang lebih baik.",
  ui_story_5040_50400602_59_dialog_content = "Dia lawan yang jauh lebih cocok untukmu.",
  ui_story_5040_50400701_1_dialog_content = "Apa yang Anda panggil saya di sini, Lady Jeriah?",
  ui_story_5040_50400701_2_dialog_content = "Yeriah, kamu tidak bermaksud...",
  ui_story_5040_50400701_3_dialog_content = "Graah...?",
  ui_story_5040_50400701_4_dialog_content = "Hehe, ya! Teman kecil Kya adalah pasangan yang cocok untuknya, bukan begitu? Segala sesuatu tentang dirinya secara praktis meneriakkan \"Eclipsite.\"",
  ui_story_5040_50400701_5_dialog_content = "Saya pikir dia akan menjadi rekan tanding yang luar biasa untuk Adonis!",
  ui_story_5040_50400701_6_dialog_content = "Maksudku, aku tahu Sable tidak terlalu mirip dengan Aurorian lainnya... tapi tidakkah menurutmu menyebutnya Eclipsite terlalu berlebihan?",
  ui_story_5040_50400701_7_dialog_content = "(Tetap saja, entah bagaimana dia pasti terhubung ke Eclipsites.)",
  ui_story_5040_50400701_8_dialog_content = "(Dia bersama Kya, dan sejauh ini tidak menimbulkan masalah. Kita hanya harus menunggu dan melihat, kurasa.)",
  ui_story_5040_50400701_9_dialog_content = "Rekan latihan...?",
  ui_story_5040_50400701_10_dialog_content = "Dia tidak tahu cara bertarung! Bagaimana jika dia terluka?",
  ui_story_5040_50400701_11_dialog_content = "Tenang, mereka tidak akan benar-benar berkelahi. Ini hanya untuk membantu Adonis menemukan keberaniannya, itu saja.",
  ui_story_5040_50400701_12_dialog_content = "Adonis, bagaimana menurutmu?",
  ui_story_5040_50400701_13_dialog_content = "I-Kelihatannya agak kasar... tapi jika Sable bersedia membantu, aku akan sangat berterima kasih.",
  ui_story_5040_50400701_14_dialog_content = "Jika saya harus berhadapan langsung dengan Eclipsite sekarang, saya praktis akan melayani diri saya sendiri di atas piring perak.",
  ui_story_5040_50400701_15_dialog_content = "Saya juga tidak pandai menggunakan Luminatics, karena saya jarang menggunakannya. Biasanya, saya hanya mengandalkan Tara untuk melindungi saya.",
  ui_story_5040_50400701_16_dialog_content = "Anda tidak harus melakukan ini, Adonis. Setiap orang memiliki kekuatan dan kelemahan yang berbeda.",
  ui_story_5040_50400701_17_dialog_content = "Dan aku bahkan tidak berpikir untuk melindungimu sebagai beban.",
  ui_story_5040_50400701_18_dialog_content = "Tara?",
  ui_story_5040_50400701_19_dialog_content = "Tidak... tidak peduli apapun, aku harus melakukan ini! Saya harus mendorong diri saya keluar dari zona nyaman saya.",
  ui_story_5040_50400701_20_dialog_content = "Kya, Sable, tolong bantu aku!",
  ui_story_5040_50400701_21_dialog_content = "Hm... Sable, apakah kamu baik-baik saja dengan ini?",
  ui_story_5040_50400701_22_dialog_content = "Jika itu berarti ... saya dapat membantu ...",
  ui_story_5040_50400701_23_dialog_content = "Lalu... Aku akan melakukannya!",
  ui_story_5040_50400701_24_dialog_content = "Jangan memaksakan diri, oke? Ini hanya pertarungan pura-pura, tidak lebih.",
  ui_story_5040_50400701_25_dialog_content = "saya tidak akan...",
  ui_story_5040_50400701_26_dialog_content = "saya... senang bisa membantu...",
  ui_story_5040_50400701_27_dialog_content = "Kamu yang terbaik, Sabel!",
  ui_story_5040_50400701_28_dialog_content = "Graah! Graaah!!",
  ui_story_5040_50400701_29_dialog_content = "Apakah hanya saya, atau apakah saya mendengar Eclipsite yang sebenarnya...?",
  ui_story_5040_50400701_30_dialog_content = "Hah?!",
  ui_story_5040_50400701_31_dialog_content = "<size=45>Graaahh—!</size>",
  ui_story_5040_50400701_32_dialog_content = "Hati-Hati! Ada Eclipsites di sini!",
  ui_story_5040_50400701_33_dialog_content = "T-Tapi bagaimana?! Dari mana mereka berasal?!",
  ui_story_5040_50400701_34_dialog_content = "Memangnya di mana? Anda dan burung hitam kecil Anda sepertinya selalu menarik banyak orang ke mana pun Anda pergi...",
  ui_story_5040_50400701_35_dialog_content = "Mungkinkah itu hanya kebetulan?",
  ui_story_5040_50400701_36_dialog_content = "Hmm.",
  ui_story_5040_50400701_37_dialog_content = "(Apakah Sable benar-benar menggambar monster-monster ini di sini...?)",
  ui_story_5040_50400701_38_dialog_content = "Eclip...situs...?",
  ui_story_5040_50400701_39_dialog_content = "Fokus. Mari singkirkan hama ini terlebih dahulu dan terutama.",
  ui_story_5040_50400701_40_dialog_content = "Dapatkan di belakangku, Adonis!",
  ui_story_5040_50400701_41_dialog_content = "Aku tahu.",
  ui_story_5040_50400702_1_dialog_content = "Sepertinya kita mendapatkan semuanya. Apakah semua orang baik-baik saja?",
  ui_story_5040_50400702_2_dialog_content = "Tentu saja. Lagipula itu hanya beberapa Eclipsites.",
  ui_story_5040_50400702_3_dialog_content = "A-aku juga baik-baik saja.",
  ui_story_5040_50400702_4_dialog_content = "Itu bagus untuk kalian, tapi sepertinya cerita yang berbeda untuk mereka berdua di sana.",
  ui_story_5040_50400702_5_dialog_content = "Ah!",
  ui_story_5040_50400702_6_dialog_content = "S... Sangat menakutkan...",
  ui_story_5040_50400702_7_dialog_content = "(Aku ingin tahu betapa produktifnya membuat keduanya melatih satu sama lain...)",
  ui_story_5040_50400702_8_dialog_content = "Haruskah kita melanjutkan pelatihan kita, atau apakah kalian berdua perlu istirahat?",
  ui_story_5040_50400702_9_dialog_content = "Aku bisa terus!",
  ui_story_5040_50400702_10_dialog_content = "M... Aku juga...!",
  ui_story_5040_50400702_11_dialog_content = "Jangan memaksakan diri, Sable.",
  ui_story_5040_50400702_12_dialog_content = "Karena kalian berdua merasa berani, mari kita lanjutkan.",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>15 menit kemudian—</color>",
  ui_story_5040_50400702_14_dialog_content = "...",
  ui_story_5040_50400702_15_dialog_content = "...",
  ui_story_5040_50400702_16_dialog_content = "Uh... apakah kalian akan memulainya dalam waktu dekat? Anda telah berdiri di sekitar untuk sementara waktu sekarang ...",
  ui_story_5040_50400702_17_dialog_content = "A-aku akan menyerang sekarang!",
  ui_story_5040_50400702_18_dialog_content = "…!!",
  ui_story_5040_50400702_19_dialog_content = "Anda tidak terlihat seperti akan pergi berperang sama sekali.",
  ui_story_5040_50400702_20_dialog_content = "Aku benar-benar akan melakukannya! Anda lebih baik bersiap-siap!",
  ui_story_5040_50400702_21_dialog_content = "O-Oke...!",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>Satu jam kemudian...</color>",
  ui_story_5040_50400702_23_dialog_content = "Kali ini, aku bersumpah akan menyerang!",
  ui_story_5040_50400702_24_dialog_content = "Hanya melihat!",
  ui_story_5040_50400702_25_dialog_content = "(Saya sangat mengantuk, saya merasa seperti saya bisa tidur siang sekarang.)",
  ui_story_5040_50400702_26_dialog_content = "Seperti yang saya katakan, Adonis, Anda benar-benar tidak perlu melakukan ini.",
  ui_story_5040_50400702_27_dialog_content = "Pergi Sabel!!!",
  ui_story_5040_50400702_28_dialog_content = "...",
  ui_story_5040_50400702_29_dialog_content = "Apakah Anda benar-benar berpikir bahwa Eclipsite akan berdiri selama satu jam dan menunggu Anda menyerang?",
  ui_story_5040_50400702_30_dialog_content = "Ingat, kau melakukan ini demi Tara.",
  ui_story_5040_50400702_31_dialog_content = "Jika dia kalah dalam pertempuran dan Eclipsite melihatnya, apakah Anda akan ragu seperti ini?",
  ui_story_5040_50400702_32_dialog_content = "Anda tidak perlu saya memberi tahu Anda apa hasilnya nanti.",
  ui_story_5040_50400702_33_dialog_content = "Aku… aku…",
  ui_story_5040_50400702_34_dialog_content = "Atau apakah Anda memberi tahu saya bahwa Anda tidak peduli jika dia terluka, karena Anda tidak mau melewati keragu-raguan Anda yang didorong oleh kepengecutan?",
  ui_story_5040_50400702_35_dialog_content = "I-Itu tidak benar sama sekali!",
  ui_story_5040_50400702_36_dialog_content = "Bahkan keraguan sesaat pun bisa berarti perbedaan antara hidup dan mati. Siapa yang mau bersama seseorang yang begitu tidak bisa diandalkan?",
  ui_story_5040_50400702_37_dialog_content = "<size=33>Hai! Kau terlalu keras padanya!</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>Aku merasa sangat kasihan padanya... Sable, kenapa kamu tidak membantunya?</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>Grah! Graaaaah!</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>Aaaaahhhh!!!</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>Bodoh...!</color>",
  ui_story_5040_50400702_42_dialog_content = "Haaa... Haaa...",
  ui_story_5040_50400702_43_dialog_content = "Aduh...",
  ui_story_5040_50400702_44_dialog_content = "S-Sabel! Apakah kamu baik-baik saja?!",
  ui_story_5040_50400702_45_dialog_content = "aku... aku baik-baik saja...",
  ui_story_5040_50400702_46_dialog_content = "Dia benar-benar menyerangnya?",
  ui_story_5040_50400702_47_dialog_content = "Anda membuat kemajuan, Adonis! Setidaknya kamu tidak meringkuk di belakang kali ini!",
  ui_story_5040_50400702_48_dialog_content = "Itu pasti serangan paling tidak berbahaya yang pernah saya lihat dalam hidup saya, tetapi Caelestite benar.",
  ui_story_5040_50400702_49_dialog_content = "Tetap saja, Anda tidak akan mendapatkan hit di Eclipsite nyata dalam waktu dekat.",
  ui_story_5040_50400702_50_dialog_content = "Yang paling penting adalah dia membuat kemajuan! Mengatasi diri sendiri selalu merupakan langkah tersulit!",
  ui_story_5040_50400702_51_dialog_content = "Terima kasih!",
  ui_story_5040_50400702_52_dialog_content = "*Sniff* Terima kasih banyak, semuanya! Terutama kamu, Sable!",
  ui_story_5040_50400702_53_dialog_content = "Tidak masalah...",
  ui_story_5040_50400702_54_dialog_content = "Bagus. Sekarang setelah kita menyingkir, pelatihan yang sebenarnya bisa dimulai.",
  ui_story_5040_50400702_55_dialog_content = "Saya pikir itu cukup untuk hari ini, Jeriah. Sudah sangat larut, dan saya yakin semua orang lelah.",
  ui_story_5040_50400702_56_dialog_content = "Kita dapat mengambilnya selangkah demi selangkah. Mari kita kembali ke kota untuk saat ini.",
  ui_story_5040_50400702_57_dialog_content = "Jika Anda berkata demikian, Caelestite kecil.",
  ui_story_5040_50400702_58_dialog_content = "Argh…",
  ui_story_5040_50400702_59_dialog_content = "Hah? Ada apa, Sabel? Apakah kamu terluka?",
  ui_story_5040_50400702_60_dialog_content = "N... Tidak...",
  ui_story_5040_50400702_61_dialog_content = "Aku ingat...",
  ui_story_5040_50400702_62_dialog_content = "Hah?!",
  ui_story_5040_50400702_63_dialog_content = "Gurun... Gurun...",
  ui_story_5040_50400702_64_dialog_content = "Seperti di Gurun Rediesel?",
  ui_story_5040_50400702_65_dialog_content = "Tidak tahu... Tapi...",
  ui_story_5040_50400702_66_dialog_content = "Aku hanya ingat... padang pasir...",
  ui_story_5040_50400702_67_dialog_content = "Kurasa Adonis membenturkan kepalamu membuat ingatanmu teralihkan?",
  ui_story_5040_50400702_68_dialog_content = "Nah, Gurun Rediesel adalah perhentian kami selanjutnya.",
  ui_story_5040_50400702_69_dialog_content = "...",
  ui_story_5040_50400702_70_dialog_content = "Kalian semua terlihat cantik, jadi mari kita berhenti dan beristirahat.",
  ui_story_5040_50400702_71_dialog_content = "Semua karena aku. Saya tidak tahu bagaimana harus berterima kasih kepada kalian semua.",
  ui_story_5040_50400702_72_dialog_content = "Ini adalah masalah kami sejak awal, tetapi Anda telah mendukung kami selama ini... Terima kasih.",
  ui_story_5040_50400702_73_dialog_content = "Mengapa kita tidak membeli makanan ringan khusus Illuminan untuk semua orang untuk menunjukkan penghargaan kita, Tara? Tidak banyak lagi yang bisa kita lakukan.",
  ui_story_5040_50400702_74_dialog_content = "Haha, kalian benar-benar tidak perlu melakukan itu!",
  ui_story_5040_50400702_75_dialog_content = "(Saya tidak yakin makanan khas Illumina cocok sebagai makanan ringan...)",
  ui_story_5040_50400702_76_dialog_content = "Itu ide yang bagus. Ayo berangkat sebelum terlambat.",
  ui_story_5040_50400702_77_dialog_content = "Saya ingin pergi...",
  ui_story_5040_50400702_78_dialog_content = "Kya, aku ingin berbicara denganmu secara pribadi. Apakah Anda punya waktu sebentar?",
  ui_story_5040_50400702_79_dialog_content = "Hah? Kenapa tiba-tiba... ya, Lady Jeriah.",
  ui_story_5040_50400702_80_dialog_content = "Tapi bagaimana dengan Sable...?",
  ui_story_5040_50400702_81_dialog_content = "Jangan khawatir tentang dia. Dia bisa kembali dengan PlayerName.",
  ui_story_5040_50400702_82_dialog_content = "Kecuali ada sesuatu tentang dia yang harus kita ketahui...?",
  ui_story_5040_50400702_83_dialog_content = "N...Tidak sama sekali!",
  ui_story_5040_50400702_84_dialog_content = "Maukah Anda membawanya kembali, PlayerName?",
  ui_story_5040_50400702_85_dialog_content = "Tentu saja tidak! Ayo, Sabel.",
  ui_story_5040_50400702_86_dialog_content = "Um…",
  ui_story_5040_50400702_87_dialog_content = "Ada apa?",
  ui_story_5040_50400702_88_dialog_content = "Aku... harus pergi ke suatu tempat...",
  ui_story_5040_50400702_89_dialog_content = "\"Pergi ke suatu tempat\"?",
  ui_story_5040_50400702_90_dialog_content = "Apakah masih ada tempat yang ingin kamu tuju?",
  ui_story_5040_50400702_91_dialog_content = "Tadi... aku mengambil... sepucuk surat...",
  ui_story_5040_50400702_92_dialog_content = "Saya ingin... mengembalikannya...",
  ui_story_5040_50400702_93_dialog_content = "Kapan Anda menemukan surat? Bukankah seharusnya kita mengantarkannya ke Courier Union?",
  ui_story_5040_50400702_94_dialog_content = "Itu ... setelah ... pelatihan kami ...",
  ui_story_5040_50400702_95_dialog_content = "Oh, jadi di suatu tempat di luar kota? Seorang kurir pasti menjatuhkannya secara tidak sengaja.",
  ui_story_5040_50400702_96_dialog_content = "Kita bisa membawanya ke Courier Union, oke?",
  ui_story_5040_50400702_97_dialog_content = "Ini memiliki ... alamat.",
  ui_story_5040_50400702_98_dialog_content = "Mereka pasti... menunggu... lama sekali...",
  ui_story_5040_50400702_99_dialog_content = "BENAR. Bagaimanapun, ini adalah Hari Mahkota Bulan. Anda ingin mengirimkannya ke penerima lebih cepat, ya?",
  ui_story_5040_50400702_100_dialog_content = "Andai saja Dove setengah bertanggung jawab sepertimu...",
  ui_story_5040_50400702_101_dialog_content = "Sini, biar saya lihat alamatnya. Saya akan membantu Anda mengirimkannya.",
  ui_story_5040_50400702_102_dialog_content = "(Amplop ini terlihat cukup tua... Ada yang mengatakan bahwa amplop ini belum dikirim baru-baru ini.)",
  ui_story_5040_50400702_103_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_5040_50400702_104_dialog_content = "Seharusnya... di sini.",
  ui_story_5040_50400702_105_dialog_content = "Ya, alamatnya benar.",
  ui_story_5040_50400702_106_dialog_content = "Halo? Dapatkah saya membantu Anda?",
  ui_story_5040_50400702_107_dialog_content = "Maaf mengganggu Anda, tapi kami menemukan surat ini di tanah tadi. Ini ditujukan ke rumah ini.",
  ui_story_5040_50400702_108_dialog_content = "Apakah begitu? Bolehkah saya melihat-lihat?",
  ui_story_5040_50400702_109_dialog_content = "...I-Ini tidak mungkin...!",
  ui_story_5040_50400702_110_dialog_content = "Ini alamat yang benar, kan?",
  ui_story_5040_50400702_111_dialog_content = "Di mana tepatnya kalian berdua menemukan surat ini?!",
  ui_story_5040_50400702_112_dialog_content = "Teman saya di sini menemukannya di luar kota. Dia bersikeras mengirimkannya kepada Anda.",
  ui_story_5040_50400702_113_dialog_content = "Apakah saya... membantu...?",
  ui_story_5040_50400702_114_dialog_content = "Aku tidak tahu harus berkata apa...",
  ui_story_5040_50400702_115_dialog_content = "Ini adalah surat untuk nenekku.",
  ui_story_5040_50400702_116_dialog_content = "Nenekmu?",
  ui_story_5040_50400702_117_dialog_content = "Dia menunggu surat ini untuk waktu yang lama, sampai saat dia meninggal.",
  ui_story_5040_50400702_118_dialog_content = "Itu dari cinta pertamanya. Dari apa yang dia katakan padaku, dia tinggal di Lumopolis. Tapi karena jarak antara disana dan Illumina, mereka tidak pernah berakhir bersama.",
  ui_story_5040_50400702_119_dialog_content = "Kakek saya sudah lama meninggal, jadi nenek saya terhubung kembali dengan cinta pertamanya.",
  ui_story_5040_50400702_120_dialog_content = "Mereka menjadi teman dekat, dan akan selalu mengirim surat satu sama lain. Mereka berjanji akan terus mengirim mereka sampai akhir.",
  ui_story_5040_50400702_121_dialog_content = "Tetapi suatu hari, surat-suratnya berhenti datang, dan tidak lama kemudian, nenek saya jatuh sakit dan meninggal dunia.",
  ui_story_5040_50400702_122_dialog_content = "Saya tidak pernah berpikir bahwa dia ...",
  ui_story_5040_50400702_123_dialog_content = "Huh, takdir benar-benar membodohi makhluk fana.",
  ui_story_5040_50400702_124_dialog_content = "Tidak kusangka ada cerita seperti itu di balik surat ini...",
  ui_story_5040_50400702_125_dialog_content = "Sable, kamu benar-benar melakukan sesuatu yang luar biasa!",
  ui_story_5040_50400702_126_dialog_content = "Saya sangat berterima kasih! Saya tidak akan membuka surat ini. Itu dimaksudkan untuk nenek saya, jadi saya akan meninggalkannya di kuburannya agar bisa menemaninya.",
  ui_story_5040_50400702_127_dialog_content = "...",
  ui_story_5040_50400702_128_dialog_content = "Ini pasti keajaiban Mooncrown Day... Aku hanya berharap kata-katanya masih bisa sampai padanya.",
  ui_story_5040_50400702_129_dialog_content = "Apakah ini cinta?",
  ui_story_5040_50400702_130_dialog_content = "Itu pertanyaan yang bagus. Kadang-kadang bahkan saya tidak mengerti diri saya sendiri. Bagaimana cinta begitu kuat?",
  ui_story_5040_50400702_131_dialog_content = "Terkadang itu menyakiti orang, terkadang menyelamatkan orang.",
  ui_story_5040_50400702_132_dialog_content = "Bagaimanapun, bagaimana saya bisa membalas kebaikan Anda berdua?",
  ui_story_5040_50400702_133_dialog_content = "Anda tidak perlu berterima kasih sama sekali. Terima Sable di sini sebagai gantinya.",
  ui_story_5040_50400702_134_dialog_content = "Tidak apa-apa...",
  ui_story_5040_50400702_135_dialog_content = "Sepertinya kita semua selesai di sini. Siap untuk kembali sekarang?",
  ui_story_5040_50400702_136_dialog_content = "Ya...",
  ui_story_5040_50400702_137_dialog_content = "<color=#e8d9bb>Sementara itu, di sisi lain kota...</color>",
  ui_story_5040_50400702_138_dialog_content = "Apa yang perlu Anda diskusikan dengan saya, Nona Jeriah?",
  ui_story_5040_50400702_139_dialog_content = "...",
  ui_story_5040_50400702_140_dialog_content = "Birdie Northland, hibur rasa penasaranku sejenak. Di mana Anda mendapatkan kerabat Anda ini?",
  ui_story_5040_50400702_141_dialog_content = "!!",
  ui_story_5040_50400702_142_dialog_content = "K-Maksudmu... S-Sable?",
  ui_story_5040_50400702_143_dialog_content = "Siapa lagi yang akan saya bicarakan?",
  ui_story_5040_50400702_144_dialog_content = "Um…",
  ui_story_5040_50400702_145_dialog_content = "(Suasananya terasa begitu menyesakkan!)",
  ui_story_5040_50400702_146_dialog_content = "Saya belum pernah bertele-tele, jadi saya akan bertanya langsung kepada Anda.",
  ui_story_5040_50400702_147_dialog_content = "Dia bukan Aurorian, kan?",
  ui_story_5040_50400702_148_dialog_content = "…!",
  ui_story_5040_50400702_149_dialog_content = "Biarkan saya menjadi lebih langsung: Dia tampaknya menjadi Eclipsite yang mampu berbicara Universese.",
  ui_story_5040_50400702_150_dialog_content = "Nona Jeriah...",
  ui_story_5040_50400702_151_dialog_content = "Heehee! Meskipun kamu sudah lama tidak menjadi kurir, harus kuakui aku cukup terkejut dengan keberanianmu, si kecil.",
  ui_story_5040_50400702_152_dialog_content = "Sepertinya aku meremehkanmu.",
  ui_story_5040_50400702_153_dialog_content = "Aku tahu itu benar-benar tidak pantas untuk kutanyakan, tapi... bisakah kau merahasiakan ini?",
  ui_story_5040_50400702_154_dialog_content = "Dan mengapa saya harus melakukan itu? Alasan apa yang saya miliki untuk membantu Anda mempertahankan fasad kecil Anda?",
  ui_story_5040_50400702_155_dialog_content = "Tidak ada, tidak ada alasan bagimu untuk membantuku. Saya juga tidak berhak meminta bantuan ini.",
  ui_story_5040_50400702_156_dialog_content = "Aku memohon padamu, itu saja.",
  ui_story_5040_50400702_157_dialog_content = "...",
  ui_story_5040_50400702_158_dialog_content = "Dia kehilangan ingatannya dan meminta saya untuk membantunya.",
  ui_story_5040_50400702_159_dialog_content = "Membantunya tidak ada gunanya bagiku. Jika ada, itu menempatkan kita semua dalam bahaya. Aurorian dan Eclipsites selalu berselisih; kita semua tahu itu.",
  ui_story_5040_50400702_160_dialog_content = "Tapi alasan utama saya menjadi kurir adalah agar saya bisa membantu orang menyampaikan pikiran dan perasaan mereka satu sama lain. Itu dia. Dan aku ingin melakukan hal yang sama untuknya.",
  ui_story_5040_50400702_161_dialog_content = "Aku bilang aku akan membantunya bahkan tanpa memikirkannya. Itu sembrono bagiku untuk melakukannya, tapi aku tetap melakukannya.",
  ui_story_5040_50400702_162_dialog_content = "Karena itu saya siap menerima tanggung jawab penuh atas apapun yang terjadi akibat perbuatan saya. Apapun yang terjadi... Aku bersumpah akan membayar harganya.",
  ui_story_5040_50400702_163_dialog_content = "Jika saya mengatakan saya ingin menyakiti Sable, apakah Anda akan berdiri di depannya?",
  ui_story_5040_50400702_164_dialog_content = "Saya akan.",
  ui_story_5040_50400702_165_dialog_content = "Nah Kya, kamu selalu bersungguh-sungguh dan menyelesaikan apa yang kamu mulai. Demikian juga, saya akan menangani masalah ini dengan tepat.",
  ui_story_5040_50400702_166_dialog_content = "...",
  ui_story_5040_50400702_167_dialog_content = "Kamu jauh lebih menarik dari yang aku bayangkan. Sedikit naif, tapi aku tidak suka kesungguhan.",
  ui_story_5040_50400702_168_dialog_content = "Saya akan melakukan apa yang Anda minta sekarang. Semoga beruntung, Kya.",
  ui_story_5040_50400702_169_dialog_content = "Jadi apakah itu berarti... kau membantuku?",
  ui_story_5040_50400702_170_dialog_content = "Terima kasih! Terima kasih banyak, Nona Jeriah.",
  ui_story_5040_50400702_171_dialog_content = "Dan jangan khawatir! Apa pun yang terjadi, saya akan bertanggung jawab penuh sampai akhir.",
  ui_story_5040_50400801_1_dialog_content = "Sable, terima kasih, kami harus melakukan sesuatu yang sangat berarti di Gannon City. Ayo, mari kita kembali dan beristirahat sekarang.",
  ui_story_5040_50400801_2_dialog_content = "Baiklah…",
  ui_story_5040_50400801_3_dialog_content = "Apakah kamu baik-baik saja? kulit Anda terlihat sedikit off.",
  ui_story_5040_50400801_4_dialog_content = "Wajahku?",
  ui_story_5040_50400801_5_dialog_content = "Ya. Aku tidak bermaksud kasar, tapi kau terlihat lelah, itu saja.",
  ui_story_5040_50400801_6_dialog_content = "Apakah Anda mendapatkan cukup vitamin akhir-akhir ini? Atau mungkin Anda merasa sedikit di bawah cuaca?",
  ui_story_5040_50400801_7_dialog_content = "Aku... aku tidak... berpikir begitu...",
  ui_story_5040_50400801_8_dialog_content = "Graaah!",
  ui_story_5040_50400801_9_dialog_content = "Graaooh!!",
  ui_story_5040_50400801_10_dialog_content = "Apa? Lebih Banyak Eclipsite?!",
  ui_story_5040_50400801_11_dialog_content = "Ini adalah pertama kalinya saya melihat mereka di Kota Gannon!",
  ui_story_5040_50400801_12_dialog_content = "Aaaaaahhh! Seseorang selamatkan aku!!",
  ui_story_5040_50400801_13_dialog_content = "H... Pegang... aku!",
  ui_story_5040_50400801_14_dialog_content = "J-Jangan... takut...",
  ui_story_5040_50400801_15_dialog_content = "Warna hitam! Bawa anak itu dan kembali!",
  ui_story_5040_50400802_1_dialog_content = "Wah... Kalian berdua baik-baik saja?",
  ui_story_5040_50400802_2_dialog_content = "Y-Ya...",
  ui_story_5040_50400802_3_dialog_content = "Waaaah! K-Kau terlihat sangat menakutkan!",
  ui_story_5040_50400802_4_dialog_content = "Aku…",
  ui_story_5040_50400802_5_dialog_content = "Jangan khawatirkan dia, Sable. Anak malang itu mungkin masih shock.",
  ui_story_5040_50400802_6_dialog_content = "Tetap saja, apa yang dilakukan Eclipsites di tengah Kota Gannon?",
  ui_story_5040_50400802_7_dialog_content = "Fiuh! Kalian berdua sangat membantuku!",
  ui_story_5040_50400802_8_dialog_content = "J-Jola?",
  ui_story_5040_50400802_9_dialog_content = "Ini adalah salah satu Eclipsites yang digunakan Migard untuk pengujian. Untuk beberapa alasan, dia mengamuk dan menemukan jalan keluar dari laboratorium.",
  ui_story_5040_50400802_10_dialog_content = "Syukurlah tidak ada yang terluka... terima kasih untuk kalian berdua, tentu saja.",
  ui_story_5040_50400802_11_dialog_content = "Sebuah Eclipsite digunakan untuk pengujian? Maksudmu seperti yang dari awal hari ini?",
  ui_story_5040_50400802_12_dialog_content = "Dengan tepat. Migard menangkap semua jenis Eclipsites. Saya tidak tahu persis sifat eksperimennya...",
  ui_story_5040_50400802_13_dialog_content = "tapi sepertinya dia melewati Eclipsites yang ditangkap dengan cukup cepat.",
  ui_story_5040_50400802_14_dialog_content = "!!!",
  ui_story_5040_50400802_15_dialog_content = "Kalian harus lebih berhati-hati dengan subjek tes kalian! Bagaimana jika yang satu ini berhasil melukai seseorang?",
  ui_story_5040_50400802_16_dialog_content = "Nah, hal semacam ini belum pernah terjadi sebelumnya. Mungkin ada sesuatu pada kalian yang membuatnya keluar.",
  ui_story_5040_50400802_17_dialog_content = "Omong-omong, Sable, kami bisa meminta Migard untuk melihatmu. Dia memiliki semua jenis obat di labnya.",
  ui_story_5040_50400802_18_dialog_content = "Jika Anda sedang tidak enak badan, saya yakin dia akan dapat membantu!",
  ui_story_5040_50400802_19_dialog_content = "Tidak... Tidak, terima kasih!",
  ui_story_5040_50400802_20_dialog_content = "Aku... baru ingat... sesuatu yang penting!",
  ui_story_5040_50400802_21_dialog_content = "Aku harus... pergi... mencari Kya!",
  ui_story_5040_50400802_22_dialog_content = "Hah?!",
  ui_story_5040_50400802_23_dialog_content = "Heheheh... Cukup menarik temanmu disana.",
  ui_story_5040_50400802_24_dialog_content = "(Sudah larut ... Sable dan yang lainnya mungkin menungguku. Aku harus pergi.)",
  ui_story_5040_50400802_25_dialog_content = "K... Kya!!!",
  ui_story_5040_50400802_26_dialog_content = "Warna hitam? Apa yang kamu lakukan di sini? Bukankah seharusnya kamu bersama PlayerName sekarang?",
  ui_story_5040_50400802_27_dialog_content = "Aku ingin... bersamamu... Kya.",
  ui_story_5040_50400802_28_dialog_content = "Begitu... kalau begitu mari kita kembali bersama.",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb>Kruuk...</color>",
  ui_story_5040_50400802_30_dialog_content = "Apa itu tadi...?",
  ui_story_5040_50400802_31_dialog_content = "Oh itu? Maaf, itu hanya perut saya.",
  ui_story_5040_50400802_32_dialog_content = "Saya belum makan apapun sepanjang hari. Saya kelaparan!",
  ui_story_5040_50400802_33_dialog_content = "M... Aku juga...",
  ui_story_5040_50400802_34_dialog_content = "Kamu juga? Ayo, kita bisa menemukan tempat makan yang enak sebelum kita tidur malam.",
  ui_story_5040_50400802_35_dialog_content = "TIDAK! Aku... Aku melihat... Orang-orang... ketakutan...",
  ui_story_5040_50400802_36_dialog_content = "Warna hitam...?",
  ui_story_5040_50400802_37_dialog_content = "Jangan katakan itu. Anda mungkin tidak terlihat seperti kebanyakan orang Aurorian, tapi Anda baik hati.",
  ui_story_5040_50400802_38_dialog_content = "Kami hanya bisa membeli roti untuk pergi. Apakah itu terdengar bagus untukmu?",
  ui_story_5040_50400802_39_dialog_content = "Ya…",
  ui_story_5040_50400802_40_dialog_content = "Jadi, apakah Federasi Illumina mengingatkan Anda tentang hal lain, Sable?",
  ui_story_5040_50400802_41_dialog_content = "Tidak...",
  ui_story_5040_50400802_42_dialog_content = "Tidak apa-apa! Setidaknya kamu ingat gurun, kan? Saya yakin kita akan lebih beruntung begitu sampai di sana.",
  ui_story_5040_50400802_43_dialog_content = "Jangan khawatir.",
  ui_story_5040_50400802_44_dialog_content = "Terima kasih…",
  ui_story_5040_50400802_45_dialog_content = "Hmm, sepertinya aku melihat seorang pedagang menjual roti jeruk buatan sendiri di dekat stasiun. Tunggu di sini untuk saya.",
  ui_story_5040_50400802_46_dialog_content = "Aku akan segera kembali, jangan kemana-mana!",
  ui_story_5040_50400802_47_dialog_content = "…!",
  ui_story_5040_50400802_48_dialog_content = "Kedengarannya... tidak asing...",
  ui_story_5040_50400802_49_dialog_content = "Aku akan segera kembali, tunggu saja aku di sini!",
  ui_story_5040_50400802_50_dialog_content = "Jangan kemana-mana, saya akan kembali segera setelah saya membelinya.",
  ui_story_5040_50400802_51_dialog_content = "Edward, apa yang membuatmu berbicara begitu lama? Kenapa kamu belum kembali?",
  ui_story_5040_50400802_52_dialog_content = "Kenapa kamu tidak kembali?",
  ui_story_5040_50400802_53_dialog_content = "Apakah karena saya tidak cukup baik? Kenapa kenapa?!",
  ui_story_5040_50400802_54_dialog_content = "<size=45>Kembali!!!</size>",
  ui_story_5040_50400802_55_dialog_content = "Merasa putus asa? Seolah-olah tidak ada yang bisa diandalkan di dunia ini? Terima benih ini, dan Anda tidak akan pernah takut lagi.",
  ui_story_5040_50400802_56_dialog_content = "Bebaskan dirimu dari penderitaan yang lemah, karena kamu akan menjadi lebih kuat dari yang pernah kamu bayangkan!",
  ui_story_5040_50400802_57_dialog_content = "Aaaaaahhh!!!",
  ui_story_5040_50400802_58_dialog_content = "Lihat, Sabil! Ini Hari Mooncrown, jadi saya berhasil mendapatkan roti gulung kayu manis. Saya yakin Anda akan menyukainya.",
  ui_story_5040_50400802_59_dialog_content = "Warna hitam...?",
  ui_story_5040_50400802_60_dialog_content = "Aaaah! Lihat kak, Eclipsite!",
  ui_story_5040_50400802_61_dialog_content = "Ada Eclipsite di kota!",
  ui_story_5040_50400802_62_dialog_content = "Tunggu... kau yakin? Mungkin itu sesuatu yang lain...",
  ui_story_5040_50400802_63_dialog_content = "Haruskah kita memanggil Legiun?",
  ui_story_5040_50400802_64_dialog_content = "!!!",
  ui_story_5040_50400802_65_dialog_content = "Minggir!",
  ui_story_5040_50400802_66_dialog_content = "Warna hitam? Warna hitam! Apakah kamu baik-baik saja?!",
  ui_story_5040_50400802_67_dialog_content = "Ah...",
  ui_story_5040_50400802_68_dialog_content = "Ayo, Sabel! Kita harus keluar dari sini!",
  ui_story_5040_50400802_69_dialog_content = "Tunggu, kalian berdua! Namai dirimu!",
  ui_story_5040_50400802_70_dialog_content = "Terkesiap... Terkesiap...",
  ui_story_5040_50400802_71_dialog_content = "Diam!",
  ui_story_5040_50400802_72_dialog_content = "Aduh...",
  ui_story_5040_50400802_73_dialog_content = "Kita akan berada dalam masalah besar jika mereka menemukan kita!",
  ui_story_5040_50400802_74_dialog_content = "Apakah Anda kebetulan melihat Eclipsite yang tampak aneh di sekitar sini? Dia bersama seorang gadis.",
  ui_story_5040_50400802_75_dialog_content = "Ya ampun, kedengarannya merepotkan. Saya yakin mereka mencoba melarikan diri ke permukaan... Haruskah saya memanggil lebih banyak tentara?",
  ui_story_5040_50400802_76_dialog_content = "Apa? Bagaimana mereka sampai di sana begitu cepat?! Setelah mereka!",
  ui_story_5040_50400802_77_dialog_content = "Jeriah... Terima kasih.",
  ui_story_5040_50400802_78_dialog_content = "Sepertinya pantai sudah bersih. Apakah kamu terluka, Sable? Mari saya lihat!",
  ui_story_5040_50400802_79_dialog_content = "Saya baik-baik saja.",
  ui_story_5040_50400802_80_dialog_content = "Maaf karena... membuatmu khawatir...",
  ui_story_5040_50400802_81_dialog_content = "Apa yang kamu katakan? Saya tidak akan pernah bisa memaafkan diri sendiri jika Anda terluka saat saya pergi membeli makanan ringan.",
  ui_story_5040_50400802_82_dialog_content = "...Kya.",
  ui_story_5040_50400802_83_dialog_content = "Aku... Aku ingat sesuatu.",
  ui_story_5040_50400802_84_dialog_content = "Benar-benar? Apa yang kamu ingat?",
  ui_story_5040_50400802_85_dialog_content = "Seseorang... Seseorang yang... mengatakan hal yang sama... sepertimu.",
  ui_story_5040_50400802_86_dialog_content = "Tapi... dia tidak pernah... kembali.",
  ui_story_5040_50400802_87_dialog_content = "Aku pergi ke suatu tempat... suatu tempat yang jauh... untuk mencarinya.",
  ui_story_5040_50400802_88_dialog_content = "Dia mengatakan padaku... bahwa dia menyukaiku...",
  ui_story_5040_50400802_89_dialog_content = "Tapi... pada akhirnya... dia meninggalkanku.",
  ui_story_5040_50400802_90_dialog_content = "Aku lari... lari dari rumah... Aku takut...",
  ui_story_5040_50400802_91_dialog_content = "Tapi kemudian... seseorang memberiku... benih.",
  ui_story_5040_50400802_92_dialog_content = "Memberitahu saya ... untuk menjadi lebih kuat.",
  ui_story_5040_50400802_93_dialog_content = "Jadi, bagaimanapun juga, Anda adalah seorang Aurorian!",
  ui_story_5040_50400802_94_dialog_content = "Tapi bagaimana hal seperti ini bisa terjadi?!",
  ui_story_5040_50400802_95_dialog_content = "Ramuan itu... membangunkanku...",
  ui_story_5040_50400802_96_dialog_content = "Tapi aku... lupa segalanya... tidak percaya apapun...",
  ui_story_5040_50400802_97_dialog_content = "Aku hanya... ingin... pulang.",
  ui_story_5040_50400802_98_dialog_content = "Warna hitam...",
  ui_story_5040_50400802_99_dialog_content = "Jangan khawatir, Sabel. Aku berjanji akan membawamu kembali ke rumahmu.",
  ui_story_5040_50400802_100_dialog_content = "Kami akan berangkat ke Gurun Rediesel besok pagi. Itu bisa jadi di mana rumah Anda berada.",
  ui_story_5040_50400802_101_dialog_content = "Terima kasih... Kya.",
  ui_story_5040_50400802_102_dialog_content = "Pikiranku... akhir-akhir ini, aku... bisa merasakannya... menjauh lagi.",
  ui_story_5040_50400802_103_dialog_content = "Aku tidak tahu... berapa lama... aku bisa bertahan.",
  ui_story_5040_50400802_104_dialog_content = "Jika saya... kehilangannya... Anda harus...",
  ui_story_5040_50400802_105_dialog_content = "Jangan katakan apa-apa lagi! Saya akan memastikan Anda melihat rumah Anda sebelum itu terjadi. Kami bahkan mungkin menemukan cara untuk menjaga agar kesadaran Anda tidak memudar!",
  ui_story_5040_50400802_106_dialog_content = "Ingat cacing pasir merah muda? Saya yakin kami akan menemukan solusinya.",
  ui_story_5040_50400802_107_dialog_content = "Kya...",
  ui_story_5040_50400802_108_dialog_content = "Kami akan berangkat besok, tidak ada waktu untuk disia-siakan.",
  ui_story_5040_50400802_109_dialog_content = "Kau akan pulang, Sable.",
  ui_story_5040_50400901_1_dialog_content = "Ini dia. Buat diri Anda di rumah.",
  ui_story_5040_50400901_2_dialog_content = "Jadi ini divisi Rediesel Wrench dari Courier Union ya?",
  ui_story_5040_50400901_3_dialog_content = "Bagian luarnya mungkin sedikit bobrok, tapi di sini sangat indah! Sama sekali tidak seperti yang saya harapkan.",
  ui_story_5040_50400901_X3_dialog_content = "Betul, belum lagi lokasinya yang susah ditemukan!",
  ui_story_5040_50400901_X4_dialog_content = "Bangunan pangkalan Rediesel Wrench semuanya dibangun dengan sembarangan, bahkan sulit untuk menemukan jalannya...",
  ui_story_5040_50400901_X5_dialog_content = "Anda harus memutar dan berbelok melalui gang selama sepuluh menit bahkan sebelum mencapai tempat ini!",
  ui_story_5040_50400901_X6_dialog_content = "Butuh waktu lama untuk menemukannya ketika saya pertama kali datang ke sini.",
  ui_story_5040_50400901_X7_dialog_content = "Itu berarti Anda memiliki arah yang baik!",
  ui_story_5040_50400901_X8_dialog_content = "Ketika saya pertama kali datang ke sini, butuh waktu lama untuk menemukannya, saya hampir menyerah.",
  ui_story_5040_50400901_4_dialog_content = "Meskipun ini adalah kedua kalinya saya melihat dekorasi ini, mereka masih sangat mengejutkan.",
  ui_story_5040_50400901_5_dialog_content = "Bukan hanya dekorasinya saja. Ada begitu banyak ornamen bagus di dalamnya yang menyilaukan.",
  ui_story_5040_50400901_6_dialog_content = "Ini benar-benar tidak terlihat seperti gaya Rediesel Wrench!",
  ui_story_5040_50400901_7_dialog_content = "Orang brengsek vulgar macam apa yang Anda anggap sebagai saya?",
  ui_story_5040_50400901_8_dialog_content = "Bukan itu maksudku...",
  ui_story_5040_50400901_9_dialog_content = "Tidak apa-apa, aku menggoda.",
  ui_story_5040_50400901_10_dialog_content = "Jeriah, saya berharap untuk melihat-lihat dengan Sable...",
  ui_story_5040_50400901_11_dialog_content = "Tidak masalah. Pergi melihat-lihat di mana pun Anda suka.",
  ui_story_5040_50400901_12_dialog_content = "Sungguh?",
  ui_story_5040_50400901_13_dialog_content = "Ingatlah untuk mengembalikan semuanya ke tempat Anda menemukannya.",
  ui_story_5040_50400901_14_dialog_content = "Tentu saja!",
  ui_story_5040_50400901_15_dialog_content = "Ayo pergi, Sabel!",
  ui_story_5040_50400901_16_dialog_content = "Aku juga harus menyiapkan mobil dan senjata.",
  ui_story_5040_50400901_17_dialog_content = "Ini akan segera malam. Kalian harus beristirahat di sini malam ini.",
  ui_story_5040_50400901_18_dialog_content = "Mobil? Bukankah lebih cepat menggunakan Colossus?",
  ui_story_5040_50400901_X18_dialog_content = "Dan Colossus sangat besar. Ini terlihat jauh lebih aman daripada mobil.",
  ui_story_5040_50400901_19_dialog_content = "Cacing pasir tahu jalan mereka di atas dan di bawah tanah.",
  ui_story_5040_50400901_20_dialog_content = "Mereka setan kecil yang licik, mahir menavigasi gua bawah tanah.",
  ui_story_5040_50400901_21_dialog_content = "Jika Anda tidak mengambilnya pada detik pertama yang Anda bisa, mereka akan menghilang.",
  ui_story_5040_50400901_X21_dialog_content = "Apa?!",
  ui_story_5040_50400901_X22_dialog_content = "Yeriah benar.",
  ui_story_5040_50400901_22_dialog_content = "Colossus mungkin cepat, tetapi sebagai penumpang, tidak ada cara untuk melibatkan mereka saat pertama kali melihatnya.",
  ui_story_5040_50400901_X23_dialog_content = "Saya pernah mengalaminya secara langsung, percayalah.",
  ui_story_5040_50400901_23_dialog_content = "Oh, begitu…",
  ui_story_5040_50400901_24_dialog_content = "Anda memiliki lebih banyak untuk belajar tentang padang pasir.",
  ui_story_5040_50400901_25_dialog_content = "Aku harus pergi. Kami akan berangkat besok pagi untuk pergi berburu cacing pasir.",
  ui_story_5040_50400901_26_dialog_content = "<color=#e8d9bb>Gruduk!</color>",
  ui_story_5040_50400901_27_dialog_content = "Maaf!",
  ui_story_5040_50400901_28_dialog_content = "Kami sangat sibuk, aku benar-benar lupa makan.",
  ui_story_5040_50400901_29_dialog_content = "<color=#e8d9bb>*Aduh*</color>",
  ui_story_5040_50400901_30_dialog_content = "Aku juga cukup lapar.",
  ui_story_5040_50400901_31_dialog_content = "Nah, karena kita berada di gurun, izinkan saya untuk menyiapkan beberapa barang khas Rediesel Wrench untuk Anda!",
  ui_story_5040_50400901_32_dialog_content = "Biarkan saya menyalakan api di luar, dan kita akan mengadakan barbekyu!",
  ui_story_5040_50400901_33_dialog_content = "Biar kubantu!",
  ui_story_5040_50400901_34_dialog_content = "Dan kemudian ada satu.",
  ui_story_5040_50400901_35_dialog_content = "Aku mungkin tidak seharusnya memakai roda tiga Tara dan Adonis, tapi kurasa Kya dan Sable juga tidak butuh bantuan.",
  ui_story_5040_50400901_36_dialog_content = "Bagaimanapun, saya hanya ingin tahu apakah banyak dari kita bahkan bisa menangani cacing pasir sebesar yang dikabarkan.",
  ui_story_5040_50400901_37_dialog_content = "Jeriah tampaknya cukup kuat, dan Tara petarung yang bagus... tapi aku masih sedikit khawatir.",
  ui_story_5040_50400901_38_dialog_content = "Aku harus mencari Jeriah, melihat apakah menurutnya kita perlu bantuan.",
  ui_story_5040_50400901_39_dialog_content = "Apakah Anda datang mencari saya karena Anda khawatir, Caelestite kecil?",
  ui_story_5040_50400901_40_dialog_content = "T-Tolong jangan panggil aku seperti itu.",
  ui_story_5040_50400901_41_dialog_content = "Tidak perlu khawatir. Saya tahu gurun ini seperti punggung tangan saya.",
  ui_story_5040_50400901_42_dialog_content = "Saya sudah memeriksa mobil dan menyiapkan perbekalan. Jaga dirimu dan kamu akan baik-baik saja.",
  ui_story_5040_50400901_43_dialog_content = "Tapi cacing pasir adalah binatang yang tangguh. Saya khawatir kita tidak akan bisa menanganinya sendiri.",
  ui_story_5040_50400901_44_dialog_content = "Haruskah kita meminta bantuan orang lain? Bagaimana dengan Sinsa, Azure, dan lainnya?",
  ui_story_5040_50400901_45_dialog_content = "Tidak perlu.",
  ui_story_5040_50400901_46_dialog_content = "Namun…",
  ui_story_5040_50400901_47_dialog_content = "Saya tidak butuh bantuan siapa pun.",
  ui_story_5040_50400901_48_dialog_content = "Hanya aku sendiri yang akan melakukannya. Itu hanya cacing pasir, beberapa pukulan akan menjatuhkannya.",
  ui_story_5040_50400901_49_dialog_content = "Sekarang jika tidak ada lagi yang Anda butuhkan, Anda dapat kembali.",
  ui_story_5040_50400901_50_dialog_content = "Saya memiliki hal-hal lain yang harus dilakukan, dan tidak perlu diganggu oleh kekhawatiran anak-anak.",
  ui_story_5040_50400901_51_dialog_content = "...",
  ui_story_5040_50400901_52_dialog_content = "Oke.",
  ui_story_5040_50400901_S52_dialog_content = "Sebaiknya aku kembali ke Soroz.",
  ui_story_5040_50400901_53_dialog_content = "Wow... Aku benar-benar dikejar oleh Jeriah.",
  ui_story_5040_50400901_54_dialog_content = "Lupakan. Jika dia ingin saya mengurus urusan saya sendiri, itulah yang akan saya lakukan!",
  ui_story_5040_50400901_55_dialog_content = "...",
  ui_story_5040_50400901_X55_dialog_content = "(Selama ini, Jeriah selalu tampil sebagai seseorang yang terhibur saat melihat sesuatu turun.)",
  ui_story_5040_50400901_X56_dialog_content = "(Bahkan jika dia anggota senior Serikat Kurir, aku masih tidak bisa mempercayainya.)",
  ui_story_5040_50400901_X57_dialog_content = "(Saya hanya akan mengirim pesan terminal ke orang-orang Rediesel Wrench agar aman.)",
  ui_story_5040_50400901_X58_dialog_content = "(Mudah-mudahan ada orang terdekat dan akan merespon...)",
  ui_story_5040_50400901_56_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_5040_50400901_57_dialog_content = "Halo PlayerName, ini Odi. Apakah Anda menyalin?",
  ui_story_5040_50400901_58_dialog_content = "Odi!",
  ui_story_5040_50400901_59_dialog_content = "Menyalin! Ini bagus, saya sebenarnya tidak berharap ada yang membalas!",
  ui_story_5040_50400901_60_dialog_content = "Ada yang bisa kubantu?",
  ui_story_5040_50400901_61_dialog_content = "Apakah Anda tahu sesuatu tentang cacing pasir merah muda?",
  ui_story_5040_50400901_62_dialog_content = "Cacing pasir merah muda? Hmm, itu membunyikan bel.",
  ui_story_5040_50400901_63_dialog_content = "Saya pikir Sinsa bertemu dengan salah satunya sekitar sebulan yang lalu.",
  ui_story_5040_50400901_64_dialog_content = "Tidak ada yang pernah melihat cacing pasir seperti itu sebelumnya, jadi semua orang bergegas keluar untuk mencoba dan menangkapnya, tapi berhasil lolos.",
  ui_story_5040_50400901_65_dialog_content = "Saya tidak memiliki rincian yang tepat. Biarkan saya menyelesaikan bos, dan Anda bisa bertanya sendiri padanya.",
  ui_story_5040_50400901_66_dialog_content = "Tentu. Maaf atas kerumitannya!",
  ui_story_5040_50400901_67_dialog_content = "Yo, PlayerName! Ada apa?",
  ui_story_5040_50400901_68_dialog_content = "Odi bilang kamu bertanya tentang cacing pasir merah muda?",
  ui_story_5040_50400901_69_dialog_content = "Ya. Apa yang bisa kamu ceritakan padaku?",
  ui_story_5040_50400901_70_dialog_content = "Apa yang ingin anda ketahui? Hewan buas itu adalah salah satu dari sedikit cacing pasir yang bisa kabur dariku.",
  ui_story_5040_50400901_71_dialog_content = "Sekitar sebulan yang lalu, saya sangat ingin memburunya, tetapi pada akhirnya ia berhasil lolos, dan saya hanya berhasil pulang dengan timbangan.",
  ui_story_5040_50400901_72_dialog_content = "Ck... Sayang sekali. Satu skala itu saja dijual dengan harga yang sangat mahal. Bayangkan apa yang bisa Anda hasilkan jika Anda menangkap semuanya!",
  ui_story_5040_50400901_73_dialog_content = "Lagi pula, tidak ada yang pernah melihat cacing pasir merah muda sebelumnya. Siapa bilang kalau itu bukan satu-satunya di seluruh dunia? Dan tahukah Anda bahwa semakin langka sesuatu, semakin mahal harganya!",
  ui_story_5040_50400901_74_dialog_content = "Lagi pula, kenapa kamu mengejar cacing pasir merah muda? Biar kutebak, apakah kamu bersama Jeriah?",
  ui_story_5040_50400901_75_dialog_content = "Bagaimana kamu tahu?!",
  ui_story_5040_50400901_76_dialog_content = "Karena Pembicara Jeriah itu ada di mana-mana, terbang ke sana kemari di antara semua tempat cacing pasir yang biasa menghentak.",
  ui_story_5040_50400901_77_dialog_content = "Dan jika Anda sedang mencari cacing pasir sekarang, saya rasa kemungkinan besar Anda sedang mencari kawan merah muda yang besar itu.",
  ui_story_5040_50400901_78_dialog_content = "Sungguh gila menggunakan Luminatics sebanyak itu.",
  ui_story_5040_50400901_79_dialog_content = "Apa kamu tahu di mana itu??",
  ui_story_5040_50400901_80_dialog_content = "Tentu saja. Tapi info itu akan merugikanmu, Nak. Apa yang kamu punya sebagai gantinya?",
  ui_story_5040_50400901_81_dialog_content = "Um... aku...",
  ui_story_5040_50400901_82_dialog_content = "Hahaha... Lihat dirimu, gemetaran seperti itu! Apa, menurutmu aku mencoba menipumu atau apa?",
  ui_story_5040_50400901_83_dialog_content = "Ingatlah untuk membawa cokelat untuk Hawa saat Anda datang ke sini lagi, dan kami baik-baik saja.",
  ui_story_5040_50400901_84_dialog_content = "Dia mendengar bahwa Umbraton mendapatkan cokelat spesial edisi terbatas untuk Crown-festival apa pun ini dan dia telah memintanya.",
  ui_story_5040_50400901_85_dialog_content = "Anda selalu menggunakan Colossus milik Anda yang terbang ke mana-mana, jadi bantu saja dia mengambil beberapa di jalan.",
  ui_story_5040_50400901_86_dialog_content = "Tentu saja.",
  ui_story_5040_50400901_87_dialog_content = "Kalau begitu, kita punya kesepakatan sendiri.",
  ui_story_5040_50400901_88_dialog_content = "Terakhir kali aku melawan benda sialan itu, licin sekali, selalu mencari tempat untuk bersembunyi.",
  ui_story_5040_50400901_89_dialog_content = "Tapi saya mendapatkan pukulan yang bagus dengan kunci pas saya sebelum hilang, yang merobek timbangan itu dari sisi kirinya.",
  ui_story_5040_50400901_90_dialog_content = "Saya mengejarnya selama berhari-hari, tetapi akhirnya kehilangan jejak. Tempat terakhir yang saya lihat adalah jauh di dalam gurun, dekat Oasis.",
  ui_story_5040_50400901_91_dialog_content = "Namun, saya tidak dapat memberi tahu Anda lokasi persisnya.",
  ui_story_5040_50400901_92_dialog_content = "Jika Anda ingin melakukannya, sebaiknya Anda memulai pencarian dari sana.",
  ui_story_5040_50400901_93_dialog_content = "Mengerti! Terima kasih banyak, Sinsa.",
  ui_story_5040_50400901_94_dialog_content = "Jika Anda membawa Jeriah bersama Anda, saya ragu hal itu akan menimbulkan banyak masalah. Tapi hati-hati, itu salah satu penipu hebat.",
  ui_story_5040_50400901_95_dialog_content = "Apa yang membuatmu mengatakan itu? Apakah Anda mengenal Jeriah dengan baik?",
  ui_story_5040_50400901_96_dialog_content = "Saya tidak akan mengatakan itu. Dia menyendiri dan tidak banyak bicara dengan kami semua.",
  ui_story_5040_50400901_97_dialog_content = "Namun mampu bertahan sendirian di Gurun Rediesel adalah bukti kekuatannya.",
  ui_story_5040_50400901_98_dialog_content = "Selain itu, dia salah satu dari segelintir kurir di gurun pasir, jadi kami sangat mengandalkannya.",
  ui_story_5040_50400901_99_dialog_content = "Jangan khawatir, lakukan apa yang dia katakan, dan Anda akan baik-baik saja!",
  ui_story_5040_50400901_100_dialog_content = "Baiklah…",
  ui_story_5040_50400901_101_dialog_content = "Siap!",
  ui_story_5040_50400901_102_dialog_content = "Lagi pula, aku mungkin harus pergi, atau Hawa akan menggangguku untuk beristirahat.",
  ui_story_5040_50400901_103_dialog_content = "Baiklah, sampai jumpa!",
  ui_story_5040_50400901_104_dialog_content = "Aku mungkin seharusnya tidak langsung ke Jeriah sekarang. Pertama, saya akan pergi mengisi yang lain.",
  ui_story_5040_50400901_105_dialog_content = "Belum lagi aku juga kelaparan! Mari kita lihat apa yang ada di menu hari ini!",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>Sementara itu, di divisi Courier Union Rediesel Wrench...</color>",
  ui_story_5040_50400901_107_dialog_content = "Semua surat yang tertinggal harus ada di sini.",
  ui_story_5040_50400901_108_dialog_content = "Dengan padang pasir yang luas dan semua orang Rediesel Wrench berkeliaran di mana-mana, tidak mengherankan jika ada banyak surat yang tidak diklaim.",
  ui_story_5040_50400901_109_dialog_content = "Mungkin perlu beberapa saat untuk menemukan apa yang kita cari.",
  ui_story_5040_50400901_110_dialog_content = "Sable... akan... membantu...",
  ui_story_5040_50400901_111_dialog_content = "Kami akan bekerja sama! Pertama kita perlu melihat berapa banyak huruf yang ada.",
  ui_story_5040_50400901_112_dialog_content = "Sangat banyak!",
  ui_story_5040_50400901_113_dialog_content = "Tunggu, ini ada catatannya.",
  ui_story_5040_50400901_114_dialog_content = "\"Penerima Hilang\", \"Penerima Tidak Dikenal\", \"Ditolak\"...",
  ui_story_5040_50400901_115_dialog_content = "Apakah semuanya benar-benar telah diajukan dalam kategori yang berbeda?!",
  ui_story_5040_50400901_116_dialog_content = "Kya... lihat... disana.",
  ui_story_5040_50400901_117_dialog_content = "Yang ini bertuliskan \"Stempel yang Sama\"?!",
  ui_story_5040_50400901_118_dialog_content = "Ada beberapa kata yang tertulis di bawahnya, yang berbunyi, \"Tersangka pengirimnya adalah orang yang sama.\"",
  ui_story_5040_50400901_119_dialog_content = "Cap di sini sama dengan milikmu, Sable.",
  ui_story_5040_50400901_120_dialog_content = "Ini... adalah... milikku...",
  ui_story_5040_50400901_121_dialog_content = "Aku tidak percaya kami menemukan apa yang kami cari begitu cepat. Untunglah!",
  ui_story_5040_50400901_122_dialog_content = "Mari kita lihat surat-suratnya.",
  ui_story_5040_50400901_123_dialog_content = "Ya…",
  ui_story_5040_50400901_124_dialog_content = "\"Terima kasih telah bersedia menjadi sahabat penaku! Senang bertemu denganmu.\"",
  ui_story_5040_50400901_125_dialog_content = "\"Gurun pasir terlalu panas bagi kebanyakan orang, jadi tampaknya semua orang tinggal sangat jauh. Kami harus bergantung pada kurir untuk berkomunikasi.\"",
  ui_story_5040_50400901_126_dialog_content = "\"Jika kita bisa bepergian bersama, aku akan senang meninggalkan padang pasir.\"",
  ui_story_5040_50400901_127_dialog_content = "Surat-surat ini sepertinya ditulis saat Anda pertama kali mengenal penerimanya.",
  ui_story_5040_50400901_128_dialog_content = "Alamat penerima selalu berbeda, dan tidak ada alamat pengirim.",
  ui_story_5040_50400901_129_dialog_content = "Mungkinkah rumah Anda berada di gurun?",
  ui_story_5040_50400901_130_dialog_content = "Mm...",
  ui_story_5040_50400901_131_dialog_content = "Ah!!",
  ui_story_5040_50400901_132_dialog_content = "Warna hitam?!",
  ui_story_5040_50400901_133_dialog_content = "Aku ingat...",
  ui_story_5040_50400901_134_dialog_content = "Rumahku... gurun yang dalam...",
  ui_story_5040_50400901_135_dialog_content = "Tapi ... di mana ... tidak ingat ...",
  ui_story_5040_50400901_136_dialog_content = "Itu tidak masalah, ini sudah menjadi petunjuk yang sangat berguna. Selanjutnya, kita tinggal bertanya kepada orang-orang yang tinggal di gurun!",
  ui_story_5040_50400901_137_dialog_content = "Jangan memaksakan diri untuk mengingat terlalu keras. Istirahat dulu.",
  ui_story_5040_50400901_138_dialog_content = "Saya menerima permintaan Anda, jadi kurir dalam diri saya akan melakukan yang terbaik untuk membantu Anda.",
  ui_story_5040_50400901_139_dialog_content = "Baiklah…",
  ui_story_5040_50400901_140_dialog_content = "Ada apa, Sabel? Anda tampak agak lesu.",
  ui_story_5040_50400901_141_dialog_content = "Tara, Adonis... Hubungan baik...",
  ui_story_5040_50400901_142_dialog_content = "Hargai... satu sama lain... bantu... satu sama lain...",
  ui_story_5040_50400901_143_dialog_content = "Saya ingin...",
  ui_story_5040_50400901_144_dialog_content = "(Sable tidak diperlakukan dengan baik oleh orang yang dia cintai, juga cintanya tidak dibalas.)",
  ui_story_5040_50400901_145_dialog_content = "(Melihat keduanya begitu bahagia pasti membuatnya merasa sedih...)",
  ui_story_5040_50400901_146_dialog_content = "Jangan merasa buruk. Pria yang memperlakukanmu dengan sangat buruk itu sudah berlalu sekarang!",
  ui_story_5040_50400901_147_dialog_content = "Tetua saya selalu memberi tahu saya bahwa dalam pengalaman mereka, karma selalu menimpa mereka yang tidak memperlakukan orang lain dengan baik.",
  ui_story_5040_50400901_148_dialog_content = "Adapun Tara dan Adonis, jika berada di sekitar mereka membuatmu kesal, kita bisa keluar dari sini dan melanjutkan sendiri.",
  ui_story_5040_50400901_149_dialog_content = "Tidak apa-apa...",
  ui_story_5040_50400901_150_dialog_content = "Mereka... mengingatkanku... saat-saat bahagia...",
  ui_story_5040_50400901_151_dialog_content = "Keluarga... Teman... Cinta...",
  ui_story_5040_50400901_152_dialog_content = "Perasaan hangat itu... Apakah semua yang kuinginkan...",
  ui_story_5040_50400901_153_dialog_content = "Kehangatan itu... sangat berharga, jadi aku... berharap mereka baik-baik saja...",
  ui_story_5040_50400901_154_dialog_content = "Baiklah…",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>*Aduh*</color>",
  ui_story_5040_50400901_156_dialog_content = "Lapar...",
  ui_story_5040_50400901_157_dialog_content = "Saya juga. Ayo pergi makan!",
  ui_story_5040_50400901_158_dialog_content = "(Aku tidak menyadari hari sudah sangat larut, dan aku tidak tahu bagaimana Tara dan yang lainnya makan malam.)",
  ui_story_5040_50400901_159_dialog_content = "Hatsyiii!",
  ui_story_5040_50400901_160_dialog_content = "(I-Rasa pedas dan pedas ini hanya bisa... Rediesel barbekyu!)",
  ui_story_5040_50400901_161_dialog_content = "Hm? Kya, Sable, bukankah kalian berdua baru saja menjelajah?",
  ui_story_5040_50400901_162_dialog_content = "Kami sudah selesai, dan karena kami kelaparan, kami memutuskan untuk kembali dan melihat bagaimana makan malam berlangsung!",
  ui_story_5040_50400901_163_dialog_content = "Ya…",
  ui_story_5040_50400901_164_dialog_content = "(Saya tidak tahu bahwa simpanan email telah dipisahkan dan dikategorikan.)",
  ui_story_5040_50400901_165_dialog_content = "(Mereka bahkan diatur bersama oleh pengirim berdasarkan kesamaan kecil!)",
  ui_story_5040_50400901_166_dialog_content = "(Hanya berkat itu, kami berhasil menemukan surat Sable dengan sangat cepat.)",
  ui_story_5040_50400901_167_dialog_content = "(Saya kira itu semua Jeriah.)",
  ui_story_5040_50400901_168_dialog_content = "Pasti ramai di sekitar sini.",
  ui_story_5040_50400901_169_dialog_content = "Bau itu... ha. Anda orang Rediesel Wrench hanya tahu cara memasak barbekyu yang berapi-api, ya?",
  ui_story_5040_50400901_170_dialog_content = "Saat Anda berada di gurun, Anda makan seperti penghuni gurun.",
  ui_story_5040_50400901_171_dialog_content = "Apakah Anda menyelesaikan semuanya, Jeriah?",
  ui_story_5040_50400901_172_dialog_content = "Ya. Mobil dan perbekalan sudah siap, dan saya juga mengidentifikasi jangkauan aktif cacing pasir.",
  ui_story_5040_50400901_173_dialog_content = "Itu terluka dari serangan sebelumnya, jadi saat ini menuju lebih dalam ke padang pasir.",
  ui_story_5040_50400901_174_dialog_content = "(Itu sejalan dengan apa yang Sinsa katakan padaku.)",
  ui_story_5040_50400901_175_dialog_content = "(Lebih baik tidak mengatakan apa-apa, kalau-kalau Jeriah marah lagi ...)",
  ui_story_5040_50400901_176_dialog_content = "Waktu yang tepat! Dendeng kadal sudah siap, datang dan makanlah!",
  ui_story_5040_50400901_177_dialog_content = "Apakah ini benar-benar tusuk sate? Anda bahkan tidak bisa melihat apa pun di bawah semua cabai.",
  ui_story_5040_50400901_178_dialog_content = "Ini dikenal sebagai dendeng kadal yang sangat pedas. Hanya petualang kuliner paling berani yang berani mencicipi masakan Rediesel terbaik ini.",
  ui_story_5040_50400901_179_dialog_content = "Eh, apakah saya harus?",
  ui_story_5040_50400901_180_dialog_content = "Ada begitu banyak cabai di atasnya, hanya dengan melihatnya membuat mata saya panas.",
  ui_story_5040_50400901_181_dialog_content = "Apakah Anda akan memiliki beberapa atau tidak?",
  ui_story_5040_50400901_182_dialog_content = "Ya! Tentu saja.",
  ui_story_5040_50400901_183_dialog_content = "Jangan memaksakan diri, Adonis.",
  ui_story_5040_50400901_184_dialog_content = "*Nyam, nyam*",
  ui_story_5040_50400901_185_dialog_content = "...",
  ui_story_5040_50400901_186_dialog_content = "Dia- Dia memakan semuanya sekaligus?",
  ui_story_5040_50400901_187_dialog_content = "…!",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>Dug!</color>",
  ui_story_5040_50400901_189_dialog_content = "A-Adonis?!",
  ui_story_5040_50400901_190_dialog_content = "Hahaha, maukah kamu melihat itu! Dia benar-benar ungu!",
  ui_story_5040_50400901_191_dialog_content = "Pedas...",
  ui_story_5040_50400901_192_dialog_content = "<size=45>SANGAT PEDAS!!</size>",
  ui_story_5040_50400901_193_dialog_content = "Wah, sepertinya dia akan pingsan!",
  ui_story_5040_50400901_194_dialog_content = "Cepat, seseorang ambilkan dia susu! Kudengar susu bagus untuk menangkal makanan pedas!",
  ui_story_5040_50400901_195_dialog_content = "Aku akan pergi melihat!",
  ui_story_5040_50400901_196_dialog_content = "...",
  ui_story_5040_50400901_197_dialog_content = "(Kenapa dia pergi? Aku akan pergi melihat ada apa.)",
  ui_story_5040_50400901_198_dialog_content = "Saya menemukan beberapa susu!",
  ui_story_5040_50400901_199_dialog_content = "Adonis, minum ini!",
  ui_story_5040_50400901_200_dialog_content = "*Glek, glek, glek*",
  ui_story_5040_50400901_201_dialog_content = "Ah... Ahhh... Apa aku masih bernafas...?",
  ui_story_5040_50400901_202_dialog_content = "Anda baru saja makan seluruh tusuk sate dendeng kadal yang sangat pedas, lalu langsung jatuh.",
  ui_story_5040_50400901_203_dialog_content = "Sungguh?",
  ui_story_5040_50400901_204_dialog_content = "Urgh... Perutku sakit, seperti menelan bongkahan batu bara yang terbakar...",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>Urgh!</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "Adonis?!!",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>Sementara itu...</color>",
  ui_story_5040_50400901_208_dialog_content = "Pacar kecilmu memuntahkan otaknya di sana. Apakah kamu tidak akan pergi untuk melihat apakah dia baik-baik saja?",
  ui_story_5040_50400901_209_dialog_content = "Atau kamu punya ide cemerlang lainnya?",
  ui_story_5040_50400901_210_dialog_content = "Aku akan membawa Adonis kembali ke Northland segera setelah dia pulih.",
  ui_story_5040_50400901_211_dialog_content = "Aku lelah. Saya tidak ingin melakukan ini lagi.",
  ui_story_5040_50400901_212_dialog_content = "Kita tidak ditakdirkan untuk bersama. Kami tidak cocok.",
  ui_story_5040_50400901_213_dialog_content = "Oh?",
  ui_story_5040_50400901_214_dialog_content = "Saya dulu berpikir bahwa selama kita bersama, kita bisa mengatasi apa pun.",
  ui_story_5040_50400901_215_dialog_content = "Saya selalu ingin memberinya rasa kehidupan Gurun Rediesel, seperti barbekyu barusan ...",
  ui_story_5040_50400901_216_dialog_content = "tetapi saya tidak pernah berpikir bahwa hal-hal yang saya sukai benar-benar akan menyakitinya.",
  ui_story_5040_50400901_217_dialog_content = "Dia terus terluka, semua karena dia memaksa dirinya menjadi calo bagiku.",
  ui_story_5040_50400901_218_dialog_content = "Menurutku itu bukan cinta.",
  ui_story_5040_50400901_X218_dialog_content = "Huh... birdie yang sedang jatuh cinta tentu melompat ke segala macam kesimpulan atas hal-hal sepele.",
  ui_story_5040_50400901_X219_dialog_content = "Mengapa Anda berpikir demikian?",
  ui_story_5040_50400901_219_dialog_content = "Ada jurang pemisah di antara kami, baik dalam gaya hidup maupun kepribadian. Mungkin orang tuanya benar.",
  ui_story_5040_50400901_220_dialog_content = "Burung Northland kekurangan bulu tipis dan tidak tahu cara menggali air, jadi tentu saja mereka tidak bisa bertahan hidup di gurun.",
  ui_story_5040_50400901_221_dialog_content = "...",
  ui_story_5040_50400901_222_dialog_content = "Ini bukanlah sesuatu yang bisa diatasi dengan keberanian sebesar apa pun. Ini masalah perbedaan bawaan.",
  ui_story_5040_50400901_223_dialog_content = "Apa yang biasa bagi burung gurun berbahaya bagi burung Northland.",
  ui_story_5040_50400901_224_dialog_content = "Namun…",
  ui_story_5040_50400901_225_dialog_content = "Namun, apa?",
  ui_story_5040_50400901_226_dialog_content = "Burung kecilmu itu tidak bisa menahan apa pun yang pedas, namun dia tetap melahap tusuk sate dan berakhir di lantai.",
  ui_story_5040_50400901_227_dialog_content = "Tentunya dia ingin menunjukkan kepada Anda, meski hanya sesaat, kesediaannya untuk melangkah dan berani?",
  ui_story_5040_50400901_228_dialog_content = "Kalian bisa menemukan gaya hidup yang cocok untuk kalian berdua secara bertahap.",
  ui_story_5040_50400901_229_dialog_content = "Daripada membatasi diri Anda hanya untuk menjalani gaya hidup Rediesel.",
  ui_story_5040_50400901_230_dialog_content = "…!",
  ui_story_5040_50400901_231_dialog_content = "Hanya itu yang ingin saya katakan.",
  ui_story_5040_50400901_232_dialog_content = "Apakah Anda berdua berakhir bersama atau tidak, Anda ada di sini sekarang, jadi sebaiknya Anda menikmatinya.",
  ui_story_5040_50400901_233_dialog_content = "Santai, bersenang-senang, dan jangan menurunkan suasana.",
  ui_story_5040_50400901_234_dialog_content = "...",
  ui_story_5040_50400901_235_dialog_content = "Hmm.",
  ui_story_5040_50400901_236_dialog_content = "Aku akan kembali.",
  ui_story_5040_50400901_237_dialog_content = "Burung kecil yang menarik.",
  ui_story_5040_50400901_238_dialog_content = "Saya ingin tahu apa bab selanjutnya dari hubungan Anda.",
  ui_story_5040_50400901_239_dialog_content = "... Ha, apa yang terjadi padaku?",
  ui_story_5040_50400901_240_dialog_content = "Aku bahkan tidak percaya aku peduli.",
  ui_story_5040_50401001_1_dialog_content = "Ah, kamu sudah datang?",
  ui_story_5040_50401001_2_dialog_content = "Kami sepakat untuk mencari cacing pasir hari ini, jadi saya bangun pagi-pagi sekali.",
  ui_story_5040_50401001_3_dialog_content = "Ditambah lagi tidak ada yang cukup berani untuk memakan tusuk sate itu, jadi kami akhirnya harus mencari sesuatu untuk dimakan di Soroz...",
  ui_story_5040_50401001_4_dialog_content = "Kalian tidak menghargai makanan enak. Tapi jangan khawatir, saya makan sisa barbekyu.",
  ui_story_5040_50401001_5_dialog_content = "Tidak satu gigitan pun terbuang sia-sia!",
  ui_story_5040_50401001_6_dialog_content = "Saya pasti setuju untuk tidak membuang-buang makanan.",
  ui_story_5040_50401001_7_dialog_content = "Jadi, bagaimana semua orang tidur tadi malam?",
  ui_story_5040_50401001_8_dialog_content = "Saya pribadi tidur dengan luar biasa.",
  ui_story_5040_50401001_9_dialog_content = "Dingin di gurun pada malam hari, tapi untungnya kamu menyiapkan selimut tebal, jadi Sable dan aku baik-baik saja.",
  ui_story_5040_50401001_10_dialog_content = "Terima kasih... Jeriah.",
  ui_story_5040_50401001_11_dialog_content = "Oh, tidak masalah sama sekali, Sable.",
  ui_story_5040_50401001_12_dialog_content = "aku, eh...",
  ui_story_5040_50401001_13_dialog_content = "Perutku sakit sepanjang malam...",
  ui_story_5040_50401001_14_dialog_content = "(Pasti Adonis yang kudengar bergegas ke kamar mandi beberapa kali tadi malam.)",
  ui_story_5040_50401001_15_dialog_content = "Apakah Anda ingin istirahat sebentar sebelum berangkat?",
  ui_story_5040_50401001_16_dialog_content = "Aku baik-baik saja!",
  ui_story_5040_50401001_17_dialog_content = "Aku benar-benar baik-baik saja, serius!",
  ui_story_5040_50401001_18_dialog_content = "...",
  ui_story_5040_50401001_19_dialog_content = "(Tara terlihat lucu di wajahnya sejak makan malam tadi malam. Apakah ada sesuatu yang dia pikirkan?)",
  ui_story_5040_50401001_20_dialog_content = "Baiklah. Kalau begitu, mari kita pergi. Tara boleh duduk di kursi penumpang, dan sisanya duduk di belakang.",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>Suatu saat nanti...</color>",
  ui_story_5040_50401001_22_dialog_content = "Ini berada di dekat area gurun yang dalam yang dihuni oleh cacing pasir.",
  ui_story_5040_50401001_23_dialog_content = "Mari kita istirahat terakhir kita di sini.",
  ui_story_5040_50401001_24_dialog_content = "Saya memindahkan tenda, peralatan masak, dan semua makanan dari mobil dengan Sable.",
  ui_story_5040_50401001_25_dialog_content = "Kita bisa mulai memasak kapan saja!",
  ui_story_5040_50401001_26_dialog_content = "Bagus.",
  ui_story_5040_50401001_27_dialog_content = "Sekarang semua barang bawaan sudah diturunkan, ayo kembali ke mobil.",
  ui_story_5040_50401001_28_dialog_content = "Hah? Mengapa? Bukankah kita akan istirahat?",
  ui_story_5040_50401001_29_dialog_content = "Kami masih memiliki satu hal lagi yang harus dilakukan sebelum itu.",
  ui_story_5040_50401001_30_dialog_content = "Bukit pasir di depan curam dan miring. Mengendarai ombak berpasir itu adalah cara sempurna untuk melepaskan dan bersantai.",
  ui_story_5040_50401001_31_dialog_content = "Apa hubungannya bukit pasir dengan bersantai?",
  ui_story_5040_50401001_32_dialog_content = "Anda akan mengetahuinya sebentar lagi, birdie Northland.",
  ui_story_5040_50401001_X32_dialog_content = "Baiklah, masuk ke dalam mobil.",
  ui_story_5040_50401001_X33_dialog_content = "Tapi itu...",
  ui_story_5040_50401001_X34_dialog_content = "Berhenti gagap dan masuk saja ke dalam mobil!",
  ui_story_5040_50401001_X35_dialog_content = "Anda juga bisa ikut, Caelestite kecil.",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>Di dalam mobil</color>",
  ui_story_5040_50401001_X37_dialog_content = "Apakah semua orang baik untuk pergi?",
  ui_story_5040_50401001_X38_dialog_content = "Jeriah, a-apa yang kamu rencanakan?",
  ui_story_5040_50401001_X39_dialog_content = "Wah, aku akan melakukan sesuatu untuk membuat Tara bahagia, tentu saja.",
  ui_story_5040_50401001_X40_dialog_content = "Aku punya firasat buruk tentang ini... Bisakah kau membiarkanku keluar dari sini!?",
  ui_story_5040_50401001_X41_dialog_content = "Aku akan membuatkanmu makan siang—",
  ui_story_5040_50401001_X42_dialog_content = "Bukan kesempatan. Anda adalah bagian tak terpisahkan dari pengalaman ini.",
  ui_story_5040_50401001_33_option_content = "Sangat diperlukan!?",
  ui_story_5040_50401001_34_dialog_content = "Tentu saja. Anda adalah navigator vital kami.",
  ui_story_5040_50401001_35_option_content = "Saya pikir saya akan lulus!",
  ui_story_5040_50401001_36_dialog_content = "Sekarang jangan kedinginan.",
  ui_story_5040_50401001_37_dialog_content = "Ingatlah untuk mengencangkan sabuk pengaman Anda.",
  ui_story_5040_50401001_38_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5040_50401001_39_dialog_content = "Ahhh!",
  ui_story_5040_50401001_40_dialog_content = "I-Ini terlalu cepat!",
  ui_story_5040_50401001_41_dialog_content = "WOO HOO! Ini luar biasa!",
  ui_story_5040_50401001_42_dialog_content = "Lebih cepat, Jeriah, lebih cepat!",
  ui_story_5040_50401001_43_dialog_content = "Membantu! Mobil ini akan lepas landas!",
  ui_story_5040_50401001_44_dialog_content = "Apa ini... rasanya terbang?",
  ui_story_5040_50401001_X44_dialog_content = "Berhenti! Jangan terlalu cepat... Ini berbahaya!",
  ui_story_5040_50401001_X45_dialog_content = "Perutku ... tidak enak ...",
  ui_story_5040_50401001_45_dialog_content = "Anda harus terus terbang lebih cepat sampai Anda melihat badai di mata untuk benar-benar memahami ekstasi penerbangan!",
  ui_story_5040_50401001_46_dialog_content = "Gahhhh!!!",
  ui_story_5040_50401001_47_dialog_content = "Hati-Hati! Suara mesin menarik Eclipsites!",
  ui_story_5040_50401001_48_dialog_content = "Caelestite kecil, saatnya pertunjukan!",
  ui_story_5040_50401001_49_dialog_content = "Hah?!",
  ui_story_5040_50401001_50_dialog_content = "Saya tidak peduli apakah Anda menggunakan mata atau kemampuan psikis Anda — beri tahu saya dengan tepat dari mana Eclipsites akan menyerang.",
  ui_story_5040_50401001_51_dialog_content = "Kapan kita pergi secepat ini? Anda membuat segalanya menjadi sulit dengan sengaja!",
  ui_story_5040_50401001_52_dialog_content = "Aahhhh!",
  ui_story_5040_50401001_53_dialog_content = "Oh! Dari belakang, sisi kiri!",
  ui_story_5040_50401001_54_dialog_content = "Bagus.",
  ui_story_5040_50401001_55_dialog_content = "<color=#e8d9bb>*Screeeee—!*</color>",
  ui_story_5040_50401001_56_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5040_50401001_57_dialog_content = "Kami baru saja menerbangkan Eclipsite!",
  ui_story_5040_50401001_58_dialog_content = "Aku butuh... Oh, tidak... *Retch*!",
  ui_story_5040_50401001_59_dialog_content = "Jangan muntah di mobilku, burung kecil Northland.",
  ui_story_5040_50401001_60_dialog_content = "Lihatlah betapa bahagianya Tara sekali ini.",
  ui_story_5040_50401001_61_dialog_content = "B-Benarkah? Lalu aku harus... bertahan... untuk Tara...",
  ui_story_5040_50401001_62_dialog_content = "...",
  ui_story_5040_50401001_63_dialog_content = "Grahh!!",
  ui_story_5040_50401001_64_dialog_content = "Lebih banyak Eclipsites, mati di depan!",
  ui_story_5040_50401001_65_dialog_content = "Mari tunjukkan semangat kita dan beri mereka kecepatan.",
  ui_story_5040_50401001_66_dialog_content = "Maju dengan kecepatan penuh!",
  ui_story_5040_50401001_67_dialog_content = "Hahaha, ini bagus!",
  ui_story_5040_50401001_68_dialog_content = "Oh tidak, tidak, aku akan... *Retch*!",
  ui_story_5040_50401001_69_dialog_content = "Mabuk dari perjalanan singkat? Saya kira seekor burung Northland perlu waktu untuk terbiasa dengan padang pasir.",
  ui_story_5040_50401001_70_dialog_content = "Sedangkan burung gurun hanya terbang bebas saat terbawa angin gurun.",
  ui_story_5040_50401001_71_dialog_content = "Ya...",
  ui_story_5040_50401001_72_dialog_content = "Saya telah memutuskan.",
  ui_story_5040_50401001_73_dialog_content = "Sudahkah kamu sekarang? Akhirnya.",
  ui_story_5040_50401001_74_dialog_content = "Ya. Sebenarnya, Adonis, aku—",
  ui_story_5040_50401001_75_dialog_content = "Hah?",
  ui_story_5040_50401001_76_dialog_content = "<color=#e8d9bb>Bergemuruh-</color>",
  ui_story_5040_50401001_77_dialog_content = "Nona Jeriah! Gerhana!",
  ui_story_5040_50401001_78_dialog_content = "Ada banyak dari mereka yang menuju ke arah kita!",
  ui_story_5040_50401001_79_dialog_content = "Orang-orang ini benar-benar tahu cara merusak suasana.",
  ui_story_5040_50401001_80_dialog_content = "Kaulah yang menyalakan mesin tadi, Jeriah! Kebisingan pasti menarik mereka!",
  ui_story_5040_50401001_81_dialog_content = "Mari kita lanjutkan pembicaraan kita nanti, burung-burung kecil.",
  ui_story_5040_50401001_82_dialog_content = "Saat ini kita harus berurusan dengan orang-orang ini, lalu kita akan makan siang yang enak.",
  ui_story_5040_50401001_83_dialog_content = "Huh...",
  ui_story_5040_50401001_84_dialog_content = "Aku akan membantu!",
  ui_story_5040_50401002_1_dialog_content = "Mereka lebih manis saat berada di tanah.",
  ui_story_5040_50401002_2_dialog_content = "Graaahh—",
  ui_story_5040_50401002_3_dialog_content = "Takut...",
  ui_story_5040_50401002_4_dialog_content = "Jangan takut, dia tidak akan... Eh, maksudku, kita sudah berurusan dengan Eclipsites.",
  ui_story_5040_50401002_5_dialog_content = "Jeriah... tidak menakutkan...",
  ui_story_5040_50401002_6_dialog_content = "Jeriah... orang baik... Lindungi semua orang...",
  ui_story_5040_50401002_7_dialog_content = "Tapi Eclipsites merusak segalanya, termasuk persediaan makanan kami!",
  ui_story_5040_50401002_8_dialog_content = "Tadinya saya berencana membuat camilan ala Umbraton, tapi sekarang semuanya terbalik. Benar-benar tidak dapat digunakan!",
  ui_story_5040_50401002_9_dialog_content = "Oh tidak, apa yang harus kita lakukan?",
  ui_story_5040_50401002_10_dialog_content = "(Apakah Jeriah hanya melirik Adonis?)",
  ui_story_5040_50401002_11_dialog_content = "Saya punya ide.",
  ui_story_5040_50401002_12_dialog_content = "Ya?",
  ui_story_5040_50401002_13_dialog_content = "Saya pikir kita masih bisa menggunakan barang ini jika kita hanya membersihkannya.",
  ui_story_5040_50401002_14_dialog_content = "Saya tidak yakin kami bisa menggunakannya untuk apa yang Anda rencanakan, tapi kami pasti bisa memasak sup.",
  ui_story_5040_50401002_15_dialog_content = "Serahkan padaku!",
  ui_story_5040_50401002_16_dialog_content = "(Adonis benar-benar langsung ke bisnis!)",
  ui_story_5040_50401002_17_dialog_content = "Pertama, potong bagian yang memar atau rusak, simpan yang masih bisa digunakan.",
  ui_story_5040_50401002_18_dialog_content = "Kemudian potong-potong seukuran gigitan dan masukkan ke dalam air mendidih.",
  ui_story_5040_50401002_19_dialog_content = "Tara, tolong berikan itu padaku?",
  ui_story_5040_50401002_20_dialog_content = "Ini.",
  ui_story_5040_50401002_21_dialog_content = "Terima kasih. Sekarang kita tambahkan sedikit garam...",
  ui_story_5040_50401002_22_dialog_content = "Baunya enak!",
  ui_story_5040_50401002_23_dialog_content = "Ini mangkuk untukmu, Tara. Aku tahu kamu tidak suka lobak, jadi aku sudah memilih semuanya.",
  ui_story_5040_50401002_24_dialog_content = "Terima kasih…",
  ui_story_5040_50401002_25_dialog_content = "Mangkuk untukku juga, tolong! Dan satu untuk Sable!",
  ui_story_5040_50401002_26_dialog_content = "Baiklah, baiklah, tunggu... Aku akan menyiapkan milikmu.",
  ui_story_5040_50401002_27_dialog_content = "Di sini, saya telah membawa mangkuk.",
  ui_story_5040_50401002_28_dialog_content = "Mmm, makan siang yang menyenangkan!",
  ui_story_5040_50401002_29_dialog_content = "Agak aneh makan sup panas di tengah padang pasir, tapi sangat enak sampai aku tidak peduli!",
  ui_story_5040_50401002_30_dialog_content = "Itulah satu-satunya hal yang penting!",
  ui_story_5040_50401002_31_dialog_content = "Biarkan saya menangani cucian.",
  ui_story_5040_50401002_32_dialog_content = "Oke. Saya akan melihat sekilas di sekitar area, dan memastikan tidak ada lagi Eclipsites.",
  ui_story_5040_50401002_33_dialog_content = "Tunggu, bukankah kamu mengatakan sesuatu sebelumnya?",
  ui_story_5040_50401002_34_dialog_content = "Saya hampir lupa, dengan seluruh kegagalan Eclipsite.",
  ui_story_5040_50401002_35_dialog_content = "... Tidak, itu bukan apa-apa. Aku pergi untuk berpatroli.",
  ui_story_5040_50401002_36_dialog_content = "Aku akan jalan-jalan dengan Sable, lihat pemandangannya.",
  ui_story_5040_50401002_37_dialog_content = "(Aneh... Sepertinya Tara menyembunyikan sesuatu dariku.)",
  ui_story_5040_50401002_38_dialog_content = "(Dan sebelumnya, Tara memberiku garam bahkan sebelum aku memintanya.)",
  ui_story_5040_50401002_39_dialog_content = "(Apakah ingatannya mulai kembali?)",
  ui_story_5040_50401002_40_dialog_content = "(Dikatakan demikian, dia agak aneh sepanjang perjalanan.)",
  ui_story_5040_50401002_41_dialog_content = "(Cara dia ragu-ragu barusan sangat mirip dengan dia dulu, ketika hendak meminta maaf untuk sesuatu.)",
  ui_story_5040_50401002_42_dialog_content = "(Benar-benar aneh. Mungkinkah... dia tidak pernah benar-benar menderita amnesia?)",
  ui_story_5040_50401002_43_dialog_content = "(Tapi kenapa dia melakukan ini? Aku harus berpikir...)",
  ui_story_5040_50401002_44_dialog_content = "(Dia pura-pura kehilangan ingatannya, yang memaksaku meninggalkan Northland... mungkinkah ini semua tipu muslihat untuk membuatku lebih berani?)",
  ui_story_5040_50401002_45_dialog_content = "(Tara, aku akan membuktikan diriku padamu. Aku berjanji!)",
  ui_story_5040_50401002_46_dialog_content = "Penny untuk pemikiranmu, Adonis?",
  ui_story_5040_50401002_47_dialog_content = "Oh, tidak apa-apa. Ada apa?",
  ui_story_5040_50401002_48_dialog_content = "Ada yang bisa saya bantu?",
  ui_story_5040_50401002_49_dialog_content = "Tidak apa-apa. Saya bisa merapikan diri.",
  ui_story_5040_50401002_50_dialog_content = "Anda dapat pergi melakukan sesuatu yang lain.",
  ui_story_5040_50401002_51_dialog_content = "Baiklah.",
  ui_story_5040_50401002_52_dialog_content = "(Saya sangat bosan sendiri. Saya berharap Vice dan Carleen ada di sini sekarang, saya rindu mengobrol dengan mereka.)",
  ui_story_5040_50401002_53_dialog_content = "(Jeriah sedikit penyendiri. Apakah dia tidak pernah bosan?)",
  ui_story_5040_50401002_54_dialog_content = "(Mudah-mudahan dia tidak marah lagi. Mungkin aku harus memeriksanya.)",
  ui_story_5040_50401002_55_dialog_content = "Sigh, itu melelahkan, tapi ...",
  ui_story_5040_50401002_56_dialog_content = "Tara, Adonis... Heheh, itu dua burung kecil yang menarik.",
  ui_story_5040_50401002_57_dialog_content = "Yeriah!",
  ui_story_5040_50401002_58_dialog_content = "Hah? Oh, kalau bukan Caelestite muda! Apa yang membawamu ke sini?",
  ui_story_5040_50401002_59_dialog_content = "Mungkinkah Anda kesepian tanpa teman-teman muda Anda yang lain?",
  ui_story_5040_50401002_60_dialog_content = "T-Tidak! Tentu saja tidak!",
  ui_story_5040_50401002_61_dialog_content = "Atau mungkin Anda menganggap saya menyedihkan, di sini sendirian, dan berpikir teman akan dihargai?",
  ui_story_5040_50401002_62_dialog_content = "Bukan itu juga...",
  ui_story_5040_50401002_63_dialog_content = "Ada sesuatu yang ingin aku tanyakan padamu.",
  ui_story_5040_50401002_64_dialog_content = "Oh?",
  ui_story_5040_50401002_65_option_content = "Apakah Anda benar-benar jujur?",
  ui_story_5040_50401002_66_dialog_content = "Kok kau bisa bilang begitu?",
  ui_story_5040_50401002_67_dialog_content = "Anda mengatakan pagi ini bahwa Anda tidur nyenyak.",
  ui_story_5040_50401002_68_dialog_content = "Tapi itu tidak sesuai dengan apa yang saya dengar!",
  ui_story_5040_50401002_69_option_content = "Apakah Anda memasang wajah berani?",
  ui_story_5040_50401002_70_dialog_content = "Wajah berani? Dan apa yang membuat Anda sampai pada kesimpulan itu?",
  ui_story_5040_50401002_71_dialog_content = "Saya mendengar bahwa kemarin Anda mengirim Pembicara Anda untuk menjelajahi seluruh gurun, mencari cacing pasir.",
  ui_story_5040_50401002_72_dialog_content = "...",
  ui_story_5040_50401002_73_dialog_content = "Bahkan jika saya melakukannya, jadi apa?",
  ui_story_5040_50401002_74_dialog_content = "Itu sembrono!",
  ui_story_5040_50401002_75_dialog_content = "Menggunakan Luminatics yang begitu intens begitu lama, lalu bangun pagi-pagi sekali—saya yakin Anda tidak beristirahat dengan baik, bukan? Dan sekarang kau masih pergi.",
  ui_story_5040_50401002_76_dialog_content = "Anda berlebihan!",
  ui_story_5040_50401002_77_dialog_content = "Sekali lagi... seandainya Anda benar, terus kenapa?",
  ui_story_5040_50401002_78_dialog_content = "Saya hanya mengatakan, Anda tidak perlu memaksakan diri terlalu keras. Tidak apa-apa untuk bersandar pada orang lain sesekali.",
  ui_story_5040_50401002_79_dialog_content = "Saya bisa bertahan dengan baik di padang pasir sendirian.",
  ui_story_5040_50401002_80_dialog_content = "Saya sangat mampu melacak sandworm sendirian, sambil menyelesaikan tugas Courier Union dan mengirimkan surat ke seluruh gurun.",
  ui_story_5040_50401002_81_dialog_content = "Lagipula apa hakmu untuk meragukanku?",
  ui_story_5040_50401002_82_dialog_content = "Aku tidak meragukanmu!",
  ui_story_5040_50401002_83_dialog_content = "Saya sangat menyadari bahwa, sebagai seorang Caelestite, saya tidak memiliki Luminatics yang sangat kuat. Saya juga tahu bahwa saya sangat tidak berguna melawan Eclipsites.",
  ui_story_5040_50401002_84_dialog_content = "Itu sebabnya saya mengandalkan kekuatan teman saya sepanjang waktu.",
  ui_story_5040_50401002_85_dialog_content = "Itu karena saya lemah sehingga saya menyadari bahwa tidak ada yang bisa bertahan hidup di dunia ini sepenuhnya sendirian.",
  ui_story_5040_50401002_86_dialog_content = "Begitu menurutmu?",
  ui_story_5040_50401002_87_dialog_content = "Betapapun kuatnya Anda, Anda pasti akan menghadapi masalah di luar kemampuan Anda.",
  ui_story_5040_50401002_88_dialog_content = "Beberapa orang mungkin bisa bertahan, dengan mengandalkan pertumbuhan atau kerja keras mereka sendiri...",
  ui_story_5040_50401002_89_dialog_content = "tetapi beberapa masalah tidak menunggu Anda tumbuh, atau terlalu banyak, bahkan jika Anda bekerja keras.",
  ui_story_5040_50401002_90_dialog_content = "Hidupku penuh dengan masalah seperti ini karena aku Caelestite yang lemah.",
  ui_story_5040_50401002_91_dialog_content = "Maksudmu, tidak ada salahnya bersandar pada orang lain?",
  ui_story_5040_50401002_92_dialog_content = "Hehe, kamu benar-benar naif.",
  ui_story_5040_50401002_93_dialog_content = "Sekali atau dua kali mungkin baik-baik saja, tetapi terlalu banyak kali dan banyaknya bantuan menjadi beban.",
  ui_story_5040_50401002_94_dialog_content = "Seperti sangkar, beban ini menjebak seekor burung, mencegahnya terbang bebas.",
  ui_story_5040_50401002_95_dialog_content = "Saya membayangkan Anda pasti tahu bagaimana rasanya, begitu terbebani oleh hutang Anda kepada orang lain.",
  ui_story_5040_50401002_96_option_content = "Ya.",
  ui_story_5040_50401002_97_dialog_content = "Anda benar, sulit berada dalam posisi berutang budi kepada orang lain.",
  ui_story_5040_50401002_98_dialog_content = "Tepat. Saya benci perasaan itu, dan saya tidak punya keinginan untuk terlibat banyak dengan orang lain.",
  ui_story_5040_50401002_99_dialog_content = "Bisakah Anda benar-benar mengatakan bahwa hidup sendiri, tetapi bebas, adalah hal yang buruk?",
  ui_story_5040_50401002_100_dialog_content = "Sangat menyenangkan memiliki kebebasan untuk melakukan apa pun yang Anda suka tanpa perlu mempertimbangkan terlalu banyak.",
  ui_story_5040_50401002_101_dialog_content = "Tetapi interaksi dengan orang lain bukanlah transaksional.",
  ui_story_5040_50401002_102_option_content = "Tidak.",
  ui_story_5040_50401002_103_dialog_content = "Memang benar banyak orang yang telah membantuku, tapi aku tidak merasa itu adalah beban apapun.",
  ui_story_5040_50401002_104_dialog_content = "…!",
  ui_story_5040_50401002_105_dialog_content = "Setiap orang memiliki kekuatan dan kelemahan mereka sendiri, dan orang-orang saling melengkapi.",
  ui_story_5040_50401002_106_dialog_content = "Rekan saya mungkin berbakat dalam Luminatics, tapi saya bisa melihat Jejak Cahaya. Kami dapat menghadapi Eclipsites bersama-sama, berdampingan.",
  ui_story_5040_50401002_107_dialog_content = "Saya tidak tahu apa yang Anda alami yang membuat Anda begitu enggan berhubungan dengan orang lain.",
  ui_story_5040_50401002_108_dialog_content = "Tetapi hubungan adalah jalan dua arah. Ya, saya mungkin menerima bantuan orang lain, tetapi saya juga akan melakukan yang terbaik untuk membantu orang lain.",
  ui_story_5040_50401002_109_dialog_content = "...",
  ui_story_5040_50401002_110_dialog_content = "Begitulah cara Anda melihatnya, ya?",
  ui_story_5040_50401002_111_dialog_content = "Sepertinya hubunganmu dengan temanmu sama dengan dua burung kecil di sana.",
  ui_story_5040_50401002_112_dialog_content = "Apa?!",
  ui_story_5040_50401002_113_dialog_content = "Kami hanya berteman! Kami sangat tidak—",
  ui_story_5040_50401002_114_dialog_content = "Wah, wah, lihat ke mana pikiranmu pergi! Saya belum mengatakan apa-apa.",
  ui_story_5040_50401002_115_dialog_content = "Kamu...",
  ui_story_5040_50401002_116_dialog_content = "Lihatlah keduanya. Mereka saling melengkapi dengan baik, bukan?",
  ui_story_5040_50401002_117_dialog_content = "Saya kembali. Sejauh ini tidak ada jejak Eclipsites di area tersebut.",
  ui_story_5040_50401002_118_dialog_content = "Kerja bagus! Di sini, minum air dan istirahat sebentar.",
  ui_story_5040_50401002_119_dialog_content = "Ya...",
  ui_story_5040_50401002_120_dialog_content = "Tara ramah dan ceria, dengan banyak pengalaman hidup di alam liar dan berurusan dengan Eclipsites.",
  ui_story_5040_50401002_121_dialog_content = "Adonis lebih logistik, dan cukup sabar untuk menangani semua pekerjaan yang menurut Tara membosankan dan tidak terlalu bagus.",
  ui_story_5040_50401002_122_dialog_content = "Itu benar. Saya tidak pernah berpikir bahwa akan ada orang yang bisa bergaul dengan anggota Rediesel Wrench seperti itu.",
  ui_story_5040_50401002_123_dialog_content = "Apakah Anda tidak menyukai Rediesel Wrenches?",
  ui_story_5040_50401002_124_dialog_content = "Benci? Ha. Mungkin.",
  ui_story_5040_50401002_125_dialog_content = "Sejauh yang saya ketahui, mereka tidak lebih dari sekelompok bandit berpandangan pendek dan tidak berotak.",
  ui_story_5040_50401002_126_dialog_content = "Mereka menjalani kehidupan yang begitu hedonistik, tidak peduli pada apapun selain bersenang-senang.",
  ui_story_5040_50401002_127_dialog_content = "Tapi tahukah Anda, Sinsa-lah yang memberi tahu saya tentang Anda menggunakan Speaker untuk menjelajahi seluruh gurun mencari cacing pasir.",
  ui_story_5040_50401002_128_dialog_content = "Apa?",
  ui_story_5040_50401002_129_dialog_content = "Kemarin, setelah kamu menyuruhku pergi, aku menghubungi Sinsa untuk menanyakan tentang cacing pasir merah muda.",
  ui_story_5040_50401002_130_dialog_content = "Dia memberi tahu saya bahwa seseorang di Rediesel Wrench melihat Anda menggunakan Speaker Anda untuk mencari cacing pasir.",
  ui_story_5040_50401002_131_dialog_content = "Semua orang mengkhawatirkanmu.",
  ui_story_5040_50401002_132_dialog_content = "Itu hanya karena saya salah satu dari sedikit kurir di padang pasir yang dapat menyampaikan informasi yang mereka butuhkan.",
  ui_story_5040_50401002_133_dialog_content = "Bukannya begitu, sih!",
  ui_story_5040_50401002_134_dialog_content = "Baiklah, saya pikir saya sudah cukup istirahat.",
  ui_story_5040_50401002_135_dialog_content = "Hei, Jeriah!",
  ui_story_5040_50401002_136_dialog_content = "Kumpulkan barang-barang Anda. Sudah waktunya untuk keluar.",
  ui_story_5040_50401002_137_dialog_content = "Serius, Yeriah. Pergi saja dan biarkan aku menggantung, kenapa tidak...",
  ui_story_5040_50401002_138_dialog_content = "Apakah dia membiasakan hidup dalam penyangkalan dan berpura-pura semuanya baik-baik saja?",
  ui_story_5040_50401101_1_dialog_content = "Bagaimana persiapanmu, burung kecil?",
  ui_story_5040_50401101_2_dialog_content = "Saya semua berkemas dan siap untuk pergi kapan saja.",
  ui_story_5040_50401101_3_dialog_content = "Aku juga siap.",
  ui_story_5040_50401101_4_dialog_content = "Api sudah padam, dan kami memiliki semua barang-barang kami.",
  ui_story_5040_50401101_5_dialog_content = "Kamu sangat bijaksana, Kya!",
  ui_story_5040_50401101_6_dialog_content = "Terima kasih! Zamrud mengajari saya dengan baik.",
  ui_story_5040_50401101_7_dialog_content = "Siapa Zamrud?",
  ui_story_5040_50401101_8_dialog_content = "Dia adalah senior saya di Courier Union, meskipun dia sudah pensiun sekarang.",
  ui_story_5040_50401101_9_dialog_content = "Sebelum saya menjadi kurir, Emerald-lah yang mengantarkan surat ke kampung halaman saya di Faar dan desa terdekat lainnya.",
  ui_story_5040_50401101_10_dialog_content = "Kampung halaman saya sangat terpencil, jadi kami hampir tidak pernah berhubungan dengan dunia luar.",
  ui_story_5040_50401101_11_dialog_content = "Satu-satunya cara kami mengetahui apa yang sedang terjadi adalah melalui surat-surat yang dibawa Emerald.",
  ui_story_5040_50401101_12_dialog_content = "Dia pasti orang yang sangat bertanggung jawab.",
  ui_story_5040_50401101_13_dialog_content = "Oh ya! Karena dia saya terinspirasi untuk menjadi kurir!",
  ui_story_5040_50401101_14_dialog_content = "Saya tahu secara langsung betapa sulitnya orang yang tinggal di tempat terpencil untuk terhubung dengan dunia luar, jadi saya ingin menjadi jembatan bagi orang lain ke luar.",
  ui_story_5040_50401101_15_dialog_content = "Itu luar biasa!",
  ui_story_5040_50401101_16_dialog_content = "Hehe, saya masih memiliki ruang untuk perbaikan.",
  ui_story_5040_50401101_17_dialog_content = "Bahkan dengan semua catatan yang diberikan Emerald kepadaku, aku masih mengacaukan segalanya...",
  ui_story_5040_50401101_18_dialog_content = "Meskipun saya mengikuti semua saran dalam catatannya dengan tepat, hal-hal entah bagaimana selalu berubah menjadi berbeda dari harapan saya.",
  ui_story_5040_50401101_19_dialog_content = "Anda tidak perlu selalu mengikuti arahan seperti itu ke tee. Terkadang, perlu berimprovisasi dan beradaptasi dengan situasi.",
  ui_story_5040_50401101_20_dialog_content = "Eh, aku tidak pandai dalam hal itu.",
  ui_story_5040_50401101_21_dialog_content = "Graaoooooohhh!!",
  ui_story_5040_50401101_22_dialog_content = "Apakah Anda mendengar itu? Sesuatu di kejauhan?",
  ui_story_5040_50401101_23_dialog_content = "Itu…?",
  ui_story_5040_50401101_24_dialog_content = "Graah! Groar!",
  ui_story_5040_50401101_25_dialog_content = "Gerhana! Semuanya, hati-hati!",
  ui_story_5040_50401101_26_dialog_content = "Begitu banyak dari mereka!",
  ui_story_5040_50401101_27_dialog_content = "Dari mana mereka semua berasal kali ini ?!",
  ui_story_5040_50401101_28_dialog_content = "Grup lain? Betapa anehnya...",
  ui_story_5040_50401101_29_dialog_content = "Mari kita berurusan dengan mereka terlebih dahulu. Semoga beruntung dan hati-hati.",
  ui_story_5040_50401102_1_dialog_content = "Graaahh—",
  ui_story_5040_50401102_2_dialog_content = "Aneh, mereka biasanya tidak menyerah begitu saja. Padahal mereka lari begitu saja...",
  ui_story_5040_50401102_3_dialog_content = "Ini bukan area di mana Eclipsites biasanya muncul.",
  ui_story_5040_50401102_4_dialog_content = "Tapi ini adalah kelompok kedua yang kami temui dalam beberapa hari terakhir. Itu tidak normal.",
  ui_story_5040_50401102_5_dialog_content = "Mereka... berlari...",
  ui_story_5040_50401102_6_dialog_content = "Apa katamu?",
  ui_story_5040_50401102_7_dialog_content = "Sable berkata mereka sepertinya melarikan diri, bersembunyi dari sesuatu?",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_5040_50401102_9_dialog_content = "Apakah tanah bergetar?",
  ui_story_5040_50401102_10_dialog_content = "Minggir, semuanya. Sesuatu akan datang!",
  ui_story_5040_50401102_11_dialog_content = "Awas, Tara!",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>Rooooaaaar!</size>",
  ui_story_5040_50401102_14_dialog_content = "Wow!! A-Apa itu benar-benar cacing pasir merah muda?!",
  ui_story_5040_50401102_15_dialog_content = "Saya pikir itu seharusnya menuju ke bagian gurun yang lebih dalam! Itu, uh, cukup jauh dari sini!",
  ui_story_5040_50401102_16_dialog_content = "Ada satu penjelasan lain untuk kemunculannya... Mungkin waktu makan.",
  ui_story_5040_50401102_17_dialog_content = "Maksudmu dia mencoba memakan Eclipsites itu?",
  ui_story_5040_50401102_18_dialog_content = "Ya... dan sepertinya sekarang kita ada di menu.",
  ui_story_5040_50401102_19_dialog_content = "<size=50>Roooaar!</size>",
  ui_story_5040_50401102_20_dialog_content = "Mengapa terburu-buru, pria besar?",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5040_50401102_22_dialog_content = "Itu adalah beberapa baju besi!",
  ui_story_5040_50401102_23_dialog_content = "Heheh... Kurasa sisik merah muda itu jauh lebih kuat dari kelihatannya.",
  ui_story_5040_50401102_24_dialog_content = "Tapi bagaimanapun juga, itu tetap saja cacing pasir.",
  ui_story_5040_50401102_25_dialog_content = "Pergi, Pembicara!",
  ui_story_5040_50401102_26_dialog_content = "Roaar—",
  ui_story_5040_50401102_27_dialog_content = "Lihat, ini berhasil!",
  ui_story_5040_50401102_28_dialog_content = "Aku akan membantu juga!",
  ui_story_5040_50401102_29_dialog_content = "Tunggu, Tara! Jangan terlalu dekat dengannya!",
  ui_story_5040_50401102_30_dialog_content = "Peluruku tidak akan menembus sisik cacing pasir ini jika aku terlalu jauh.",
  ui_story_5040_50401102_31_dialog_content = "Selain itu, tidak ada yang perlu ditakuti. Merah muda atau tidak, itu hanya cacing pasir!",
  ui_story_5040_50401102_32_dialog_content = "Rrr... Gemuruh...!",
  ui_story_5040_50401102_33_dialog_content = "Selanjutnya... headshot!",
  ui_story_5040_50401102_34_dialog_content = "Groar!",
  ui_story_5040_50401102_35_dialog_content = "Hah?!",
  ui_story_5040_50401102_36_dialog_content = "I-Itu punya pistol Tara! Apakah itu melakukan itu dengan sengaja ?!",
  ui_story_5040_50401102_37_dialog_content = "Berangkat!",
  ui_story_5040_50401102_38_dialog_content = "Bagaimana mungkin cacing pasir memiliki kesadaran seperti ini? Ada yang salah...",
  ui_story_5040_50401102_39_dialog_content = "Kita tidak akan bisa mengalahkannya dengan cepat. Tidak dengan kekuatan kita saat ini.",
  ui_story_5040_50401102_40_dialog_content = "Itu mencoba melemahkan kita dengan menyeret keluar pertarungan!",
  ui_story_5040_50401102_41_dialog_content = "Kita tidak bisa membiarkan itu terjadi. Grimoire, lepaskan kekuatanmu!",
  ui_story_5040_50401102_42_dialog_content = "Mengaum-!",
  ui_story_5040_50401102_43_dialog_content = "Ke-kemana perginya?!",
  ui_story_5040_50401102_44_dialog_content = "Itu menggali di bawah pasir! Perhatikan langkahmu!",
  ui_story_5040_50401102_45_dialog_content = "<size=50>Roooooarrr!!!</size>",
  ui_story_5040_50401102_46_dialog_content = "<color=#e8d9bb>Whoosh — Banting!</color>",
  ui_story_5040_50401102_47_dialog_content = "Ah—!",
  ui_story_5040_50401102_48_dialog_content = "Itu melemparkan Tara ke bukit pasir di sana!",
  ui_story_5040_50401102_49_dialog_content = "Tara!!!",
  ui_story_5040_50401102_50_dialog_content = "Aku tak apa-apa!",
  ui_story_5040_50401102_51_dialog_content = "Pasir di sini lepas; itu digunakan untuk menggali dan menyergap kita.",
  ui_story_5040_50401102_52_dialog_content = "Semua orang ke dalam mobil!",
  ui_story_5040_50401102_53_dialog_content = "Ada bagian gurun yang sebagian besar tanahnya berupa batu. Jika kita bisa kesana, cacing pasir tidak akan bisa menyergap kita!",
  ui_story_5040_50401102_54_dialog_content = "Mengerti! Ayo Sable, ayo ke mobil!",
  ui_story_5040_50401102_55_dialog_content = "Kami mundur, Adonis!",
  ui_story_5040_50401102_56_dialog_content = "Punya—Awas, Tara!",
  ui_story_5040_50401102_57_dialog_content = "Roaar—",
  ui_story_5040_50401102_58_dialog_content = "Urgh—!",
  ui_story_5040_50401102_59_dialog_content = "Tara!!",
  ui_story_5040_50401102_60_dialog_content = "Aduh...",
  ui_story_5040_50401102_61_dialog_content = "Oh tidak, kaki Tara terluka!",
  ui_story_5040_50401102_62_dialog_content = "Groar!",
  ui_story_5040_50401102_63_dialog_content = "(Drat, kita tidak akan berhasil. Bagaimana saya bisa menghentikannya...)",
  ui_story_5040_50401102_64_dialog_content = "Tinggalkan Tara, dasar ulat jelek dan gendut!",
  ui_story_5040_50401102_65_dialog_content = "Roaar—",
  ui_story_5040_50401102_66_dialog_content = "Di sini, kamu belatung yang terlalu besar! Temui aku!",
  ui_story_5040_50401102_67_dialog_content = "Adonis menarik perhatian cacing pasir!",
  ui_story_5040_50401102_68_dialog_content = "Aku tidak percaya serangan lemahnya berhasil!",
  ui_story_5040_50401102_69_dialog_content = "Perhatikan baik-baik tempat Adonis terkena cacing pasir... Kurasa itu luka yang belum sembuh total.",
  ui_story_5040_50401102_70_dialog_content = "Itu pasti dari pertarungannya dengan Sinsa dan yang lainnya!",
  ui_story_5040_50401102_71_dialog_content = "Groar!",
  ui_story_5040_50401102_72_dialog_content = "Astaga!!!",
  ui_story_5040_50401102_73_dialog_content = "Cacing pasir mengejar Adonis sekarang, dia menjauh dari Tara!",
  ui_story_5040_50401102_74_dialog_content = "Sekarang kesempatanmu, Jeriah!",
  ui_story_5040_50401102_75_dialog_content = "Hehehe... Aku tahu.",
  ui_story_5040_50401102_76_dialog_content = "Terbang, Elang! Bertujuan untuk luka itu!",
  ui_story_5040_50401102_77_dialog_content = "Mengaum? Roaaarrrr!",
  ui_story_5040_50401102_78_dialog_content = "Sekarang!",
  ui_story_5040_50401102_79_dialog_content = "Apakah kamu baik-baik saja, Tara?",
  ui_story_5040_50401102_80_dialog_content = "Saya baik-baik saja! Ayo bantu Adonis!",
  ui_story_5040_50401102_81_dialog_content = "Baik!",
  ui_story_5040_50401102_82_dialog_content = "Aku akan... membantu... juga!",
  ui_story_5040_50401102_83_dialog_content = "<color=#e8d9bb>Jagoan-!</color>",
  ui_story_5040_50401102_84_dialog_content = "Roooooarrr!!!",
  ui_story_5040_50401102_85_dialog_content = "Aku... aku selamat!",
  ui_story_5040_50401102_86_dialog_content = "Dapatkan di belakang kami, dan jangan kehilangan pijakan Anda!",
  ui_story_5040_50401102_87_dialog_content = "Groar!",
  ui_story_5040_50401102_88_dialog_content = "<color=#e8d9bb>Fwooosh!!!</color>",
  ui_story_5040_50401102_89_dialog_content = "Wah! Dari mana datangnya badai pasir ini?!",
  ui_story_5040_50401102_90_dialog_content = "Ini bukan badai pasir. Cacing pasir melemparkan pasir ke udara.",
  ui_story_5040_50401102_91_dialog_content = "Dia mencoba melindungi titik lemahnya dengan mengaburkan pandangan kita!",
  ui_story_5040_50401102_92_dialog_content = "Oh tidak... aku kehilangan Kya dan yang lainnya!",
  ui_story_5040_50401102_93_dialog_content = "Tara! Kamu ada di mana?!",
  ui_story_5040_50401102_94_dialog_content = "Di sini!",
  ui_story_5040_50401102_95_dialog_content = "Kami menuju ke sana!",
  ui_story_5040_50401102_96_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_5040_50401102_97_dialog_content = "Ahhh!!!",
  ui_story_5040_50401102_98_dialog_content = "A-Adonis?!",
  ui_story_5040_50401102_99_dialog_content = "Aku akan pergi membawa mereka kembali!",
  ui_story_5040_50401102_100_dialog_content = "<size=50>Groooaaar!!!</size>",
  ui_story_5040_50401102_101_dialog_content = "Hah?!",
  ui_story_5040_50401102_102_dialog_content = "Jeriah, itu semakin jauh!",
  ui_story_5040_50401102_103_dialog_content = "Tidak di jam tangan saya!",
  ui_story_5040_50401102_104_dialog_content = "<size=50>Roooooarrr!!!</size>",
  ui_story_5040_50401102_105_dialog_content = "Ugh!!!",
  ui_story_5040_50401102_106_dialog_content = "PlayerName!!!",
  ui_story_5040_50401102_107_dialog_content = "Aduh...",
  ui_story_5040_50401201_1_dialog_content = "Jepret dari itu, PlayerName!",
  ui_story_5040_50401201_2_dialog_content = "Aduh... Kepalaku...",
  ui_story_5040_50401201_3_dialog_content = "*Sputtering* Ugh, mulutku penuh dengan pasir!",
  ui_story_5040_50401201_4_dialog_content = "Fiuh... Syukurlah kau baik-baik saja. Apakah Anda terluka di mana saja?",
  ui_story_5040_50401201_5_dialog_content = "* Batuk * Tidak, saya pikir saya baik-baik saja. Kepalaku hanya sakit, itu saja...",
  ui_story_5040_50401201_6_dialog_content = "Cacing pasir mengirimmu terbang lebih dulu ke bukit pasir... Saat aku melihat tubuhmu yang setengah terkubur mencuat dari pasir, kupikir kau terluka parah.",
  ui_story_5040_50401201_7_dialog_content = "Tidak mudah bagi Tara dan aku untuk menarikmu keluar, Caelestite kecil... kau harus berterima kasih pada kami.",
  ui_story_5040_50401201_8_dialog_content = "T-Terima kasih...",
  ui_story_5040_50401201_9_dialog_content = "Tunggu, dimana yang lainnya? Apakah mereka baik-baik saja?",
  ui_story_5040_50401201_10_dialog_content = "Kami berlari untuk membantu Anda segera setelah kami melihat kaki Anda menyembul dari pasir.",
  ui_story_5040_50401201_11_dialog_content = "Berkat badai pasir yang ganas itu, kami kehilangan cacing pasir dan terpisah dari Adonis dan yang lainnya.",
  ui_story_5040_50401201_12_dialog_content = "Saya akan mencoba menemukan mereka dengan kekuatan saya!",
  ui_story_5040_50401201_13_option_content = "Mindlink!",
  ui_story_5040_50401201_14_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401201_15_dialog_content = "Saya tidak merasakan jejak mereka di dekatnya ...",
  ui_story_5040_50401201_16_dialog_content = "Tidak apa-apa. Pembicara saya sedang mencari mereka saat kita berbicara. Kecuali jika mereka mendapat masalah, kita akan segera mendengar kabar dari mereka.",
  ui_story_5040_50401201_17_dialog_content = "Bahkan jika mereka terkubur di bawah tanah, Elang dapat mendeteksi gerakan sekecil apa pun di permukaan pasir dan menemukannya.",
  ui_story_5040_50401201_18_dialog_content = "Adonis... Harap baik-baik saja...",
  ui_story_5040_50401201_19_dialog_content = "Shree—!",
  ui_story_5040_50401201_20_dialog_content = "Burung saya punya berita untuk kita.",
  ui_story_5040_50401201_21_dialog_content = "Dengan baik? Apakah Anda menemukan mereka?",
  ui_story_5040_50401201_22_dialog_content = "Shree—",
  ui_story_5040_50401201_23_dialog_content = "... Tidak ada tanda-tanda mereka sama sekali?",
  ui_story_5040_50401201_24_dialog_content = "Coba lagi, dan perluas radius pencarian Anda kali ini. Jangan khawatir tentang berapa banyak Lumina yang akan dikeluarkannya.",
  ui_story_5040_50401201_25_dialog_content = "Pergilah!",
  ui_story_5040_50401201_26_dialog_content = "Shree—!",
  ui_story_5040_50401201_27_dialog_content = "Aku akan melihat-lihat juga.",
  ui_story_5040_50401201_28_dialog_content = "Tapi kakimu masih sakit!",
  ui_story_5040_50401201_29_dialog_content = "Saya tidak bisa hanya duduk di sini dan tidak melakukan apa-apa!",
  ui_story_5040_50401201_30_dialog_content = "Anda hanya akan membuang-buang energi Anda. Jika mata elang tidak bisa melihat sesuatu dari udara, apa yang membuat Anda berpikir bahwa mata Anda bisa lebih baik?",
  ui_story_5040_50401201_31_dialog_content = "Pilihan terbaik Anda adalah beristirahat di sini, agar tidak memperparah cedera Anda.",
  ui_story_5040_50401201_32_dialog_content = "...",
  ui_story_5040_50401201_33_dialog_content = "Jika bukan karena aku berpura-pura hilang ingatan, Adonis tidak akan berada dalam kekacauan ini, bukan?",
  ui_story_5040_50401201_34_dialog_content = "... Sejujurnya, aku mengetahuinya sejak lama melalui kemampuanku bahwa kau berpura-pura.",
  ui_story_5040_50401201_35_dialog_content = "Hanya saja saya pikir Anda punya alasan, jadi saya tidak ingin ikut campur.",
  ui_story_5040_50401201_36_dialog_content = "Ya…",
  ui_story_5040_50401201_37_dialog_content = "Tapi kalau dipikir-pikir, membiarkanmu melakukan apa yang kamu mau akhirnya menempatkan kita semua dalam bahaya!",
  ui_story_5040_50401201_38_dialog_content = "Apa sih yang kamu pikirkan? Bagaimana Anda bisa melakukan ini pada semua orang ?!",
  ui_story_5040_50401201_39_dialog_content = "Kupikir... Kupikir itu akan membantu Adonis mengatasi rasa takutnya terhadap dunia luar.",
  ui_story_5040_50401201_40_dialog_content = "Dia selalu enggan meninggalkan kehidupannya di Northland... Jadi saya berharap uji coba ini akan memberinya dorongan yang dia butuhkan.",
  ui_story_5040_50401201_41_option_content = "Itu benar-benar gila!",
  ui_story_5040_50401201_42_dialog_content = "Jangan pedulikan kita semua. Bukankah Adonis adalah orang yang paling berarti untukmu?",
  ui_story_5040_50401201_43_dialog_content = "Apa gunanya menyelesaikan semua cobaan ini, jika itu berarti membahayakan pria yang Anda cintai?!",
  ui_story_5040_50401201_44_dialog_content = "Sekarang dia tidak bisa ditemukan, bersama dengan Kya dan Sable! Ini bukan lelucon, Tara!",
  ui_story_5040_50401201_45_dialog_content = "Maaf…",
  ui_story_5040_50401201_46_option_content = "... Aku tahu dari mana asalmu.",
  ui_story_5040_50401201_47_dialog_content = "Terkadang, ketika saya tidak cukup berani untuk melakukan sesuatu, saya membutuhkan orang lain untuk mendorong saya maju.",
  ui_story_5040_50401201_48_dialog_content = "Hati Anda berada di tempat yang tepat, tetapi saya tidak bisa mengatakan saya setuju dengan metode Anda.",
  ui_story_5040_50401201_49_dialog_content = "Jika orang yang Anda sayangi tidak cukup berani untuk menghadapi tantangan, Anda harus mendukungnya.",
  ui_story_5040_50401201_50_dialog_content = "Anda seharusnya menggunakan kata-kata dan tindakan Anda untuk membantu mereka menemukan keberanian dan menghadapi tantangan itu bersama.",
  ui_story_5040_50401201_51_dialog_content = "Aku salah... Maafkan aku. Aku seharusnya tidak begitu ceroboh...",
  ui_story_5040_50401201_52_dialog_content = "Saya pikir cacing pasir merah muda akan sama seperti cacing pasir lainnya, hanya warnanya yang berbeda.",
  ui_story_5040_50401201_53_dialog_content = "Saya telah berurusan dengan banyak cacing pasir biasa sebelumnya tanpa hambatan. Kupikir aku bisa melindungi Adonis sendirian.",
  ui_story_5040_50401201_54_dialog_content = "Aku tidak tahu benda itu akan sangat licik dan kuat...",
  ui_story_5040_50401201_55_dialog_content = "Saya sebagian harus disalahkan untuk ini.",
  ui_story_5040_50401201_56_dialog_content = "Saya seharusnya menyadari bahwa agar cacing pasir yang istimewa dapat bertahan dari kenyataan pahit gurun begitu lama, ia pasti jauh lebih ulet daripada yang lain.",
  ui_story_5040_50401201_57_dialog_content = "Pada akhirnya, akulah yang mempresentasikan uji coba ini, menempatkan semua orang dalam bahaya. Saya akan bertanggung jawab untuk itu, dan melakukan semua yang saya bisa untuk menyelamatkan mereka.",
  ui_story_5040_50401201_58_dialog_content = "Huh, coba cari yang lain dulu.",
  ui_story_5040_50401201_59_dialog_content = "semoga mereka selamat...",
  ui_story_5040_50401201_60_dialog_content = "(Ini mengkhawatirkan...)",
  ui_story_5040_50401201_61_dialog_content = "(Apa yang harus kita lakukan jika Pembicara Jeriah tidak dapat menemukan mereka...?)",
  ui_story_5040_50401201_62_dialog_content = "Burungku kembali.",
  ui_story_5040_50401201_63_dialog_content = "Hah? Di mana?",
  ui_story_5040_50401201_64_dialog_content = "Elang, ke sini!",
  ui_story_5040_50401201_65_dialog_content = "Kree—!",
  ui_story_5040_50401201_66_dialog_content = "Graaah...",
  ui_story_5040_50401201_67_dialog_content = "Dan sepertinya membawa sesuatu yang ekstra...",
  ui_story_5040_50401201_68_dialog_content = "Mari kita urus dulu Eclipsites ini!",
  ui_story_5040_50401201_69_dialog_content = "Biarkan saya membantu. Goresan seperti ini... bukan apa-apa bagi seseorang yang dibesarkan di Gurun Rediesel!",
  ui_story_5040_50401202_1_dialog_content = "*Uhuk uhuk*",
  ui_story_5040_50401202_2_dialog_content = "Astaga, aku tidak menyangka akan merasa sangat lelah.",
  ui_story_5040_50401202_3_dialog_content = "Apakah menurut Anda Eclipsites itu melarikan diri dari cacing pasir?",
  ui_story_5040_50401202_4_dialog_content = "Tidak, mereka sepertinya tidak panik atau mencari perlindungan...",
  ui_story_5040_50401202_5_dialog_content = "Mungkin mereka memperhatikan berapa banyak yang dihabiskan Lumina Hawk untuk mencari yang lain, dan melihat peluang sempurna untuk menyergap kita?",
  ui_story_5040_50401202_6_dialog_content = "Sekarang, burung kecilku... Apa kau menemukan sesuatu?",
  ui_story_5040_50401202_7_dialog_content = "Shree!",
  ui_story_5040_50401202_8_dialog_content = "Tetap tidak ada...?",
  ui_story_5040_50401202_9_dialog_content = "Tidak ada tanda-tanda cacing pasir di dekat sini. Kemungkinan besar bergerak menggunakan terowongan bawah tanah yang dibuat sebelumnya.",
  ui_story_5040_50401202_10_dialog_content = "Jika itu masalahnya, maka kemungkinan besar itu juga membawa Adonis, Kya, dan Sable bersamanya...",
  ui_story_5040_50401202_11_dialog_content = "Itu berarti mereka dalam bahaya serius!",
  ui_story_5040_50401202_12_dialog_content = "Tidak mungkin ketiganya bisa menangani cacing pasir itu sendirian! Belum lagi mereka bisa tersesat di terowongan itu!",
  ui_story_5040_50401202_13_dialog_content = "Kita harus segera menemukan mereka!",
  ui_story_5040_50401202_14_dialog_content = "Jangan khawatir. Saya bisa memberdayakan Hawk untuk mencari di seluruh gurun.",
  ui_story_5040_50401202_15_dialog_content = "Haw—*Batuk*—Hawk!",
  ui_story_5040_50401202_16_dialog_content = "Hentikan, Jeriah!",
  ui_story_5040_50401202_17_dialog_content = "Anda terlihat sangat pucat, Anda jelas berada di batas kemampuan Anda!",
  ui_story_5040_50401202_18_dialog_content = "Heheh... Jangan remehkan aku Caelestite kecil. Aku hampir tidak sehalus itu.",
  ui_story_5040_50401202_19_dialog_content = "Setelah bertahun-tahun, saya telah berhasil mengatasi setiap masalah sendiri.",
  ui_story_5040_50401202_20_dialog_content = "Kali ini tidak akan ada perbedaan—",
  ui_story_5040_50401202_21_dialog_content = "Kita harus meminta bantuan Rediesel Wrench.",
  ui_story_5040_50401202_22_dialog_content = "Apa?",
  ui_story_5040_50401202_23_dialog_content = "Mari kembali ke Soroz. Saya akan menggunakan komunikator untuk menghubungi Sinsa dan Rediesel Wrench lainnya, sehingga mereka dapat membantu kami mencari.",
  ui_story_5040_50401202_24_dialog_content = "Jika kita tidak bisa menemukan mereka hanya dengan kita bertiga, maka kita hanya perlu mengerahkan semua orang di seluruh gurun!",
  ui_story_5040_50401202_25_dialog_content = "Anda adalah anggota senior Serikat Kurir! Saya yakin semua orang akan bersedia membantu jika seseorang dengan status Anda memintanya!",
  ui_story_5040_50401202_26_dialog_content = "\"Seseorang dengan statusku\"? Betapa naifnya dirimu, hehe...",
  ui_story_5040_50401202_27_dialog_content = "Saya selalu menjadi seorang profesional. Saya tidak membantu orang lain, dan saya tidak mengharapkan bantuan dari orang lain.",
  ui_story_5040_50401202_28_dialog_content = "Selain itu, saya yakin mereka akan jauh lebih bahagia dengan kurir lain yang jauh lebih bertanggung jawab.",
  ui_story_5040_50401202_29_dialog_content = "Kamu bukan seseorang yang bisa diganti begitu saja!",
  ui_story_5040_50401202_30_dialog_content = "Semua orang di Gurun Rediesel tahu bahwa kurir adalah jembatan yang menghubungkan kita semua!",
  ui_story_5040_50401202_31_dialog_content = "Courier Union adalah satu-satunya alasan Adonis dan aku bisa tetap berhubungan selama ini!",
  ui_story_5040_50401202_32_dialog_content = "Itu benar. Hubungan antar manusia tidak pernah sesederhana itu, Jeriah.",
  ui_story_5040_50401202_33_dialog_content = "Dengan mengirimkan surat semua orang, saya yakin Anda telah menjalin hubungan dengan orang-orang yang berjalan lebih dalam dari yang Anda sadari.",
  ui_story_5040_50401202_34_dialog_content = "...",
  ui_story_5040_50401202_35_dialog_content = "Apa yang harus aku lakukan dengan kalian berdua...",
  ui_story_5040_50401202_36_dialog_content = "Bagus. Kami akan melakukannya dengan cara Anda, dan meminta bantuan.",
  ui_story_5040_50401202_37_dialog_content = "Tapi jangan terlalu berharap. Rediesel Wrench mungkin tidak ingin membantu seseorang yang hanya memikirkannya saat dalam masalah.",
  ui_story_5040_50401202_38_dialog_content = "Kita tidak akan pernah tahu kecuali kita mencobanya, bukan?",
  ui_story_5040_50401202_39_dialog_content = "Mari kita kembali ke Soroz!",
  ui_story_5040_50401202_40_dialog_content = "Jangan terlalu terburu-buru. Saya dapat menjangkau mereka lebih cepat daripada komunikator Anda.",
  ui_story_5040_50401202_41_dialog_content = "Hah?",
  ui_story_5040_50401202_42_dialog_content = "Itu adalah bakat saya, yang akan menghabiskan hampir seluruh Lumina saya. Setelah saya menggunakannya, saya tidak akan dapat melakukannya lagi untuk waktu yang lama...",
  ui_story_5040_50401202_43_dialog_content = "tapi saya percaya sekarang adalah waktu yang tepat untuk menggunakannya.",
  ui_story_5040_50401202_44_dialog_content = "Tunggu, apakah Anda memberi tahu saya bahwa Anda memiliki semacam serangan pamungkas?",
  ui_story_5040_50401202_45_dialog_content = "Bukan serangan, bukan.",
  ui_story_5040_50401202_46_dialog_content = "Yang dilakukannya hanyalah membiarkan saya dengan cepat membuat koneksi dengan birdie Courier Union kecil saya, jadi ini dimaksudkan hanya untuk keadaan darurat.",
  ui_story_5040_50401202_47_dialog_content = "Dengan mengaktifkan skill ini, saya bisa menggunakan Hawk untuk meminta bantuan mereka. Dengan cara ini, kami dapat menjangkau setiap anggota Rediesel Wrench di area tersebut.",
  ui_story_5040_50401202_48_dialog_content = "Pernahkah Anda melakukannya sebelumnya?",
  ui_story_5040_50401202_49_dialog_content = "Tidak! Ini adalah usaha pertama saya.",
  ui_story_5040_50401202_50_dialog_content = "Ayo, burung kecilku yang manis! Bawalah pesan saya kepada semua orang yang mau mendengarkan!",
  ui_story_5040_50401202_51_dialog_content = "Shree!",
  ui_story_5040_50401202_52_dialog_content = "Pergilah!",
  ui_story_5040_50401202_53_dialog_content = "Shree—!",
  ui_story_5040_50401202_54_dialog_content = "Pulanglah dengan kabar baik, burung kecilku yang cantik...",
  ui_story_5040_50401202_55_dialog_content = "<color=#e8d9bb>Beberapa menit kemudian…</color>",
  ui_story_5040_50401202_56_dialog_content = "Masih tidak ada respon...",
  ui_story_5040_50401202_57_dialog_content = "Hawk mungkin cepat, tapi masih butuh waktu untuk menyampaikan pesanku. Bersabarlah.",
  ui_story_5040_50401202_58_dialog_content = "... Lihat! Itu ada!",
  ui_story_5040_50401202_59_dialog_content = "Ya! Itu Elang Jeriah...",
  ui_story_5040_50401202_60_dialog_content = "Shree—!",
  ui_story_5040_50401202_61_dialog_content = "Sepertinya dia membawa sesuatu di cakarnya... L-Awas! Itu menjatuhkan barang pada kita!",
  ui_story_5040_50401202_62_dialog_content = "Apakah ini ... huruf?",
  ui_story_5040_50401202_63_dialog_content = "Mereka! Lihat semua surat ini, jatuh dari langit seperti salju...",
  ui_story_5040_50401202_64_dialog_content = "Ada begitu banyak dari mereka. Saya pikir ada catatan di dalamnya.",
  ui_story_5040_50401202_65_dialog_content = "Wah, apa artinya ini? Saya tidak bisa membuat kepala atau ekor ini!",
  ui_story_5040_50401202_66_dialog_content = "Biarku lihat.",
  ui_story_5040_50401202_67_dialog_content = "Oh, itu hanya pesan kode dari Rediesel Wrench. Dikatakan bahwa tidak ada yang pernah melihat teman kita atau cacing pasir itu di bagian barat laut gurun.",
  ui_story_5040_50401202_68_dialog_content = "Tidak semua orang di Rediesel Wrench dapat membaca atau menulis, jadi kami sering menggunakan pesan seperti ini untuk berkomunikasi.",
  ui_story_5040_50401202_69_dialog_content = "Itu benar-benar berhasil ...",
  ui_story_5040_50401202_70_dialog_content = "Shree!",
  ui_story_5040_50401202_71_dialog_content = "Apakah Anda memberi tahu saya bahwa surat-surat ini mencakup setiap lokasi di mana Rediesel Wrench menemukan cacing pasir merah muda?!",
  ui_story_5040_50401202_72_dialog_content = "Jadi kalau kita mengikuti catatan mereka, seharusnya kita bisa menemukan sandworm dan teman-teman kita, kan?",
  ui_story_5040_50401202_73_dialog_content = "Oke…",
  ui_story_5040_50401202_74_dialog_content = "Jadi apa yang kita tunggu? Mari kita mulai melalui surat-surat ini!",
  ui_story_5040_50401202_75_dialog_content = "Tidak ada apa pun di dekat Tail Street atau Red-Eye Gorge.",
  ui_story_5040_50401202_76_dialog_content = "Tidak ada yang mengarah ke Federasi Illumina juga... Hmm?",
  ui_story_5040_50401202_77_dialog_content = "Aha! Menemukan Anda!",
  ui_story_5040_50401202_78_dialog_content = "Di mana?!",
  ui_story_5040_50401202_79_dialog_content = "Jauh ke selatan, dekat sebuah oasis jauh di dalam gurun.",
  ui_story_5040_50401202_80_dialog_content = "Tempat itu penuh dengan cacing pasir, dan Rediesel Wrench sesekali pergi ke sana untuk memburu mereka.",
  ui_story_5040_50401202_81_dialog_content = "Rupanya, salah satu anggota mereka melihat cacing pasir merah muda muncul dari tanah belum lama ini!",
  ui_story_5040_50401202_82_dialog_content = "Kalau begitu ayo berangkat! Jika kita cepat, kita mungkin bisa melacak Adonis!",
  ui_story_5040_50401202_83_dialog_content = "Masuklah!",
  ui_story_5040_50401202_84_dialog_content = "<color=#e8d9bb>Vroom—</color>",
  ui_story_5040_50401202_85_dialog_content = "Bwaaah!!!",
  ui_story_5040_50401202_86_dialog_content = "JJ-Jeriah! Pelan sedikit!!",
  ui_story_5040_50401202_87_dialog_content = "<size=45>Apa itu tadi?</size>",
  ui_story_5040_50401202_88_dialog_content = "<size=45>Aku tidak bisa mendengarmuuuuu!!</size>",
  ui_story_5040_50401202_89_option_content = "Pelan-pelan, Jeriaaaaah!!!",
  ui_story_5040_50401202_90_dialog_content = "Pelan - pelan? Kami tidak punya waktu untuk melambat! Nyawa dipertaruhkan!",
  ui_story_5040_50401202_91_option_content = "Jangan melewati speeeeed limiiiiiit!!!!",
  ui_story_5040_50401202_92_dialog_content = "Ha ha ha! Anda memiliki selera humor yang tinggi, Anda tahu!",
  ui_story_5040_50401202_93_dialog_content = "Batas kecepatan? Di gurun?",
  ui_story_5040_50401202_94_dialog_content = "Graaaah—!",
  ui_story_5040_50401202_95_dialog_content = "Kami dikejar oleh Eclipsites!",
  ui_story_5040_50401202_96_dialog_content = "Maka kita hanya harus kehilangan mereka!",
  ui_story_5040_50401202_97_dialog_content = "Bertahanlah, Caelestite kecil! Kita akan pergi lebih cepat sekarang!",
  ui_story_5040_50401202_98_dialog_content = "<color=#e8d9bb>Vroooom—!!!</color>",
  ui_story_5040_50401301_1_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5040_50401301_2_dialog_content = "Ahhhhhhhh—!",
  ui_story_5040_50401301_3_dialog_content = "Itu indah!",
  ui_story_5040_50401301_4_dialog_content = "Anda mungkin dapat memberikan driver terbaik Rediesel Wrench untuk mendapatkan uang mereka!",
  ui_story_5040_50401301_5_dialog_content = "Ah, benarkah? Saya akan menganggap itu sebagai pujian.",
  ui_story_5040_50401301_6_dialog_content = "Saya tidak melihat tanda-tanda Eclipsites lagi... Saya pikir kita kehilangan mereka.",
  ui_story_5040_50401301_7_dialog_content = "Saya kira itu berarti saya bisa melepaskan gas sedikit sekarang.",
  ui_story_5040_50401301_8_dialog_content = "Fiuh...akhirnya selesai juga...",
  ui_story_5040_50401301_9_dialog_content = "Apakah kita hampir sampai?",
  ui_story_5040_50401301_10_dialog_content = "Tidak, kita masih agak jauh.",
  ui_story_5040_50401301_11_dialog_content = "Bukit pasir yang bergeser di Gurun Rediesel menyulitkan kebanyakan orang untuk mempertahankan arah.",
  ui_story_5040_50401301_12_dialog_content = "Tetapi dengan Anda yang memimpin, saya yakin kami akan baik-baik saja.",
  ui_story_5040_50401301_13_dialog_content = "Mengapa aku merasa pernah mendengar hal seperti ini sebelumnya...?",
  ui_story_5040_50401301_14_dialog_content = "Jangan khawatir, lakukan apa yang dia katakan, dan Anda akan baik-baik saja!",
  ui_story_5040_50401301_15_dialog_content = "Aku keberatan tentangmu kemarin, tapi kurasa aku bisa mempercayaimu sekarang.",
  ui_story_5040_50401301_16_dialog_content = "Ketika saya berbicara dengan Sinsa, dia berkata bahwa saya harus mempercayai Anda dengan sepenuh hati.",
  ui_story_5040_50401301_17_dialog_content = "Apakah itu yang dia katakan?",
  ui_story_5040_50401301_18_dialog_content = "Tentu saja, semua orang di Rediesel Wrench juga mempercayai Anda dan berterima kasih atas semua yang Anda lakukan.",
  ui_story_5040_50401301_19_dialog_content = "Itulah mengapa saya sangat terganggu ketika Anda kadang-kadang berbicara begitu buruk tentang mereka.",
  ui_story_5040_50401301_20_dialog_content = "Apakah begitu? Hehe terima kasih.",
  ui_story_5040_50401301_21_dialog_content = "Itu mengingatkanku, PlayerName... Saya harus minta maaf untuk kemarin.",
  ui_story_5040_50401301_22_dialog_content = "Hah? Kenapa sekarang, tiba-tiba?",
  ui_story_5040_50401301_23_dialog_content = "Ketika Anda bertanya kepada saya apakah kita harus meminta bantuan untuk mencari yang lain, saya agak menutup Anda.",
  ui_story_5040_50401301_24_dialog_content = "Oh itu? Saya tidak terlalu kesal, jujur saja ...",
  ui_story_5040_50401301_25_dialog_content = "Tapi aku tidak mengerti. Mengapa Anda sangat membenci Rediesel Wrench?",
  ui_story_5040_50401301_26_dialog_content = "Ya, saya pikir Anda mengenal mereka dengan baik, mengingat Anda lahir di sini.",
  ui_story_5040_50401301_27_dialog_content = "Apa salah satu orang tak berguna yang mengabaikan perintah Sinsa menjarah desamu?",
  ui_story_5040_50401301_28_dialog_content = "Tidak, tidak ada yang seperti itu... Sebaliknya, orang tua saya pernah menjadi anggota Rediesel Wrench, seperti saya.",
  ui_story_5040_50401301_29_dialog_content = "Tapi saya memutuskan hubungan dengan orang tua saya dan Rediesel Wrench sejak lama sekali.",
  ui_story_5040_50401301_30_dialog_content = "Tapi, kenapa?",
  ui_story_5040_50401301_31_dialog_content = "Apakah Anda biasanya ingin tahu tentang kehidupan pribadi orang lain, atau hanya saya?",
  ui_story_5040_50401301_32_dialog_content = "Aku minta maaf, aku tidak bermaksud membongkar! Tidak apa-apa jika Anda tidak ingin membicarakannya ...",
  ui_story_5040_50401301_33_dialog_content = "Heheh... Kamu benar-benar tidak bisa diajak bercanda ya?",
  ui_story_5040_50401301_34_dialog_content = "Itu bukan rahasia yang dalam dan gelap atau apa pun. Saya hanya tidak setuju dengan cara mereka melakukan sesuatu.",
  ui_story_5040_50401301_35_dialog_content = "Orang tua saya, seperti Rediesel Wrench lainnya, menghargai kebebasan di atas segalanya.",
  ui_story_5040_50401301_36_dialog_content = "Sepanjang yang bisa saya ingat, mereka tidak pernah merawat saya seperti orang tua normal. Yang mereka lakukan hanyalah mengajari saya beberapa keterampilan dasar bertahan hidup di gurun.",
  ui_story_5040_50401301_37_dialog_content = "Sisa waktu, mereka hanya meninggalkan saya ke perangkat saya sendiri.",
  ui_story_5040_50401301_38_dialog_content = "Sendirian?!",
  ui_story_5040_50401301_39_dialog_content = "Apakah sesulit itu untuk dibayangkan?",
  ui_story_5040_50401301_40_option_content = "Dia!",
  ui_story_5040_50401301_41_dialog_content = "Ya... Maksudku, meskipun aku terjebak di bawah tanah hampir sepanjang hidupku, setidaknya aku punya Soroz untuk menemaniku.",
  ui_story_5040_50401301_42_dialog_content = "Hari-hari terasa panjang dan membosankan, tetapi saya tidak pernah sendirian.",
  ui_story_5040_50401301_43_dialog_content = "Itulah mengapa agak sulit bagi saya untuk membayangkan kehidupan seperti itu...",
  ui_story_5040_50401301_44_dialog_content = "Harus kukatakan, aku tidak bisa tidak merasakan sedikit kecemburuan, Caelestite kecil.",
  ui_story_5040_50401301_45_dialog_content = "Soroz pasti merawatmu dengan baik, kurasa?",
  ui_story_5040_50401301_46_dialog_content = "Ya... Soroz selalu seperti keluarga bagiku.",
  ui_story_5040_50401301_47_option_content = "Tidak juga...",
  ui_story_5040_50401301_48_dialog_content = "Yah, aku menghabiskan tujuh belas tahun terjebak di bawah tanah, dengan hanya Soroz yang menemaniku...",
  ui_story_5040_50401301_49_dialog_content = "Soroz adalah mentor saya, dan satu-satunya keluarga yang saya miliki.",
  ui_story_5040_50401301_50_dialog_content = "Tanpa Soroz, saya rasa saya tidak akan bisa menjadi seperti sekarang ini.",
  ui_story_5040_50401301_51_dialog_content = "Begitu... Soroz pasti guru yang luar biasa.",
  ui_story_5040_50401301_52_dialog_content = "Sangat cocok!",
  ui_story_5040_50401301_53_dialog_content = "Anda beruntung, tetapi tidak semua orang bisa seberuntung Anda.",
  ui_story_5040_50401301_54_dialog_content = "Gurun ini begitu luas dan kosong, bahkan membuat jarak antara mereka yang tinggal di dalamnya menjadi lautan bukit pasir yang tak berujung.",
  ui_story_5040_50401301_55_dialog_content = "Mungkin karena orang tua saya sudah terbiasa dengan cara mereka yang lalai, mereka berharap saya bisa tumbuh mandiri tanpa perawatan mereka, sendirian.",
  ui_story_5040_50401301_56_dialog_content = "Bahkan ketika saya masih kecil, mereka lebih mementingkan hidup cepat dan bebas daripada merawat putri mereka sendiri.",
  ui_story_5040_50401301_57_dialog_content = "Pasti ada lebih dari sedikit orang seperti itu di Rediesel Wrench...",
  ui_story_5040_50401301_58_dialog_content = "Mereka terlalu bersemangat dalam hal keinginan mereka. Hanya berkat amal orang lain saya berhasil tumbuh dengan aman dan sehat.",
  ui_story_5040_50401301_59_dialog_content = "Semua orang di Rediesel Wrench selalu baik, tapi aku selalu cemburu pada anak-anak lain yang orang tuanya benar-benar merawat mereka.",
  ui_story_5040_50401301_60_dialog_content = "Saya iri bahwa mereka memiliki orang tua yang dapat mereka andalkan, bahwa mereka dapat menangis dan tertawa tanpa hambatan.",
  ui_story_5040_50401301_61_dialog_content = "Dan meskipun kehidupan di Rediesel Wrench selalu dipenuhi dengan kebisingan dan aksi, saya tidak pernah memiliki ruang pribadi, selalu dikelilingi oleh orang-orang.",
  ui_story_5040_50401301_62_dialog_content = "Keaktifan, lingkungan yang riuh; itu semua terlalu berat bagiku. Yang saya inginkan hanyalah berada di suatu tempat yang damai dan tenang.",
  ui_story_5040_50401301_63_dialog_content = "Jadi suatu hari, saya memutuskan sudah waktunya untuk meninggalkan semuanya. The Rediesel Wrench, orang tuaku... Aku tidak ingin menjadi salah satu dari mereka lagi.",
  ui_story_5040_50401301_64_dialog_content = "Saya hidup bebas seperti burung, karena tidak setia pada faksi apa pun, tidak berkomitmen pada siapa pun.",
  ui_story_5040_50401301_65_dialog_content = "Adapun Serikat Kurir, bekerja untuk mereka hanyalah alat untuk mencapai tujuan. Ini pekerjaan bagi saya, dan tidak lebih.",
  ui_story_5040_50401301_66_dialog_content = "Benarkah itu yang kamu rasakan...?",
  ui_story_5040_50401301_67_dialog_content = "Pertama kali saya menginjakkan kaki di kantor Anda, saya sangat terkejut melihat semua dekorasi itu.",
  ui_story_5040_50401301_68_dialog_content = "Mereka berserakan di mana-mana dan tertutup debu karena tidak dibersihkan selama bertahun-tahun.",
  ui_story_5040_50401301_69_dialog_content = "Asal tahu saja, Anda tidak dapat memiliki salah satu dari mereka. Hal-hal itu sangat berharga bagi saya.",
  ui_story_5040_50401301_70_dialog_content = "Saya sama sekali tidak tertarik pada mereka! Saya bukan tipe orang yang menginginkan apapun yang saya lihat!",
  ui_story_5040_50401301_71_dialog_content = "Yang akan saya katakan adalah bahwa meskipun Anda mengatakan Anda membutuhkannya ... Anda tidak terlalu peduli tentang mereka, bukan?",
  ui_story_5040_50401301_72_dialog_content = "...",
  ui_story_5040_50401301_73_dialog_content = "Tak satu pun dari hal-hal itu berasal dari Rediesel Desert, dan Anda menggunakannya untuk meyakinkan diri sendiri bahwa Anda bukan bagian dari Rediesel Wrench.",
  ui_story_5040_50401301_74_dialog_content = "Tetapi jika Anda tidak termasuk dalam Rediesel Wrench, lalu di mana Anda berada? Saya rasa Anda juga tidak tahu jawabannya.",
  ui_story_5040_50401301_75_dialog_content = "(Itu menjelaskan mengapa kantor Jeriah penuh dengan dekorasi berdebu...)",
  ui_story_5040_50401301_76_dialog_content = "(Mungkin dia hanya mencoba mengisi kekosongan di hatinya?)",
  ui_story_5040_50401301_77_dialog_content = "Katakan padaku, menurutmu orang seperti apa aku ini?",
  ui_story_5040_50401301_78_dialog_content = "Anda selalu bertingkah seolah-olah Anda begitu penuh teka-teki dan terpisah, tetapi pada akhirnya, Anda hanyalah seseorang yang diabaikan secara emosional hampir sepanjang hidup Anda.",
  ui_story_5040_50401301_79_dialog_content = "Itu sebabnya Anda menolak untuk mencintai siapa pun, dan menolak siapa pun yang mungkin peduli dengan Anda!",
  ui_story_5040_50401301_80_dialog_content = "Anda mengharapkan seseorang yang tidak pernah dicintai, seseorang yang bahkan tidak tahu apa itu cinta, untuk mencintai orang lain?",
  ui_story_5040_50401301_81_dialog_content = "A-aku tidak bermaksud seperti itu sama sekali...",
  ui_story_5040_50401301_82_dialog_content = "Katakan, Jeriah... bukankah menurutmu kau terlalu keras pada dirimu sendiri?",
  ui_story_5040_50401301_83_dialog_content = "Bagaimana maksudmu?",
  ui_story_5040_50401301_84_dialog_content = "Saya tidak percaya sedetik pun bahwa Anda tidak tahu apa itu cinta.",
  ui_story_5040_50401301_85_dialog_content = "Jika Anda benar-benar tidak tahu, Anda tidak akan berusaha keras untuk membantu Adonis dan Tara.",
  ui_story_5040_50401301_86_dialog_content = "Anda mengajari mereka cara menjual prangko saat kami berada di Lumopolis.",
  ui_story_5040_50401301_87_dialog_content = "Berkat kamu, mereka bisa membantu Tina, dan sebagai balasannya... Dia mengarahkan kita ke lab penelitian di Illumina.",
  ui_story_5040_50401301_88_dialog_content = "Dan meskipun Tara berbohong tentang kehilangan ingatannya, Anda tetap merahasiakannya dan tetap membantunya.",
  ui_story_5040_50401301_89_dialog_content = "Anda juga tidak ingin melihat hubungan mereka berantakan, bukan?",
  ui_story_5040_50401301_90_dialog_content = "...",
  ui_story_5040_50401301_91_dialog_content = "Saya baru saja menemukan mereka pasangan yang menarik. Tidak setiap hari dua orang dari ujung Astra yang berlawanan berakhir bersama.",
  ui_story_5040_50401301_92_dialog_content = "Ini sama penasarannya dengan seekor burung dan kelinci yang jatuh cinta.",
  ui_story_5040_50401301_93_dialog_content = "Anda tidak mendengar cerita seperti itu setiap hari, apalagi memiliki kesempatan untuk menyaksikannya terungkap, itulah sebabnya saya memutuskan untuk ikut dengan mereka.",
  ui_story_5040_50401301_94_dialog_content = "Maka Anda bisa saja duduk dan mengamati dalam diam.",
  ui_story_5040_50401301_95_dialog_content = "Tapi bukan itu yang terjadi, bukan? Nyatanya, Anda berkali-kali berusaha membantu mereka, baik Anda memilih untuk mengakuinya atau tidak.",
  ui_story_5040_50401301_96_dialog_content = "Anda mungkin tidak dicintai dengan sepenuh hati di masa lalu, tetapi seseorang sekuat dan mengesankan seperti Anda pasti akan bertemu dengan orang-orang yang akan mencintai Anda di masa depan.",
  ui_story_5040_50401301_97_dialog_content = "Benarkah...?",
  ui_story_5040_50401301_98_dialog_content = "Aku hanya seorang kurir yang menempel pada dirinya sendiri.",
  ui_story_5040_50401301_99_dialog_content = "Jangan meremehkan signifikansi Anda sendiri!",
  ui_story_5040_50401301_100_dialog_content = "Anda adalah seorang kurir, dan seseorang yang tidak dapat dilakukan oleh orang-orang di gurun!",
  ui_story_5040_50401301_101_dialog_content = "Anda jauh lebih penting daripada yang Anda tahu!",
  ui_story_5040_50401301_102_dialog_content = "…!",
  ui_story_5040_50401301_103_dialog_content = "Benar, Yeriah! Anda tidak tahu betapa pentingnya Anda bagi semua orang!",
  ui_story_5040_50401301_104_dialog_content = "Kehidupan di gurun itu brutal. Orang hanya bisa bertahan hidup di sini dengan mengandalkan satu sama lain, dan saling membantu!",
  ui_story_5040_50401301_105_dialog_content = "Setiap Aurorian di sini seperti perahu kecil yang mengapung di lautan pasir. Sendirian, kita mudah tersesat, atau bahkan terbalik...",
  ui_story_5040_50401301_106_dialog_content = "Tetapi ketika kita semua tetap bersatu, kita dapat menghadapi badai apa pun yang menghadang kita!",
  ui_story_5040_50401301_107_dialog_content = "Dan tidak ada orang di sini yang lebih baik dalam menjaga kita semua tetap terhubung daripada Persatuan Kurir Gurun Rediesel!",
  ui_story_5040_50401301_108_dialog_content = "...",
  ui_story_5040_50401301_109_dialog_content = "Heheheh... Kurasa aku akhirnya mengerti kenapa Adonis rela memberanikan diri untuk meninggalkan Northland.",
  ui_story_5040_50401301_110_dialog_content = "Apa?!",
  ui_story_5040_50401301_111_dialog_content = "Benar-benar? Mengapa?",
  ui_story_5040_50401301_112_dialog_content = "... Aku akan membiarkanmu memikirkannya sendiri, Caelestite kecil.",
  ui_story_5040_50401301_113_dialog_content = "Jangan terlalu kabur dan misterius!",
  ui_story_5040_50401301_114_dialog_content = "Sekarang bukan waktunya. Kami memiliki hal-hal yang lebih penting di tangan ...",
  ui_story_5040_50401301_115_dialog_content = "Mengaum-!!!",
  ui_story_5040_50401301_116_dialog_content = "Gerhana! Tapi dari mana mereka berasal!?",
  ui_story_5040_50401301_117_dialog_content = "Eclipsites diketahui berlindung di liang bawah tanah yang ditinggalkan oleh cacing pasir...",
  ui_story_5040_50401301_118_dialog_content = "Kami semakin dekat dengan tujuan kami.",
  ui_story_5040_50401301_119_dialog_content = "Baiklah! Ayo habisi semuanya sekaligus!",
  ui_story_5040_50401302_1_dialog_content = "<color=#e8d9bb>Pekik—!</color>",
  ui_story_5040_50401302_2_dialog_content = "Jadi ini oasis yang ditinggali cacing pasir?",
  ui_story_5040_50401302_3_dialog_content = "Ya. Tempat ini akan sempurna untuk pemukiman Aurorian jika bukan karena semua cacing pasir.",
  ui_story_5040_50401302_4_dialog_content = "Karena mereka, itu tetap tidak berpenghuni sama sekali.",
  ui_story_5040_50401302_5_dialog_content = "Mungkin lebih baik seperti ini, kau tahu? Lagi pula, lihat saja betapa indahnya di sini.",
  ui_story_5040_50401302_6_dialog_content = "Bagaimana jika saya memberi tahu Anda bahwa pasir di sekitar oasis ini berserakan dengan sisa-sisa Aurorian dan hewan yang menjadi korban cacing pasir?",
  ui_story_5040_50401302_7_dialog_content = "A-Apa?!",
  ui_story_5040_50401302_8_dialog_content = "Di padang pasir, semakin indah sesuatu, semakin besar kemungkinan ia memiliki sisi yang mengerikan.",
  ui_story_5040_50401302_9_dialog_content = "Jangan lengah hanya karena terlihat cantik. Ada berbagai macam bahaya yang bersembunyi tepat di bawah permukaan.",
  ui_story_5040_50401302_10_dialog_content = "G-mengerti...",
  ui_story_5040_50401302_11_dialog_content = "Ini aneh, meskipun. Saya tidak merasakan ada cacing pasir di dekatnya... tidak ada sisik yang terlihat.",
  ui_story_5040_50401302_12_dialog_content = "Mungkinkah mereka bermigrasi ke tempat lain?",
  ui_story_5040_50401302_13_dialog_content = "Ada kemungkinan lain.",
  ui_story_5040_50401302_14_dialog_content = "Cacing pasir merah muda bisa saja mengusir mereka untuk mengklaim oasis ini sebagai miliknya.",
  ui_story_5040_50401302_15_dialog_content = "Maka kita harus bergegas dan mencari tanda-tanda cacing pasir itu!",
  ui_story_5040_50401302_16_dialog_content = "Sepertinya aku harus menyusahkanmu lagi, Hawk.",
  ui_story_5040_50401302_17_dialog_content = "Shree!",
  ui_story_5040_50401302_18_dialog_content = "Saya akan menggunakan kemampuan psikis saya untuk mengintai juga!",
  ui_story_5040_50401302_19_option_content = "Force Boost!",
  ui_story_5040_50401302_20_dialog_content = "(Tolong, tunjukkan sesuatu... Jejak cacing pasir merah muda, petunjuk kehadiran teman-temanku... apa saja!)",
  ui_story_5040_50401302_21_dialog_content = "Tunggu, apakah itu...?",
  ui_story_5040_50401302_22_dialog_content = "Yeriah! Tara! Saya pikir saya baru saja merasakan Adonis dan Kya!",
  ui_story_5040_50401302_23_dialog_content = "Benar-benar? Kau bahkan lebih cepat dari Hawk...",
  ui_story_5040_50401302_24_dialog_content = "Di mana mereka?!",
  ui_story_5040_50401302_25_dialog_content = "Lewat sini!",
  ui_story_5040_50401302_26_dialog_content = "Apakah Anda yakin merasakannya? Tidak ada apa-apa di sini, kecuali beberapa semak...",
  ui_story_5040_50401302_27_dialog_content = "Kekuatanku belum berbohong padaku! Mereka ada di suatu tempat di sekitar sini, tapi sepertinya mereka tidak sadar... Itu sebabnya aku tidak bisa menentukan lokasi mereka.",
  ui_story_5040_50401302_28_dialog_content = "Halo?",
  ui_story_5040_50401302_29_dialog_content = "Kya! Adonis! Warna hitam!",
  ui_story_5040_50401302_30_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401302_31_dialog_content = "Tunggu... Lihat semak di sana. Tanaman itu biasanya tumbuh lurus ke atas, tapi ini tergeletak di tanah!",
  ui_story_5040_50401302_32_dialog_content = "Sepertinya seseorang atau sesuatu melakukan ini pada mereka...",
  ui_story_5040_50401302_33_dialog_content = "A-Adonis?!",
  ui_story_5040_50401302_34_dialog_content = "Dan Kya juga! Tapi di mana Sable?",
  ui_story_5040_50401302_35_dialog_content = "Mereka masih bernapas... hanya tak sadarkan diri.",
  ui_story_5040_50401302_36_dialog_content = "Adonis! Bangun!",
  ui_story_5040_50401302_37_dialog_content = "Urgh... Ke-Dimana aku...?",
  ui_story_5040_50401302_38_dialog_content = "Oh, syukurlah kau baik-baik saja!",
  ui_story_5040_50401302_39_dialog_content = "Aduh! E-Mudah, Tara! Tulang rusukku akan patah... atau mungkin sudah patah.",
  ui_story_5040_50401302_40_dialog_content = "Maaf, aku lega kau baik-baik saja.",
  ui_story_5040_50401302_41_dialog_content = "Apakah Anda ingat bagaimana Anda sampai di sini? Mengapa Sable tidak bersama kalian berdua?",
  ui_story_5040_50401302_42_dialog_content = "Sebentar…",
  ui_story_5040_50401302_43_dialog_content = "Aku ingat badai pasir gila ini, dan tanah tenggelam di bawah kakiku... Dan kemudian, cacing pasir merah muda itu menyerbu ke arahku...",
  ui_story_5040_50401302_44_dialog_content = "Saya panik. Saya tidak ingin tersapu oleh badai atau ditelan pasir, jadi saya meraih salah satu sisik cacing pasir dan berpegangan erat-erat.",
  ui_story_5040_50401302_45_dialog_content = "Setelah itu, dia membawaku ke tempat yang gelap gulita... Kupikir itu semacam liang?",
  ui_story_5040_50401302_46_dialog_content = "Saya memanggil Kya dan Sable, tetapi mereka tidak menanggapi.",
  ui_story_5040_50401302_47_dialog_content = "Saat itulah cacing pasir mulai meronta-ronta. Saya tidak berani melepaskannya, jadi saya bertahan sampai akhirnya saya pingsan.",
  ui_story_5040_50401302_48_dialog_content = "Jangan pernah lakukan itu lagi lain kali saat kau melihat cacing pasir, Adonis.",
  ui_story_5040_50401302_49_dialog_content = "Itu salah satu hal paling berbahaya yang bisa Anda lakukan. Anda sangat beruntung masih hidup.",
  ui_story_5040_50401302_50_dialog_content = "Maksudku, ini pertama kalinya aku bertatap muka dengan cacing pasir...",
  ui_story_5040_50401302_51_dialog_content = "Bagaimanapun... Kau masih hidup dan aman, dan hanya itu yang bisa kuminta.",
  ui_story_5040_50401302_52_dialog_content = "Ya, syukurlah.",
  ui_story_5040_50401302_53_dialog_content = "Oh, dan aku punya ini!",
  ui_story_5040_50401302_54_dialog_content = "Apakah itu sisik dari cacing pasir merah muda?!",
  ui_story_5040_50401302_55_dialog_content = "Ya! Aku berhasil melepaskannya dari monster itu saat dia menyeretku melintasi padang pasir.",
  ui_story_5040_50401302_56_dialog_content = "Tapi saya hanya punya satu dari mereka ... Saya harap itu cukup.",
  ui_story_5040_50401302_57_dialog_content = "(Tapi Tara bahkan tidak mengalami amnesia... Haruskah kita memberitahunya?)",
  ui_story_5040_50401302_58_dialog_content = "Sebenarnya, Adonis... Ada yang ingin aku akui.",
  ui_story_5040_50401302_59_dialog_content = "Ada apa?",
  ui_story_5040_50401302_60_dialog_content = "Saya tidak pernah kehilangan ingatan saya sejak awal.",
  ui_story_5040_50401302_61_dialog_content = "Selama ini aku berpura-pura... Aku hanya ingin melihat apakah kau mampu mengumpulkan keberanian untuk meninggalkan Northland...",
  ui_story_5040_50401302_62_dialog_content = "... Tara, kamu seharusnya tidak melakukan ini.",
  ui_story_5040_50401302_63_dialog_content = "Maaf…",
  ui_story_5040_50401302_64_dialog_content = "Seharusnya aku tidak berbohong padamu, atau memaksamu meninggalkan Northland, atau membuatmu menghadapi semua bahaya itu... kau berhak marah padaku.",
  ui_story_5040_50401302_65_dialog_content = "Saya berjanji tidak akan pernah membuat Anda tinggal di mana pun Anda tidak ingin hidup lagi! Aku akan menghabiskan sisa hidupku di Northland, jika aku harus...",
  ui_story_5040_50401302_66_dialog_content = "Tapi bagaimana Anda akan menjelajah jika Anda tinggal di sana? Bepergian di Northland hampir mustahil.",
  ui_story_5040_50401302_67_dialog_content = "Aku... Aku akan berhenti menjelajah.",
  ui_story_5040_50401302_68_dialog_content = "Anda jauh lebih penting bagi saya daripada menggali di beberapa reruntuhan.",
  ui_story_5040_50401302_69_dialog_content = "...",
  ui_story_5040_50401302_70_dialog_content = "Aku tidak bisa mempercayaimu.",
  ui_story_5040_50401302_71_dialog_content = "Apa?!",
  ui_story_5040_50401401_1_dialog_content = "Aku... Aku bahkan tidak bisa menggambarkan betapa marahnya aku padamu!",
  ui_story_5040_50401401_2_dialog_content = "Aku turut sedih...",
  ui_story_5040_50401401_3_dialog_content = "Dengarkan apa yang harus saya katakan sebelum Anda mulai meminta maaf!",
  ui_story_5040_50401401_4_dialog_content = "Aku pernah menjadi orang yang sangat lemah sebelumnya... Aku bahkan tidak bisa melangkah keluar dari Northland, apalagi melawan Eclipsites.",
  ui_story_5040_50401401_5_dialog_content = "Saya tidak menyalahkan Anda karena melakukan apa yang Anda lakukan untuk membantu saya mengatasi ketakutan saya... Lagi pula, saya yakin Anda sudah kehabisan akal.",
  ui_story_5040_50401401_6_dialog_content = "Adonis...",
  ui_story_5040_50401401_7_dialog_content = "Jadi kamu tidak kesal padanya karena dia berbohong tentang amnesia?",
  ui_story_5040_50401401_8_dialog_content = "Saya sudah menduga bahwa dia tidak kehilangan ingatannya tadi malam. Aku tidak marah tentang itu.",
  ui_story_5040_50401401_9_dialog_content = "Sebaliknya, saya merasakan kelegaan yang luar biasa ...",
  ui_story_5040_50401401_10_dialog_content = "karena akhirnya aku tahu pasti bahwa Tara tidak melupakanku karena dia membenciku.",
  ui_story_5040_50401401_11_dialog_content = "Lalu mengapa kamu begitu marah?",
  ui_story_5040_50401401_12_dialog_content = "Mungkin karena dia berkompromi?",
  ui_story_5040_50401401_13_dialog_content = "Berkompromi bagaimana tepatnya?",
  ui_story_5040_50401401_14_dialog_content = "Itu sebabnya, Mbak Jeriah! Saya senang seseorang melihat dari mana saya berasal.",
  ui_story_5040_50401401_15_dialog_content = "Bisakah seseorang tolong beri tahu saya apa yang sedang kita bicarakan ?!",
  ui_story_5040_50401401_16_dialog_content = "Aku marah karena Tara baru saja berkata dia rela menyerah menjelajahi dunia, hanya agar dia bisa tinggal bersamaku di Northland.",
  ui_story_5040_50401401_17_option_content = "Anda tidak ingin dia merasa terkekang.",
  ui_story_5040_50401401_18_dialog_content = "Benar sekali!",
  ui_story_5040_50401401_19_option_content = "Karena kau tidak menyukainya lagi?",
  ui_story_5040_50401401_20_dialog_content = "Tentu saja! Mengapa Anda bahkan berpikir bahwa ?!",
  ui_story_5040_50401401_21_dialog_content = "Saya mengenal Tara lebih baik dari siapa pun, jadi saya dapat mengatakan tanpa ragu bahwa dia tidak akan pernah rela pindah ke Northland dan menjalani kehidupan yang tenang dan damai.",
  ui_story_5040_50401401_22_dialog_content = "Meskipun dia bilang dia bersedia tinggal di sana dan bersamaku... Jelas bagiku bahwa dia menyerah pada harapan dan impiannya!",
  ui_story_5040_50401401_23_dialog_content = "Aku tidak pernah bisa membiarkan dia melakukan itu untuk dirinya sendiri, terutama untukku!",
  ui_story_5040_50401401_24_dialog_content = "Adonis, kamu...",
  ui_story_5040_50401401_25_dialog_content = "Aku mencintaimu, Tara. Anda yang NYATA. Orang yang ingin bepergian dan menjelajahi reruntuhan di setiap sudut dunia.",
  ui_story_5040_50401401_26_dialog_content = "Tanpamu, seorang pengecut yang terlindung sepertiku tidak akan pernah belajar banyak tentang dunia di luar Northland.",
  ui_story_5040_50401401_27_dialog_content = "Saya masih ingat mendengar Anda menjelaskan melihat siluet dinding garis pertahanan Illumina di cakrawala dari Gurun Rediesel.",
  ui_story_5040_50401401_28_dialog_content = "Atau bagaimana, dari Lumopolis, Anda bisa melihat ke bawah dan melihat semua gunung dan dataran, serta awan yang melintas di bawah kaki Anda...",
  ui_story_5040_50401401_29_dialog_content = "Pffft... Apakah kamu tidak melupakan bagian di mana tentara Lumopolis salah mengira aku sebagai pencuri?",
  ui_story_5040_50401401_30_dialog_content = "Itu sangat kacau ... Saya akhirnya menghabiskan sepanjang hari membantu mereka menangkap penjahat yang sebenarnya!",
  ui_story_5040_50401401_31_dialog_content = "Ha ha ha! Itu benar, dan syukurlah kamu cukup cepat untuk menangkapnya! Jika tidak, Anda akan berada dalam masalah besar!",
  ui_story_5040_50401401_32_dialog_content = "Saya harus bekerja sangat keras untuk membuktikan bahwa saya tidak bersalah!",
  ui_story_5040_50401401_33_dialog_content = "Tara... Kita bisa jalan berjam-jam, tapi yang ingin kukatakan...",
  ui_story_5040_50401401_34_dialog_content = "adalah sebelum aku bertemu denganmu, seluruh duniaku seputih dan sekosong salju yang menutupi Northland.",
  ui_story_5040_50401401_35_dialog_content = "Kaulah yang memberi warna pada hidupku yang membosankan dan monoton.",
  ui_story_5040_50401401_36_dialog_content = "Itu yang paling aku suka dari kamu. Saya tidak ingin menahan Anda atau mencegah Anda menjelajahi dunia ...",
  ui_story_5040_50401401_37_dialog_content = "itulah sebabnya saya akan melakukan yang terbaik untuk menjadi lebih kuat dan lebih berani, sehingga saya bisa pergi bersamamu!",
  ui_story_5040_50401401_38_dialog_content = "<size=45>Adoni—!</size>",
  ui_story_5040_50401401_39_dialog_content = "Aduh—! K-Kau menghancurkanku lagi!!!",
  ui_story_5040_50401401_40_dialog_content = "Jadi itu yang mereka rasakan, ya?",
  ui_story_5040_50401401_41_dialog_content = "Anda mungkin memiliki kemampuan membaca pikiran orang, tetapi itu tidak berarti Anda mampu membedakan apa yang ada di dalam hati mereka.",
  ui_story_5040_50401401_42_dialog_content = "Hai! Saya tidak pernah mengatakan kemampuan psikis saya serba tahu !!",
  ui_story_5040_50401401_43_dialog_content = "Memang, karena tidak ada orang. Dan itulah mengapa ada kesalahpahaman yang menciptakan jurang di antara orang-orang hingga secara bertahap memutuskan hubungan mereka.",
  ui_story_5040_50401401_44_dialog_content = "Tetapi jika orang mau berkomunikasi satu sama lain, mereka dapat menjembatani jurang dan menyambung kembali.",
  ui_story_5040_50401401_45_dialog_content = "Dan mereka kembali lebih kuat dan lebih tangguh dari sebelumnya.",
  ui_story_5040_50401401_46_dialog_content = "Ugh... Ada apa dengan semua keributan itu...?",
  ui_story_5040_50401401_47_dialog_content = "Kya! Anda akhirnya bangun!",
  ui_story_5040_50401401_48_dialog_content = "... PlayerName? Yeriah? Tara dan Adonis juga ada di sini... Apakah mereka akhirnya berbaikan?",
  ui_story_5040_50401401_49_dialog_content = "Mereka mengalami banyak hal, tapi ya... mereka baik-baik saja sekarang!",
  ui_story_5040_50401401_50_dialog_content = "Senang mendengarnya... Saat cacing pasir itu menyapuku dan Sable pergi, aku benar-benar mengkhawatirkan Adonis.",
  ui_story_5040_50401401_51_dialog_content = "Itu mengingatkan saya... Dimana Sable?",
  ui_story_5040_50401401_52_dialog_content = "Kami belum melihatnya... Ketika kami sampai di sini, kami hanya menemukan Anda dan Adonis pingsan. Aku juga tidak bisa merasakannya di dekat sini...",
  ui_story_5040_50401401_53_dialog_content = "Apakah Anda ingat apa yang terjadi sebelum Anda kehilangan kesadaran?",
  ui_story_5040_50401401_54_dialog_content = "Aku... Aku hanya ingat terlempar ke langit bersama Sable oleh badai pasir itu... Kurasa dia berhasil menangkap tanduk cacing pasir itu.",
  ui_story_5040_50401401_55_dialog_content = "Setelah itu, cacing pasir menyeret kami ke bawah tanah, dan kepalaku membentur batu atau semacamnya... Semuanya menjadi gelap setelah itu.",
  ui_story_5040_50401401_56_dialog_content = "Jadi jika selama ini kau dan Adonis sama-sama tidak sadarkan diri... siapa yang menyembunyikan kalian berdua di sini?",
  ui_story_5040_50401401_57_dialog_content = "Kecuali itu...",
  ui_story_5040_50401401_58_dialog_content = "Warna hitam?!",
  ui_story_5040_50401401_59_dialog_content = "Tapi jika dia yang menyembunyikanmu di sini, kenapa dia tidak terlihat?",
  ui_story_5040_50401401_60_dialog_content = "Mungkin dia ingin memancing cacing pasir menjauh dari Kya dan Adonis? Atau mungkin...",
  ui_story_5040_50401401_61_dialog_content = "Dia merasa dia sudah mencapai batasnya.",
  ui_story_5040_50401401_62_dialog_content = "\"Membatasi\"? \"Batas\" apa? Apa yang kalian berdua bicarakan kali ini?",
  ui_story_5040_50401401_63_dialog_content = "Sebenarnya, Sable bukanlah seorang Aurorian. Atau lebih tepatnya, dia pernah menjadi salah satunya.",
  ui_story_5040_50401401_64_dialog_content = "Apa?!",
  ui_story_5040_50401401_65_dialog_content = "Sudah kuduga…",
  ui_story_5040_50401401_66_dialog_content = "Kau sama sekali tidak terkejut, Caelestite.",
  ui_story_5040_50401401_67_dialog_content = "Saya punya firasat bahwa itulah masalahnya. Aku hanya tidak pernah punya bukti...",
  ui_story_5040_50401401_68_dialog_content = "Dia ditinggalkan oleh kekasihnya ketika dia masih seorang Aurorian. Dalam keputusasaannya, dia tertarik pada kekuatan Eclipsites dan menjadi Sable yang kita kenal sekarang.",
  ui_story_5040_50401401_69_dialog_content = "Tetapi meskipun tubuh dan pikirannya sangat terpengaruh, kesadarannya telah berjuang melawan keinginan untuk melawan dan menghancurkan.",
  ui_story_5040_50401401_70_dialog_content = "Namun, belum lama ini, dia mengatakan kepada saya bahwa dia tidak bisa bertahan lebih lama lagi ...",
  ui_story_5040_50401401_71_dialog_content = "Bagaimana ini mungkin...?",
  ui_story_5040_50401401_72_dialog_content = "(Kenapa aku merasa pernah melihat hal seperti ini terjadi sebelumnya...?)",
  ui_story_5040_50401401_73_dialog_content = "Beri tahu saya, PlayerName. Menurutmu orang seperti apa Sable itu?",
  ui_story_5040_50401401_74_option_content = "Salah satu yang baik.",
  ui_story_5040_50401401_75_dialog_content = "Dia mungkin terlihat dan bertindak sedikit berbeda, tapi dia ramah kepada semua orang. Aku percaya dia orang yang baik.",
  ui_story_5040_50401401_76_dialog_content = "Kita harus melakukan apapun yang kita bisa untuk membantunya.",
  ui_story_5040_50401401_77_option_content = "Aku tidak benar-benar mengenalnya...",
  ui_story_5040_50401401_78_dialog_content = "Dia terlihat sangat pemalu, jadi kami belum banyak bicara... tapi itu tidak menghentikanku untuk percaya bahwa dia adalah orang yang baik!",
  ui_story_5040_50401401_79_dialog_content = "Aku benar-benar ingin menjadi temannya jika dia mau.",
  ui_story_5040_50401401_80_dialog_content = "Kalau begitu mari kita lakukan segala daya kita untuk menemukan Sable.",
  ui_story_5040_50401401_81_dialog_content = "Sepakat!",
  ui_story_5040_50401401_82_dialog_content = "Shree—!",
  ui_story_5040_50401401_83_dialog_content = "Sepertinya Hawk memiliki sesuatu untuk diberitahukan kepada kita. Terima kasih, burung.",
  ui_story_5040_50401401_84_dialog_content = "Kree, Kree!",
  ui_story_5040_50401401_85_dialog_content = "Anda mengatakan Anda melihat tanda-tanda Sable di dekatnya?",
  ui_story_5040_50401401_86_dialog_content = "Dimana dia?!",
  ui_story_5040_50401401_87_dialog_content = "Shree—",
  ui_story_5040_50401401_88_dialog_content = "\"Di bawah kaki kita\"?",
  ui_story_5040_50401401_89_dialog_content = "Apa artinya...?",
  ui_story_5040_50401401_90_dialog_content = "Tunggu, aku merasakan sesuatu! Itu samar, tapi aku bisa merasakan sejumlah kecil Darkflow mendekat...",
  ui_story_5040_50401401_91_dialog_content = "<color=#e8d9bb>Booom—!!!</color>",
  ui_story_5040_50401401_92_dialog_content = "Gaah! Getaran! M-Mungkinkah itu cacing pasir?!",
  ui_story_5040_50401401_93_dialog_content = "<size=45>Groooaaar!!!</size>",
  ui_story_5040_50401401_94_dialog_content = "Awas, Tara!",
  ui_story_5040_50401401_95_dialog_content = "Heh, aku tahu itu masih mengintai.",
  ui_story_5040_50401401_96_dialog_content = "<size=45>Graaah!</size>",
  ui_story_5040_50401401_97_dialog_content = "Sepertinya ada sesuatu yang mengejar cacing pasir keluar dari terowongannya! Apakah itu... Sabel?!",
  ui_story_5040_50401401_98_dialog_content = "Aku... tidak akan... membiarkanmu!!!",
  ui_story_5040_50401401_99_dialog_content = "Warna hitam?! Dia terlihat seperti—",
  ui_story_5040_50401401_100_dialog_content = "Tidak peduli seperti apa dia! Dia masih di pihak kita!",
  ui_story_5040_50401401_101_dialog_content = "Anda harus membantunya, PlayerName!",
  ui_story_5040_50401401_102_dialog_content = "...",
  ui_story_5040_50401401_103_dialog_content = "Saya mendapatkannya. Saya akan melakukan semua yang saya bisa.",
  ui_story_5040_50401401_104_dialog_content = "Kupikir sudah waktunya kita menempatkan ancaman merah muda ini di tempatnya... Siap, Caelestite kecil?",
  ui_story_5040_50401401_105_dialog_content = "Apakah kamu akan baik-baik saja? Kami telah bertarung secara berurutan untuk waktu yang lama sekarang, dan Anda membakar banyak Lumina sebelumnya ...",
  ui_story_5040_50401401_106_dialog_content = "Ya ampun, betapa perhatiannya kamu.",
  ui_story_5040_50401401_107_dialog_content = "Tapi jangan khawatir. Saya memulihkan beberapa Lumina saya dalam perjalanan ke sini.",
  ui_story_5040_50401401_108_dialog_content = "Ayo.",
  ui_story_5040_50401401_109_dialog_content = "Roger! Mari bantu Sable dengan benda ini!",
  ui_story_5040_50401402_1_dialog_content = "Ingatanku...menjadi sangat kabur...",
  ui_story_5040_50401402_2_dialog_content = "Mereka seperti potongan-potongan film yang berserakan, melayang di benakku, menampilkan gambar yang tidak lengkap di depan mataku...",
  ui_story_5040_50401402_3_dialog_content = "Ingatan saya yang paling awal adalah gurun... Di sanalah saya dilahirkan, tempat saya dibesarkan...",
  ui_story_5040_50401402_4_dialog_content = "Sebelum kurir membawakan saya surat itu, saya pikir saya hanyalah orang biasa di dunia ini.",
  ui_story_5040_50401402_5_dialog_content = "Tapi surat itu membuka mata saya pada keindahan dunia di luar gurun... Dan bagaimana saya bertemu \"dia\"...",
  ui_story_5040_50401402_6_dialog_content = "Namanya luput dariku sekarang, tapi aku ingat cintaku padanya semakin dalam dengan setiap surat yang kami kirimkan satu sama lain.",
  ui_story_5040_50401402_7_dialog_content = "Ketika saya akhirnya mengakui perasaan saya kepadanya, dan dia membalasnya ...",
  ui_story_5040_50401402_8_dialog_content = "hati saya dipenuhi dengan kegembiraan dan kegembiraan.",
  ui_story_5040_50401402_9_dialog_content = "Tapi itu juga saat surat-suratnya mulai jarang datang.",
  ui_story_5040_50401402_10_dialog_content = "Saya khawatir surat-surat saya tidak cukup menyampaikan perasaan saya, jadi saya mulai mengiriminya hadiah.",
  ui_story_5040_50401402_11_dialog_content = "Awalnya, saya hanya mengirimkan barang-barang yang sulit didapat di padang pasir, seperti bunga dan pernak-pernik kuno.",
  ui_story_5040_50401402_12_dialog_content = "Hadiah saya tumbuh lebih boros seiring berjalannya waktu, sampai saya mulai mengirim Nightium.",
  ui_story_5040_50401402_13_dialog_content = "Tapi kemudian, surat-suratnya menjadi semakin langka, dan bukannya kata-kata lembut yang biasa dia ucapkan kepadaku, dia hanya akan memintaku untuk mengirimkan lebih banyak hadiah.",
  ui_story_5040_50401402_14_dialog_content = "Saya tidak bisa memahaminya, tetapi saya tidak pernah meragukannya. Sebenarnya aku ingin bertemu dengannya. Jadi, dia mengirimi saya alamat.",
  ui_story_5040_50401402_15_dialog_content = "Saya mengumpulkan keberanian saya dan berangkat dari gurun untuk pertama kalinya.",
  ui_story_5040_50401402_16_dialog_content = "Mengikuti surat-suratnya, saya pergi ke Illumina...",
  ui_story_5040_50401402_17_dialog_content = "Dan kemudian Lumopolis...",
  ui_story_5040_50401402_18_dialog_content = "Dan akhirnya... ke tepi Danau Cermin.",
  ui_story_5040_50401402_19_dialog_content = "Dia memberitahuku bahwa dia telah menyiapkan pesta pernikahan yang sangat besar untuk kami di Northland...",
  ui_story_5040_50401402_20_dialog_content = "... tapi dia tidak terlihat.",
  ui_story_5040_50401402_21_dialog_content = "Saya sangat terpukul, menangis, tidak tahu ke mana harus pergi atau apakah saya bisa kembali ke rumah.",
  ui_story_5040_50401402_22_dialog_content = "Saat itulah sebuah suara berbicara kepadaku.",
  ui_story_5040_50401402_23_dialog_content = "\"Ambil benih ini,\" katanya. \"Itu akan memberimu kekuatan untuk mewujudkan semua impianmu.\"",
  ui_story_5040_50401402_24_dialog_content = "Saya menaruh semua kepercayaan saya pada \"benih\" itu, tetapi pada akhirnya... saya kehilangan segalanya.",
  ui_story_5040_50401402_25_dialog_content = "Kenanganku, kemampuanku untuk berpikir... Aku menjadi tidak lebih dari monster liar yang berkeliaran di tanah tanpa tujuan...",
  ui_story_5040_50401402_26_dialog_content = "Sampai saya bertemu Adonis dan Tara. Tindakan mereka menunjukkan kepada saya bahwa masih ada cinta di dunia ini.",
  ui_story_5040_50401402_27_dialog_content = "Dan Kya, yang menunjukkan padaku ada orang yang menepati janjinya.",
  ui_story_5040_50401402_28_dialog_content = "Dan meskipun terkadang dia bersikap dingin dan jauh, Jeriah adalah orang yang sangat bisa diandalkan.",
  ui_story_5040_50401402_29_dialog_content = "Dari dia, saya melihat apa artinya menjadi riang.",
  ui_story_5040_50401402_30_dialog_content = "Itu sebabnya... dengan sedikit waktu yang tersisa...",
  ui_story_5040_50401402_31_dialog_content = "Aku... tidak akan membiarkanmu... mendekati mereka!!!",
  ui_story_5040_50401402_32_dialog_content = "<size=45>Groooaaar!!!</size>",
  ui_story_5040_50401402_33_dialog_content = "Urgh—!",
  ui_story_5040_50401402_34_dialog_content = "Warna hitam!",
  ui_story_5040_50401402_35_dialog_content = "Cacing pasir memiliki Sable! Kejar kepalanya, Jeriah! Kita perlu mengalihkan perhatiannya!",
  ui_story_5040_50401402_36_dialog_content = "Jangan khawatir...tentang aku!",
  ui_story_5040_50401402_37_dialog_content = "Serang... titik lemah!",
  ui_story_5040_50401402_38_dialog_content = "...",
  ui_story_5040_50401402_39_dialog_content = "Biar aku saja.",
  ui_story_5040_50401402_40_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5040_50401402_41_dialog_content = "Aum...",
  ui_story_5040_50401402_42_dialog_content = "Agh!",
  ui_story_5040_50401402_43_dialog_content = "(Cacing pasir akhirnya mati...)",
  ui_story_5040_50401402_44_dialog_content = "(Serangan Yeriah menargetkan luka lama dan menembus cangkangnya...)",
  ui_story_5040_50401402_45_dialog_content = "(Tapi tidak sebelum Sable menggigit besar, dan melemparkannya ke udara ...)",
  ui_story_5040_50401402_46_dialog_content = "Warna hitam! Apakah kamu baik-baik saja?!",
  ui_story_5040_50401402_47_dialog_content = "Nyeri...",
  ui_story_5040_50401402_48_dialog_content = "Warna hitam! Warna hitam!! Hentikan itu!!",
  ui_story_5040_50401402_49_dialog_content = "Luka itu terlihat serius...",
  ui_story_5040_50401402_50_dialog_content = "Bahkan jika dia sekuat Eclipsite, kurasa...",
  ui_story_5040_50401402_51_dialog_content = "Biarkan saya mencoba menyembuhkannya dengan Luminatics saya!",
  ui_story_5040_50401402_52_dialog_content = "Ini... Ini tidak bekerja! Tapi kenapa?!",
  ui_story_5040_50401402_53_dialog_content = "Tidak ada gunanya, Adonis. Luka itu bukanlah sesuatu yang dapat diobati oleh Luminatics Anda.",
  ui_story_5040_50401402_54_dialog_content = "Nona Jeriah! Kenapa kamu tidak membantunya?!",
  ui_story_5040_50401402_55_dialog_content = "Aku hanya melakukan apa yang dia minta.",
  ui_story_5040_50401402_56_dialog_content = "Anda juga mengerti, bukan? Bahkan jika aku menyelamatkannya, dia akan berubah menjadi monster tak berakal dalam waktu lama.",
  ui_story_5040_50401402_57_dialog_content = "...",
  ui_story_5040_50401402_58_dialog_content = "Kya...",
  ui_story_5040_50401402_59_dialog_content = "Warna hitam? Aku di sini, Sabel!",
  ui_story_5040_50401402_60_dialog_content = "Tolong... jangan salahkan... Jeriah...",
  ui_story_5040_50401402_61_dialog_content = "Aku tidak... ingin menyakitimu... jadi aku pergi. Tapi kemudian... aku melihat... cacing pasir...",
  ui_story_5040_50401402_62_dialog_content = "Aku harus... melihat kalian... kalian semua... untuk terakhir kalinya...",
  ui_story_5040_50401402_63_dialog_content = "Dan... aku ingat... dulu aku adalah... seorang Aurorian.",
  ui_story_5040_50401402_64_dialog_content = "Senang.",
  ui_story_5040_50401402_65_dialog_content = "T-Tapi aku masih belum mengantarmu pulang, Sable! Aku masih belum memenuhi permintaanmu!",
  ui_story_5040_50401402_66_dialog_content = "Lalu... aku mengubah... permintaanku.",
  ui_story_5040_50401402_67_dialog_content = "Tolong... bawa ini... kembali ke... rumahku.",
  ui_story_5040_50401402_68_dialog_content = "Beri tahu keluargaku... Maafkan aku...",
  ui_story_5040_50401402_69_dialog_content = "...",
  ui_story_5040_50401402_70_dialog_content = "... Courier Union Kya... siap melayani Anda.",
  ui_story_5040_50401402_71_dialog_content = "Courier Union selalu berhasil mengantarkan paket!",
  ui_story_5040_50401402_72_dialog_content = "Aku mengandalkan mu...",
  ui_story_5040_50401402_73_dialog_content = "Sabel... Tidak...",
  ui_story_5040_50401402_74_dialog_content = "Tidak apa-apa, Kya...",
  ui_story_5040_50401402_75_dialog_content = "Aku akan pergi mencarikanmu sesuatu untuk menyeka air matamu...",
  ui_story_5040_50401402_76_dialog_content = "...",
  ui_story_5040_50401402_77_dialog_content = "Pergi dan biarkan semuanya keluar.",
  ui_story_5040_50401402_78_dialog_content = "Hanya dengan begitu kesedihan Anda akan menjadi motivasi yang Anda butuhkan untuk terus maju.",
  ui_story_5040_50401402_79_dialog_content = "Yeriah...?",
  ui_story_5040_50401402_80_dialog_content = "Apakah kamu baik-baik saja? Kenapa kamu tiba-tiba pergi?",
  ui_story_5040_50401402_81_dialog_content = "Bahkan aku butuh waktu untuk menenangkan diri sesekali, Caelestite kecil.",
  ui_story_5040_50401402_82_dialog_content = "Oh! M-Maaf, Jeriah... Kurasa aku sudah terbiasa melihatmu berurusan dengan segala sesuatu dengan cara yang begitu riang.",
  ui_story_5040_50401402_83_dialog_content = "Hehehe... Terima kasih atas pujiannya.",
  ui_story_5040_50401402_84_dialog_content = "Saya sudah lama tahu bahwa Sable tidak punya banyak waktu lagi.",
  ui_story_5040_50401402_85_dialog_content = "Kupikir aku akan bisa menjaga jarak seperti biasanya... tapi kali ini sepertinya tidak.",
  ui_story_5040_50401402_86_dialog_content = "Anda tahu tentang dia? Mengapa Anda tidak memberi tahu siapa pun?",
  ui_story_5040_50401402_87_dialog_content = "Mengapa saya melakukan itu?",
  ui_story_5040_50401402_88_dialog_content = "Uh.. Nah, jika kita semua tahu lebih awal, kita mungkin bisa membantunya lebih banyak lagi!",
  ui_story_5040_50401402_89_dialog_content = "Tara dan Adonis juga tidak masalah.",
  ui_story_5040_50401402_90_dialog_content = "Mereka mungkin bisa menyimpan rahasia, tentu... tapi bagaimana dengan orang lain?",
  ui_story_5040_50401402_91_dialog_content = "Semakin banyak orang yang tahu tentang sebuah rahasia, semakin mudah terungkap.",
  ui_story_5040_50401402_92_dialog_content = "Ada juga banyak Aurorian di dunia yang tidak akan berpikir dua kali untuk membalas dendam padanya.",
  ui_story_5040_50401402_93_dialog_content = "Burung kecil itu sudah terbang terlalu dekat dengan matahari; tidak ada jalan kembali untuknya.",
  ui_story_5040_50401402_94_dialog_content = "Jika identitasnya diketahui, itu akan membuat \"perjalanan terakhir\" berharganya jauh lebih sulit daripada sebelumnya.",
  ui_story_5040_50401402_95_dialog_content = "Kau benar…",
  ui_story_5040_50401402_96_dialog_content = "Itu sebabnya, Caelestite kecil, Anda harus selalu mengingat satu hal yang sangat penting.",
  ui_story_5040_50401402_97_dialog_content = "Hubungan dengan orang lain itu penting, tetapi memiliki lebih banyak dari mereka tidak selalu merupakan hal yang baik.",
  ui_story_5040_50401402_98_dialog_content = "Nyatanya, mempertahankan tingkat jarak dan kebijaksanaan yang sesuai terkadang merupakan pilihan yang lebih baik.",
  ui_story_5040_50401402_99_dialog_content = "Biarkan hubungan Anda menjadi angin di bawah sayap rekan Anda, dan bukan jaring yang mengikat mereka.",
  ui_story_5040_50401402_100_dialog_content = "Aku paham…",
  ui_story_5040_50401402_101_dialog_content = "Saya kembali, Nona Jeriah.",
  ui_story_5040_50401402_102_dialog_content = "Aku minta maaf karena aku menangis begitu lama...",
  ui_story_5040_50401402_103_dialog_content = "Apa yang perlu disesali? Anda tidak bisa memendam emosi seperti itu. Itu selalu yang terbaik untuk membiarkan mereka keluar saat mereka perlu keluar.",
  ui_story_5040_50401402_104_dialog_content = "Tara benar.",
  ui_story_5040_50401402_105_dialog_content = "Sepertinya kamu sudah memutuskan apa yang akan kamu lakukan selanjutnya, Kya.",
  ui_story_5040_50401402_106_dialog_content = "Ya. Aku sudah selesai menangis, karena masih ada yang harus kulakukan. Sable meminta saya untuk mengirimkan stempel ini ke rumahnya.",
  ui_story_5040_50401402_107_dialog_content = "Saya mungkin tidak memiliki cara untuk melakukannya sekarang, tetapi setelah semuanya selesai... Saya akan mengirimkan permintaan untuk mentransfer ke divisi Rediesel Wrench dari Courier Union.",
  ui_story_5040_50401402_108_dialog_content = "Saat saya bekerja, saya akan membiasakan diri dengan gurun sehingga suatu hari saya dapat menemukan rumah Sable.",
  ui_story_5040_50401402_109_dialog_content = "Saya tidak akan pernah menyerah, bahkan jika saya harus mencari setiap jengkal Gurun Rediesel.",
  ui_story_5040_50401402_110_dialog_content = "Selama ada tujuan, seekor burung kecil selalu bisa menyelesaikan perjalanannya berapapun jaraknya... Benar kan, Kya?",
  ui_story_5040_50401402_111_dialog_content = "Benar sekali!",
  ui_story_5040_50401402_112_dialog_content = "Bagaimana dengan kalian?",
  ui_story_5040_50401402_113_dialog_content = "Saya tidak ragu lagi. Saya tahu bahwa saya benar-benar mencintai Adonis dengan sepenuh hati.",
  ui_story_5040_50401402_114_dialog_content = "Saya tidak perlu apa-apa lagi untuk membuktikannya.",
  ui_story_5040_50401402_115_dialog_content = "Aku juga sudah mengambil keputusan. Dunia luar mungkin berbahaya, tetapi tidak seseram yang saya kira.",
  ui_story_5040_50401402_116_dialog_content = "Aku yang dulu sebenarnya tidak takut pada dunia luar... Aku takut pada hal yang tidak diketahui.",
  ui_story_5040_50401402_117_dialog_content = "Tapi dengan bantuan Tara, aku akhirnya mengatasi ketakutanku.",
  ui_story_5040_50401402_118_dialog_content = "Aku juga tidak akan pernah meminta Adonis melakukan hal-hal gila di luar dirinya.",
  ui_story_5040_50401402_119_dialog_content = "Kami melakukan perjalanan ke seluruh benua, menghadapi bahaya yang tak terhitung jumlahnya, dan mengalami rasa sakit dan kehilangan...",
  ui_story_5040_50401402_120_dialog_content = "tapi setidaknya pada akhirnya, kalian berdua akhirnya bisa saling memahami.",
  ui_story_5040_50401402_121_dialog_content = "Saya kira orang bisa menyebut ini lapisan perak.",
  ui_story_5040_50401402_122_dialog_content = "Apa yang akan kamu lakukan jika Adonis gagal mendapatkan sisik cacing pasir merah muda itu, Tara?",
  ui_story_5040_50401402_123_dialog_content = "Apakah Anda akan terus sandiwara kecil Anda?",
  ui_story_5040_50401402_124_dialog_content = "Tentang itu...",
  ui_story_5040_50401402_125_dialog_content = "Saya berani menebak bahwa Anda memiliki rencana cadangan.",
  ui_story_5040_50401402_126_dialog_content = "Ehehe... Tidak ada yang melewatimu, Jeriah!",
  ui_story_5040_50401402_127_dialog_content = "A-Skala cacing pasir pink lainnya?!",
  ui_story_5040_50401402_128_dialog_content = "Ini berasal dari pertemuan pertama Sinsa dengan cacing pasir merah muda. Saya harus menawar banyak uang untuk membelinya di pelelangan.",
  ui_story_5040_50401402_129_dialog_content = "Kaulah yang membelinya?!",
  ui_story_5040_50401402_130_dialog_content = "Tidak heran Anda langsung tahu bahwa ramuan itu palsu ... \"Bahan langka\" yang disebutkan paranormal itu ada di tangan Anda selama ini!",
  ui_story_5040_50401402_131_dialog_content = "Bukan hanya itu... Maksudku, ayolah! \"Ramuan Kekuatan Tak Terbatas\"? Nama itu saja sudah cukup konyol!",
  ui_story_5040_50401402_132_dialog_content = "Kau satu-satunya orang yang naif dan cukup impulsif sehingga aku tahu siapa yang akan jatuh cinta pada hal seperti itu.",
  ui_story_5040_50401402_133_dialog_content = "Aku, eh... Yah...",
  ui_story_5040_50401402_134_dialog_content = "Sebenarnya, saya sudah siap untuk hasil ini ketika saya memutuskan untuk memalsukan amnesia.",
  ui_story_5040_50401402_135_dialog_content = "Jika Adonis gagal dalam persidangan...",
  ui_story_5040_50401402_135X1_dialog_content = "Saya akan memberikan skala ini kepada Jeriah dan memintanya untuk menemukan cara lain agar kami mendapatkannya.",
  ui_story_5040_50401402_136_dialog_content = "Begitu... Jadi kenapa kau membeli sesuatu seperti ini? ",
  ui_story_5040_50401402_137_dialog_content = "…!",
  ui_story_5040_50401402_138_dialog_content = "Er, b-baiklah... Ini skala cacing pasir yang sangat langka, lho! Ditambah warnanya merah muda, jadi aku...",
  ui_story_5040_50401402_139_dialog_content = "Aku ingin menunjukkannya pada Adonis... jadi aku membelinya karena dorongan hati.",
  ui_story_5040_50401402_140_dialog_content = "Awalnya, saya ingin meminta pandai besi untuk membuatkan cincin kawin untuknya.",
  ui_story_5040_50401402_141_dialog_content = "Oh? Itu ide yang menarik. Itu juga tidak akan membiarkan kecantikan skala cacing pasir disia-siakan.",
  ui_story_5040_50401402_142_dialog_content = "Tapi kalau saya tidak salah, hanya bagian tengah timbangan yang cukup keras untuk pekerjaan itu... artinya hanya bisa dibuat satu cincin saja, kan?",
  ui_story_5040_50401402_143_dialog_content = "Apa yang akan kaulakukan terhadap cincinmu sendiri jika Adonis tidak berhasil membongkar sisik lain dari monster itu hari ini?",
  ui_story_5040_50401402_144_dialog_content = "Aku... Aku tidak pernah benar-benar memikirkannya.",
  ui_story_5040_50401402_145_dialog_content = "Tapi itu tidak begitu penting. Saya bisa menerima materi apa pun, jujur saja.",
  ui_story_5040_50401402_146_dialog_content = "Anda tidak pernah menjadi orang yang peduli tentang hal semacam ini, tetapi itu tidak membuatnya baik-baik saja!",
  ui_story_5040_50401402_147_dialog_content = "Pernikahan tanpa sepasang cincin yang serasi tidaklah tepat! Di samping itu...",
  ui_story_5040_50401402_148_dialog_content = "Kami memiliki semua sisik cacing pasir merah muda yang kami inginkan sekarang!",
  ui_story_5040_50401402_149_dialog_content = "<color=#e8d9bb>pekikan—</color>",
  ui_story_5040_50401402_150_dialog_content = "Di mana cacing pasir? Aku tidak melihatnya dimanapun!!",
  ui_story_5040_50401402_151_dialog_content = "Tenang, Brock. Lihat ke sana.",
  ui_story_5040_50401402_152_dialog_content = "Astaga, ini nyata! Cacing pasir merah muda itu nyata! ... Tapi kenapa tidak bergerak?",
  ui_story_5040_50401402_153_dialog_content = "Tunggu ... apakah itu mati?!?!",
  ui_story_5040_50401402_154_dialog_content = "Fleur? Bangsat? Apa yang kalian berdua lakukan di sini?",
  ui_story_5040_50401402_155_dialog_content = "Ah, PlayerName! Syukurlah kau tidak terluka.",
  ui_story_5040_50401402_156_dialog_content = "Saya mendengar dari Sinsa bahwa Anda dan teman Anda sedang berburu cacing pasir merah muda, jadi tentu saja saya agak khawatir.",
  ui_story_5040_50401402_157_dialog_content = "Aku bergegas secepat mungkin, tapi sepertinya bantuanku tidak diperlukan lagi.",
  ui_story_5040_50401402_158_dialog_content = "Saya tidak tahu seseorang di Rediesel Wrench bisa begitu perhatian. Sayang sekali, kalau begitu, kamu terlambat.",
  ui_story_5040_50401402_159_dialog_content = "Semoga lebih beruntung lain kali, saya kira... Hubungi kami jika Anda membutuhkan bantuan lagi. Kami akan sampai di sana lebih cepat dari yang bisa Anda katakan \"cacing pasir\".",
  ui_story_5040_50401402_160_dialog_content = "Nah, jika semuanya sudah diurus di sini, kita harus kembali.",
  ui_story_5040_50401402_161_dialog_content = "Kalian mungkin menang kali ini, tapi aku bersumpah akan memburu yang lebih besar, bahkan lebih jahat lain kali!",
  ui_story_5040_50401402_162_dialog_content = "Omong-omong, kalian butuh bantuan kami dengan hal ini? Kudengar sisik cacing pasir berwarna merah jambu dijual dengan harga sangat mahal...",
  ui_story_5040_50401402_163_dialog_content = "Cacing pasir merah muda ini merenggut nyawa teman Kya, jadi kami tidak bisa begitu saja menyerahkannya kepadamu dengan mudah.",
  ui_story_5040_50401402_164_dialog_content = "Paling tidak, Anda harus bertanya kepada Kya terlebih dahulu.",
  ui_story_5040_50401402_165_dialog_content = "... Saya tidak peduli apa yang dilakukan orang dengan cacing pasir ini.",
  ui_story_5040_50401402_166_dialog_content = "Selama Tara dan Adonis memiliki timbangan yang cukup untuk membuat cincin kawin mereka, kalian bisa melakukan apa saja dengan sisanya.",
  ui_story_5040_50401402_167_dialog_content = "Saya yakin Sable juga menginginkannya.",
  ui_story_5040_50401402_168_dialog_content = "Saya tidak tahu apa yang sebenarnya terjadi di sini, tapi... Saya harap Anda segera merasa lebih baik!",
  ui_story_5040_50401402_169_dialog_content = "Saya berjanji kita akan memanfaatkan cacing pasir ini dengan baik. Kami tidak akan membiarkan semua itu sia-sia!",
  ui_story_5040_50401402_170_dialog_content = "Kami kembali untuk meminta bantuan. Untuk cacing pasir sebesar ini, kita pasti membutuhkannya.",
  ui_story_5040_50401402_171_dialog_content = "Sampai Lain waktu, PlayerName.",
  ui_story_5040_50401402_172_dialog_content = "Tentu, sampai jumpa!",
  ui_story_5040_50401402_173_dialog_content = "Ini hari yang cukup sibuk, tapi setelah semua perjuangan pahit kami, akhirnya kami berhasil mengalahkan cacing pasir merah muda.",
  ui_story_5040_50401402_174_dialog_content = "Yang berarti Adonis telah resmi lulus sidang terakhirnya.",
  ui_story_5040_50401402_175_dialog_content = "Saya hanya berharap semuanya bisa berakhir berbeda dengan Sable...",
  ui_story_5040_50401402_176_dialog_content = "Tapi, berkat dia dan semua orang, akhirnya aku bisa memahami perasaan Adonis yang sebenarnya.",
  ui_story_5040_50401402_177_dialog_content = "Dan saya semakin memahami Tara, selain mendapatkan keberanian yang akhirnya saya butuhkan untuk melangkah ke dunia.",
  ui_story_5040_50401402_178_dialog_content = "Karena semua orang tampaknya telah mendapatkan apa yang mereka inginkan, hanya ada satu hal yang harus dilakukan... Izinkan saya untuk memberi Anda stempel Anda.",
  ui_story_5040_50401402_179_dialog_content = "<color=#e8d9bb>Stempel!</color>",
  ui_story_5040_50401402_180_dialog_content = "Selamat, kalian berdua.",
  ui_story_5040_50401402_181_dialog_content = "Ya! Selamat!",
  ui_story_5040_50401402_182_option_content = "Selamat!",
  ui_story_5040_50401402_183_dialog_content = "Terima kasih!",
  ui_story_5040_50401402_184_dialog_content = "Terimakasih semuanya!",
  ui_story_5040_50401402_185_dialog_content = "Jika bukan karena kalian semua, aku masih meringkuk di sudut di Northland...",
  ui_story_5040_50401402_186_dialog_content = "Tapi Anda mengatasi ketakutan Anda.",
  ui_story_5040_50401402_187_dialog_content = "Ya. Saya akhirnya memiliki keberanian untuk menemani Anda selama sisa hidup kita.",
  ui_story_5040_50401402_188_dialog_content = "*Ehem* Bukannya aku ingin mengganggu momen pribadi kalian ini, tapi sebelum itu semua, masih ada yang harus diselesaikan.",
  ui_story_5040_50401402_189_dialog_content = "…!",
  ui_story_5040_50401402_190_dialog_content = "Ya! Dan itu juga yang paling penting!",
  ui_story_5040_50401402_191_dialog_content = "Bagus, sepertinya semua burung tahu bagian terakhir yang paling penting dari perjalanan ini.",
  ui_story_5040_50401402_192_dialog_content = "Hah? Ada yang mau mengisi saya?",
  ui_story_5040_50401402_193_dialog_content = "Bukankah sudah jelas?",
  ui_story_5040_50401402_194_dialog_content = "Pernikahan!",
  ui_story_5040_50401501_1_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian di Northland...</color>",
  ui_story_5040_50401501_2_dialog_content = "Adonis dan Tara benar-benar tidak terburu-buru...",
  ui_story_5040_50401501_3_dialog_content = "Hatsyiii!",
  ui_story_5040_50401501_4_dialog_content = "Dingin sekali di sini... Berapa lama lagi kita harus menunggu?!",
  ui_story_5040_50401501_5_dialog_content = "Sabar, Caelestite kecil. Ini adalah salah satu hari terpenting dalam hidup mereka, jadi beri mereka sedikit lebih banyak waktu untuk bersiap.",
  ui_story_5040_50401501_6_dialog_content = "Iya, iya...",
  ui_story_5040_50401501_7_dialog_content = "Omong-omong, ini bukan tempat yang awalnya direncanakan Adonis untuk mengadakan pernikahan, bukan?",
  ui_story_5040_50401501_8_dialog_content = "Tentu saja tidak.",
  ui_story_5040_50401501_9_dialog_content = "Mereka tidak punya alasan untuk kawin lari lagi, jadi masuk akal jika mereka ingin mengadakan pernikahan yang lebih besar dan lebih mencolok.",
  ui_story_5040_50401501_10_dialog_content = "Atau ... apakah Anda mungkin lebih suka melakukan hal-hal yang terlarang?",
  ui_story_5040_50401501_11_dialog_content = "T-Tidak, ini baik-baik saja! Sekarang mereka dapat berbagi kebahagiaan dengan semua teman dan keluarga mereka tanpa khawatir!",
  ui_story_5040_50401501_12_dialog_content = "PlayerName?",
  ui_story_5040_50401501_13_dialog_content = "Saya tidak berharap melihat Anda di sini hari ini.",
  ui_story_5040_50401501_14_dialog_content = "Hei, Novio! Apakah Anda di sini untuk pernikahan juga?",
  ui_story_5040_50401501_15_dialog_content = "Memang. Aku menerima undangan dari Adonis, dan aku akan lalai jika tidak hadir. ",
  ui_story_5040_50401501_16_dialog_content = "Karena dia adalah murid saya, saya di sini untuk menyampaikan harapan terbaik Istana Musim Dingin kepadanya dan pengantin barunya.",
  ui_story_5040_50401501_17_dialog_content = "Oh ya, saya ingat orang tua Adonis dan Naroxel menyebutkan sesuatu tentang itu!",
  ui_story_5040_50401501_18_dialog_content = "Adonis selalu berhati-hati, anak laki-laki tertutup... Sejauh yang saya tahu, dia tidak pernah menginjakkan kaki di luar perbatasan Northland.",
  ui_story_5040_50401501_19_dialog_content = "Ketika saya mendengar bahwa dia menikahi Tara, seorang wanita muda dari Rediesel Wrench... Yah, saya terkejut, untuk sedikitnya.",
  ui_story_5040_50401501_20_dialog_content = "Tetap saja, Yang Mulia selalu senang melihat rakyatnya berinteraksi dengan dunia luar dan memperluas wawasan mereka... Seperti saya.",
  ui_story_5040_50401501_21_dialog_content = "Iya!",
  ui_story_5040_50401501_22_dialog_content = "Tolong sampaikan salam kami kepada Ratu Bethlehem saat Anda kembali ke istana.",
  ui_story_5040_50401501_23_dialog_content = "Tentu saja.",
  ui_story_5040_50401501_24_dialog_content = "Sekarang permisi, saya masih perlu menawarkan hadiah pernikahan saya kepada Adonis.",
  ui_story_5040_50401501_25_dialog_content = "Hal yang pasti. Sampai jumpa lagi, Novio!",
  ui_story_5040_50401501_26_dialog_content = "Sampai Lain waktu, PlayerName.",
  ui_story_5040_50401501_27_dialog_content = "Ngomong-ngomong, kenapa Kya belum datang?",
  ui_story_5040_50401501_28_dialog_content = "Dia secara praktis memerintahkan saya untuk menghentikan Colossus saat kami terbang di atas Umbraton beberapa hari yang lalu, mengatakan dia perlu melakukan sesuatu...",
  ui_story_5040_50401501_29_dialog_content = "Dia tidak mendengar saya ketika saya bertanya tentang hal itu, dan melompat bahkan sebelum saya memiliki kesempatan untuk mendaratkan Soroz dengan benar!",
  ui_story_5040_50401501_30_dialog_content = "Apakah dia tidak berencana datang ke pernikahan Tara dan Adonis?",
  ui_story_5040_50401501_31_dialog_content = "Kya bukan orang yang melanggar janjinya.",
  ui_story_5040_50401501_32_dialog_content = "Aku... aku akhirnya berhasil!!!",
  ui_story_5040_50401501_33_dialog_content = "Wah... syukurlah... aku belum terlambat!",
  ui_story_5040_50401501_34_dialog_content = "K-Kya?! Mengapa kau begitu kehabisan napas?",
  ui_story_5040_50401501_35_dialog_content = "Sini, minumlah air dan atur napasmu. Pernikahan akan segera dimulai.",
  ui_story_5040_50401501_36_dialog_content = "Th... Terima kasih, Nona Jeriah...",
  ui_story_5040_50401501_37_dialog_content = "<color=#e8d9bb>Gluk, gluk, gluk—</color>",
  ui_story_5040_50401501_38_dialog_content = "Ahh... Aku sangat senang aku berhasil tepat waktu. Saya tidak akan pernah memaafkan diri sendiri jika saya terlambat untuk ini!",
  ui_story_5040_50401501_39_dialog_content = "Kemana saja kamu beberapa hari terakhir ini, Kya?",
  ui_story_5040_50401501_40_dialog_content = "Oh ya, aku masih belum memberitahumu.",
  ui_story_5040_50401501_41_dialog_content = "Tara dan Adonis memintaku untuk membawa sisik cacing pasir mereka ke pandai besi dan memalsukan mereka menjadi cincin kawin mereka.",
  ui_story_5040_50401501_42_dialog_content = "Lihatlah!",
  ui_story_5040_50401501_43_dialog_content = "Mereka cantik... Anda bahkan tidak tahu mereka terbuat dari sisik cacing pasir!",
  ui_story_5040_50401501_44_dialog_content = "Pandai besi itu membutuhkan waktu lebih lama dari yang dia perkirakan untuk memalsukan cincin-cincin ini.",
  ui_story_5040_50401501_45_dialog_content = "Jika bukan karena jalan pintas yang saya temukan di catatan yang dipinjamkan Emerald kepada saya, saya pasti sudah terlambat!",
  ui_story_5040_50401501_46_dialog_content = "Oh? Jalan pintas mana itu, dan mengapa saya belum pernah mendengarnya?",
  ui_story_5040_50401501_47_dialog_content = "Langit, tentu saja! Saya harus terbang tanpa henti selama berjam-jam hanya untuk mengejar kereta ke Northland!",
  ui_story_5040_50401501_48_dialog_content = "Sayapku masih sangat sakit...",
  ui_story_5040_50401501_49_dialog_content = "Anda tahu bahwa Serikat Kurir Umbraton akan memberi Anda transportasi seandainya Anda mengirimkan permintaan mendesak?",
  ui_story_5040_50401501_50_dialog_content = "Apa?!",
  ui_story_5040_50401501_51_dialog_content = "Kenapa tidak ada yang memberitahuku itu! Juga tidak disebutkan dalam catatan Emerald...",
  ui_story_5040_50401501_52_dialog_content = "Ini adalah layanan yang cukup baru yang ditawarkan oleh divisi Umbraton. Secara alami, Anda tidak akan menemukan apa pun tentang itu di buku catatan senior Anda.",
  ui_story_5040_50401501_53_dialog_content = "Sigh... Saya kira saya masih harus banyak belajar tentang divisi yang berbeda.",
  ui_story_5040_50401501_54_dialog_content = "Tetap saja, senang sekali Anda berhasil tiba di sini tepat waktu! Kami masih menunggu upacara dimulai, jadi istirahatlah, Kya!",
  ui_story_5040_50401501_55_dialog_content = "Baiklah!",
  ui_story_5040_50401501_56_dialog_content = "Bagaimana persiapan selama saya pergi?",
  ui_story_5040_50401501_57_dialog_content = "Tolong beritahu saya Anda menemukan apa yang disebut \"paranormal\" dan memberinya pelajaran sehingga dia tidak menipu orang lagi.",
  ui_story_5040_50401501_58_dialog_content = "Hehehe... Tentu saja.",
  ui_story_5040_50401501_59_dialog_content = "Kami pergi mencarinya segera setelah kami tiba.",
  ui_story_5040_50401501_60_dialog_content = "Itu dia! Itulah paranormal!",
  ui_story_5040_50401501_61_dialog_content = "Ah?! ... M-Bolehkah saya membantu Anda, tuan yang baik hati?",
  ui_story_5040_50401501_62_dialog_content = "Anda menjual saya beberapa \"ramuan ajaib\" jelek beberapa hari yang lalu, tapi itu benar-benar palsu!",
  ui_story_5040_50401501_63_dialog_content = "Ah iya! aku mengingatmu sekarang...",
  ui_story_5040_50401501_64_dialog_content = "Saya harus meminta Anda berhenti menodai nama baik saya dengan klaim menggelikan Anda, Pak. Saya dapat meyakinkan Anda, ramuan saya 100 persen asli dan efektif.",
  ui_story_5040_50401501_65_dialog_content = "Itu terbuat dari skala cacing pasir merah muda yang langka!",
  ui_story_5040_50401501_66_dialog_content = "Dan jika saya ingat dengan benar, bukankah Anda yang datang kepada saya ketika ramuan saya menyebabkan tunangan Anda kehilangan ingatannya?",
  ui_story_5040_50401501_67_dialog_content = "Itu saya, dan saya mengada-ada sepanjang waktu. Ramuanmu sama sekali tidak berpengaruh padaku.",
  ui_story_5040_50401501_68_dialog_content = "Tidak hanya itu, Anda bahkan tidak pernah menggunakan timbangan cacing pasir merah muda untuk membuatnya!",
  ui_story_5040_50401501_69_dialog_content = "O-Oh ya? Lalu mana buktimu?!",
  ui_story_5040_50401501_70_dialog_content = "Kamu duluan! Di mana Anda mendapatkan skala cacing pasir merah muda?",
  ui_story_5040_50401501_71_dialog_content = "Saya ingin Anda tahu bahwa saya membelinya di pelelangan belum lama ini! Hanya ada satu dari jenisnya di seluruh Astra!",
  ui_story_5040_50401501_72_dialog_content = "Wah, kebetulan sekali... soalnya kebetulan saya juga pernah beli timbangan cacing pasir warna pink di lelang beberapa waktu lalu.",
  ui_story_5040_50401501_73_dialog_content = "Apa?!",
  ui_story_5040_50401501_74_dialog_content = "Bahkan, saya masih memiliki sertifikat penjualan resmi sejak saya membelinya... Mau lihat?",
  ui_story_5040_50401501_75_dialog_content = "Anda adalah pembeli misterius yang melarikan diri dengan skala cacing pasir di pelelangan itu ?!",
  ui_story_5040_50401501_76_dialog_content = "Astaga... Membuatmu melibatkan dirimu hampir tidak membutuhkan usaha sama sekali.",
  ui_story_5040_50401501_77_dialog_content = "Saya tidak sepenuhnya paham bagaimana Northland menghukum para penipu, tapi...",
  ui_story_5040_50401501_78_dialog_content = "Saya yakin kalian tidak ingin tahu bagaimana kami menghukum mereka di Gurun Rediesel.",
  ui_story_5040_50401501_79_dialog_content = "Uh... kami benar-benar tidak perlu mendengarnya, terima kasih...",
  ui_story_5040_50401501_80_dialog_content = "M-maaf!",
  ui_story_5040_50401501_81_dialog_content = "Di sini, Anda dapat memiliki uang Anda kembali! Aku akan menyerahkan diri!",
  ui_story_5040_50401501_82_dialog_content = "Itu terdengar baik. Saya senang semuanya berhasil.",
  ui_story_5040_50401501_83_dialog_content = "Lantas, bagaimana dengan orang tua Adonis? Apakah mereka menyetujui pernikahan itu?",
  ui_story_5040_50401501_84_dialog_content = "Setelah melihat betapa Adonis telah berubah, mereka tidak punya hal lain untuk dikatakan tentang itu.",
  ui_story_5040_50401501_85_dialog_content = "Mereka dengan senang hati menyetujui pernikahan Tara dan Adonis!",
  ui_story_5040_50401501_86_dialog_content = "Benar-benar? Itu hampir terlalu bagus untuk menjadi kenyataan!",
  ui_story_5040_50401501_87_dialog_content = "Lagi pula, mereka sama sekali menentang gagasan Adonis kawin lari dengan Tara sebelumnya.",
  ui_story_5040_50401501_88_dialog_content = "Anda hanya berpikir begitu karena Anda gagal melihat bagaimana perasaan mereka yang sebenarnya.",
  ui_story_5040_50401501_89_dialog_content = "Saya kira jika ada satu orang yang bisa melihat melalui orang, itu Anda ...",
  ui_story_5040_50401501_90_dialog_content = "Jika kekuatan Caelestite bisa membaca hati orang, saya membayangkan dia juga bisa.",
  ui_story_5040_50401501_91_dialog_content = "A-aku tidak menggunakan kemampuanku untuk mengorek pikiran orang! Itu sama sekali tidak pantas!",
  ui_story_5040_50401501_92_dialog_content = "Cara terbaik untuk memahami orang lain adalah dengan berkomunikasi dengan mereka.",
  ui_story_5040_50401501_93_dialog_content = "Jadi apa yang dipikirkan orang tua Adonis saat itu?",
  ui_story_5040_50401501_94_dialog_content = "Hal yang sama yang akan dipikirkan ibu dan ayah biasa mana pun dalam posisi mereka.",
  ui_story_5040_50401501_95_dialog_content = "Mereka hanya khawatir anak mereka, yang tidak pernah meninggalkan Northland, tidak akan mampu beradaptasi dengan dunia luar yang asing.",
  ui_story_5040_50401501_96_dialog_content = "Itu, pada gilirannya, membuat mereka semakin tidak rela membiarkan dia menginjakkan kaki di luar tanah airnya.",
  ui_story_5040_50401501_97_dialog_content = "Kedengarannya seperti lingkaran setan.",
  ui_story_5040_50401501_98_dialog_content = "Itu benar, itulah sebabnya saya harus memberi mereka sedikit dorongan untuk memberi kesempatan kepada putra mereka.",
  ui_story_5040_50401501_99_dialog_content = "J-Jangan bilang kamu mengancam mereka seperti yang kamu lakukan dengan paranormal ?!",
  ui_story_5040_50401501_100_dialog_content = "Apa aku benar-benar terlihat seperti orang seperti itu bagimu?",
  ui_story_5040_50401501_101_dialog_content = "T-tidak…",
  ui_story_5040_50401501_102_dialog_content = "Anda harus menggunakan metode yang berbeda dengan orang yang berbeda.",
  ui_story_5040_50401501_103_dialog_content = "Orang tua Adonis adalah orang yang sangat berakal sehat. Mereka hanya enggan membiarkan putra mereka yang berharga keluar dari pandangan mereka.",
  ui_story_5040_50401501_104_dialog_content = "Yang saya lakukan hanyalah menunjukkan masalah memperlakukannya seperti ini, dan mereka segera menyadari bahwa melepaskannya adalah yang terbaik.",
  ui_story_5040_50401501_105_dialog_content = "Aku iri padanya karena memiliki orang tua seperti itu.",
  ui_story_5040_50401501_106_dialog_content = "Saya tidak tahu Anda melakukan begitu banyak di belakang layar!",
  ui_story_5040_50401501_107_dialog_content = "Saya hanya membantu di sana-sini... Saya ingin melihat bagaimana kisah mereka akan berakhir, dua kekasih ini dari ujung yang berlawanan.",
  ui_story_5040_50401501_108_dialog_content = "Ini memiliki akhir yang cukup memuaskan, jika saya mengatakannya sendiri.",
  ui_story_5040_50401501_109_dialog_content = "Lihat, mereka ada di sini!",
  ui_story_5040_50401501_110_dialog_content = "Itu Adonis dan Tara!",
  ui_story_5040_50401501_111_dialog_content = "Pakaian mereka terlihat luar biasa!",
  ui_story_5040_50401501_112_dialog_content = "Tara terlihat sangat menakjubkan! Dan Adonis... Aku tidak menyangka dia bersih-bersih dengan sangat baik!",
  ui_story_5040_50401501_113_dialog_content = "Selamat, kalian berdua.",
  ui_story_5040_50401501_114_dialog_content = "Selamat!",
  ui_story_5040_50401501_115_dialog_content = "Selamat!",
  ui_story_5040_50401501_116_dialog_content = "Terima kasih!",
  ui_story_5040_50401501_117_dialog_content = "Terima kasih banyak, semuanya! Maaf membuat kalian semua menunggu!",
  ui_story_5040_50401501_118_dialog_content = "Kami adalah pengantin baru yang paling beruntung di seluruh Astra karena dua kurir terhebatnya menjadi saksi pernikahan kami!",
  ui_story_5040_50401501_119_dialog_content = "Perasaan itu saling menguntungkan. Nah, mari kita mulai, oke?",
  ui_story_5040_50401501_120_dialog_content = "Tara, apa kau menerima Adonis sebagai suami sahmu?",
  ui_story_5040_50401501_121_dialog_content = "Untuk memiliki dan mempertahankan sejak hari ini, dalam keadaan sakit dan sehat, baik kaya maupun miskin, melalui semua kesengsaraan—",
  ui_story_5040_50401501_122_dialog_content = "Untuk mencintai, menghormati, dan menerimanya, sekarang dan selamanya, sampai maut memisahkan?",
  ui_story_5040_50401501_123_dialog_content = "Aku bersedia!",
  ui_story_5040_50401501_124_dialog_content = "Adonis, apa kau menerima Tara menjadi istri sahmu?",
  ui_story_5040_50401501_125_dialog_content = "Untuk memiliki dan mempertahankan sejak hari ini, dalam keadaan sakit dan sehat, baik kaya maupun miskin, melalui semua kesengsaraan—",
  ui_story_5040_50401501_126_dialog_content = "Untuk mencintai, menghormati, dan menerimanya, sekarang dan selamanya, sampai maut memisahkan?",
  ui_story_5040_50401501_127_dialog_content = "Aku bersedia!",
  ui_story_5040_50401501_128_dialog_content = "Cintamu telah menyeberangi sungai dan bertahan dari pegunungan perbedaan; itu telah menghadapi segala macam rintangan dan bahaya dan bertahan. Nah, burung-burung kecilku...",
  ui_story_5040_50401501_129_dialog_content = "Saya meminta Anda untuk menukar cincin Anda.",
  ui_story_5040_50401501_130_dialog_content = "Wah... Syukurlah upacaranya sudah selesai!",
  ui_story_5040_50401501_131_dialog_content = "Kami akhirnya harus membuang pakaian itu untuk sesuatu yang lebih nyaman!",
  ui_story_5040_50401501_132_dialog_content = "Anda tidak menyukai gaun pengantin Anda ?!",
  ui_story_5040_50401501_133_dialog_content = "Tentu saja! Kami memilihnya bersama, bukan?",
  ui_story_5040_50401501_134_dialog_content = "Itu hanya sedikit pengap memakainya, itu saja... Aku hampir tidak bisa bergerak di dalamnya!",
  ui_story_5040_50401501_135_dialog_content = "Saya hampir jatuh beberapa kali ketika Anda mengantar saya ke altar!",
  ui_story_5040_50401501_136_dialog_content = "Ha ha ha ha! Sejujurnya, agak aneh melihatmu dengan gaun flamboyan seperti itu.",
  ui_story_5040_50401501_137_dialog_content = "Mengenakan pakaian favorit Anda dan melakukan apapun yang Anda suka selalu yang terbaik, bukan?",
  ui_story_5040_50401501_138_dialog_content = "Ya, tapi harus kukatakan, setelan itu terlihat bagus untukmu.",
  ui_story_5040_50401501_139_dialog_content = "Aku juga penasaran, mengingat pakaian formal jauh dari pakaian biasa.",
  ui_story_5040_50401501_140_dialog_content = "Bagaimana Anda membuat diri Anda terlihat begitu baik di dalamnya?",
  ui_story_5040_50401501_141_dialog_content = "Eh, sebenarnya...",
  ui_story_5040_50401501_142_dialog_content = "Adonis telah mempersiapkan pernikahan ini secara rahasia untuk waktu yang sangat lama.",
  ui_story_5040_50401501_143_dialog_content = "Ayah? Ibu?!",
  ui_story_5040_50401501_144_dialog_content = "Dia sering menunggu sampai kami tidur larut malam dan mencobanya di depan cermin, memperbaiki perawakannya.",
  ui_story_5040_50401501_145_dialog_content = "Pernikahan ini sangat berarti baginya... Lebih dari segalanya, dia ingin memberi Anda pengalaman yang tak terlupakan.",
  ui_story_5040_50401501_146_dialog_content = "Tetap saja, dia akan sangat bersemangat berlatih sehingga dia akan membangunkan kami di tengah malam ...",
  ui_story_5040_50401501_147_dialog_content = "Tunggu, jadi selama ini kalian berdua sudah tahu?!",
  ui_story_5040_50401501_148_dialog_content = "Tentu saja kami melakukannya.",
  ui_story_5040_50401501_149_dialog_content = "Kami tidak pernah benar-benar menentang Anda menikah, Nak. Anda selalu bebas memilih apakah Anda melakukannya atau tidak, dan kepada siapa.",
  ui_story_5040_50401501_150_dialog_content = "Kami hanya khawatir bahwa Anda akan langsung menikah tanpa mempersiapkan diri dengan baik secara mental dan emosional.",
  ui_story_5040_50401501_151_dialog_content = "Lagi pula, Anda praktis tidak tahu apa-apa tentang dunia luar. Bahkan seorang penipu yang menjajakan ramuan bisa mengalahkanmu!",
  ui_story_5040_50401501_152_dialog_content = "Kami tidak bertanggung jawab membiarkan Anda menikah dalam keadaan seperti itu!",
  ui_story_5040_50401501_153_dialog_content = "Tepat! Bagaimana jika, suatu hari, Anda menyadari bahwa dunia luar bukan untuk Anda? Jika Anda menyesali keputusan Anda untuk meninggalkan Northland,",
  ui_story_5040_50401501_154_dialog_content = "Anda akan menganggap Tara bertanggung jawab sebagai alasan Anda pergi.",
  ui_story_5040_50401501_155_dialog_content = "Dan itu, anakku, tidak adil untukmu atau Tara. Apakah kamu mengerti sekarang?",
  ui_story_5040_50401501_156_dialog_content = "Ayah... Ibu... Maafkan aku yang begitu egois...",
  ui_story_5040_50401501_157_dialog_content = "Tapi sekarang aku bisa memberitahumu, dengan penuh kepastian, bahwa aku tahu seperti apa dunia luar, dan meski begitu... aku masih ingin menikah dengan Tara.",
  ui_story_5040_50401501_158_dialog_content = "Ya, kami telah menyaksikan bagaimana Anda berubah, jadi kami tidak lagi menentang pernikahan Anda.",
  ui_story_5040_50401501_159_dialog_content = "Kami berharap Anda berdua mendapatkan cinta dan kebahagiaan di dunia.",
  ui_story_5040_50401501_160_dialog_content = "Ini bukan hanya rumah kita lagi. Ini rumah Tara juga.",
  ui_story_5040_50401501_161_dialog_content = "Sementara petualangan Anda pasti akan membawa Anda ke setiap sudut Astra... Jangan pernah lupa bahwa Northland akan selalu ada di sini untuk menyambut Anda kembali.",
  ui_story_5040_50401501_162_dialog_content = "Ibu, Ayah... Terima kasih banyak!",
  ui_story_5040_50401501_163_dialog_content = "Mulai sekarang, kita adalah keluarga!",
  ui_story_5040_50401501_164_dialog_content = "<color=#e8d9bb>Dua hari kemudian, naik Soroz...</color>",
  ui_story_5040_50401501_165_dialog_content = "Petualangan itu pasti menghabiskan banyak waktu...",
  ui_story_5040_50401501_166_dialog_content = "Awalnya, saya hanya membawa beberapa orang dari Gurun Rediesel ke Northland... Saya tidak pernah menyangka akan bepergian ke seluruh Astra karena itu!",
  ui_story_5040_50401501_167_dialog_content = "Untung saya bisa menyelesaikan semuanya sebelum Vice dan Carleen kembali dari liburan... Saya bahkan bisa membeli pemutar rekaman mewah dengan pembayaran yang saya dapat dari Naroxel!",
  ui_story_5040_50401501_168_dialog_content = "Mereka selalu banyak membantuku, tapi kali ini aku memberi mereka kejutan sendirian!",
  ui_story_5040_50401501_169_dialog_content = "Kami kembali, PlayerName!",
  ui_story_5040_50401501_170_dialog_content = "Mooncrown Day sama sibuknya dengan tahun-tahun lainnya, tapi syukurlah semuanya tetap relatif damai tahun ini.",
  ui_story_5040_50401501_171_dialog_content = "Bagaimana keadaan saat kita pergi?",
  ui_story_5040_50401501_172_dialog_content = "Ah, sama seperti biasanya.",
  ui_story_5040_50401501_173_dialog_content = "Saya baru saja menerbangkan Soroz selama beberapa hari, dan mengalami Hari Mahkota Bulan di beberapa tempat berbeda.",
  ui_story_5040_50401501_174_dialog_content = "Saya bahkan mengambil pekerjaan dari Courier Union dan menghasilkan uang!",
  ui_story_5040_50401501_175_dialog_content = "Saya mendengarnya! Jola bertanya mengapa aku tidak bersamamu.",
  ui_story_5040_50401501_176_dialog_content = "Beberapa tentara Lumopolis juga melihatmu membantu Serikat Kurir setempat beberapa hari yang lalu. Anda sudah bekerja keras.",
  ui_story_5040_50401501_177_dialog_content = "Oh, itu bukan apa-apa, sungguh.",
  ui_story_5040_50401501_178_dialog_content = "Saya sangat sibuk!",
  ui_story_5040_50401501_179_dialog_content = "Saya mengambil pekerjaan dari Courier Union dan menghasilkan uang!",
  ui_story_5040_50401501_180_dialog_content = "Itu seharusnya menjadi perjalanan singkat, tetapi pekerjaan itu akhirnya memakan waktu beberapa hari.",
  ui_story_5040_50401501_181_dialog_content = "Saya mendengar tentang itu, ya. Anda berada di Lumopolis pada satu titik, lalu saya pikir Anda pergi ke Illumina?",
  ui_story_5040_50401501_182_dialog_content = "Kudengar kau bahkan sampai ke Rediesel Desert dan Northland! Itu pasti perjalanan yang luar biasa!",
  ui_story_5040_50401501_183_dialog_content = "Tunggu sebentar... Kenapa kalian berdua tahu kemana saja aku selama ini?!",
  ui_story_5040_50401501_184_dialog_content = "Nah, Soroz tidak terlalu sulit untuk dilewatkan... Anda menarik banyak perhatian ke mana pun Anda terbang!",
  ui_story_5040_50401501_185_dialog_content = "Saya rasa itu masuk akal...",
  ui_story_5040_50401501_186_dialog_content = "Ngomong-ngomong, saya menggunakan pembayaran untuk memberi kalian sedikit kejutan!",
  ui_story_5040_50401501_187_dialog_content = "Ta-wa—!",
  ui_story_5040_50401501_188_dialog_content = "Apakah itu pemutar rekaman dari sebelumnya?!",
  ui_story_5040_50401501_189_dialog_content = "Itu cukup mahal, jika saya ingat dengan benar.",
  ui_story_5040_50401501_190_dialog_content = "Saat kita berbelanja di Umbraton, aku ingat kalian berdua menatapnya lama sekali melalui jendela.",
  ui_story_5040_50401501_191_dialog_content = "Saya pikir kalian pasti sangat menyukainya, jadi saya mengintip harganya dan itu benar-benar mengejutkan saya.",
  ui_story_5040_50401501_192_dialog_content = "Tetapi ketika saya memikirkan tentang saat-saat Anda telah membantu saya, saya menyadari bahwa saya tidak melakukan banyak hal untuk menunjukkan penghargaan saya...",
  ui_story_5040_50401501_193_dialog_content = "Saat itulah saya memutuskan untuk membeli pemutar rekaman itu untuk Anda berdua!",
  ui_story_5040_50401501_194_dialog_content = "Saya telah melakukan pekerjaan serabutan di sana-sini, dan kali ini saya akhirnya mampu membelinya!",
  ui_story_5040_50401501_195_dialog_content = "PlayerName…",
  ui_story_5040_50401501_196_dialog_content = "Ada alasan mengapa kami menatap pemutar rekaman itu begitu lama...",
  ui_story_5040_50401501_197_dialog_content = "Carleen dan aku telah membicarakannya selama berhari-hari... Kami ingin memberimu sesuatu yang istimewa.",
  ui_story_5040_50401501_198_dialog_content = "Jadi ketika kami berdua melihat pemutar rekaman itu di Umbraton, kami langsung tahu itu adalah pilihan yang tepat!",
  ui_story_5040_50401501_199_dialog_content = "Lagi pula, orang Caelest selalu menyukai musik, bukan? Dan cara apa yang lebih baik untuk menikmatinya selain dengan pemutar rekaman berkualitas tinggi!",
  ui_story_5040_50401501_200_dialog_content = "Saat itulah kami memutuskan untuk mengumpulkan uang kami untuk membelinya untuk Anda.",
  ui_story_5040_50401501_201_dialog_content = "Itu juga alasan kami kembali bekerja untuk Mooncrown Day...",
  ui_story_5040_50401501_202_dialog_content = "Bekerja...? Tunggu, jadi kalian berdua tidak pergi berlibur?!",
  ui_story_5040_50401501_203_dialog_content = "Yap... Kami tidak ingin Anda mengetahuinya, jadi kami merahasiakannya...",
  ui_story_5040_50401501_204_dialog_content = "Tapi baru setelah kami tiba di Umbraton kami menyadari... seseorang telah membeli pemutar rekaman itu.",
  ui_story_5040_50401501_205_dialog_content = "Yang bisa kami lakukan hanyalah membeli beberapa manisan Umbraton dan beberapa buku baru sebagai hadiah.",
  ui_story_5040_50401501_206_dialog_content = "Jadi kalian berdua tidak menginginkan pemutar rekaman itu sejak awal?!",
  ui_story_5040_50401501_207_dialog_content = "Ini...",
  ui_story_5040_50401501_208_dialog_content = "Tidak apa-apa! Tentu, itu tidak terjadi seperti yang kami harapkan, tetapi pada akhirnya kami mendapatkan pemutar rekaman, bukan?",
  ui_story_5040_50401501_209_dialog_content = "Belum lagi beberapa buku baru dan beberapa makanan ringan.",
  ui_story_5040_50401501_210_dialog_content = "Ya kamu benar!",
  ui_story_5040_50401501_211_dialog_content = "Ayo, mari kita mengejar musik dan makanan ringan!"
}
return config
